# ================================================================
# FONCTIONS DE FIT POUR PICS RAMAN
# ----------------------------------------------------------------
# Profils analytiques (Gauss / Lorentz / Pseudo-Voigt) avec FWHM en
# paramètre direct (convention littérature Raman). L'amplitude A est
# la valeur au sommet (intensité au centre du pic).
#
# Pseudo-Voigt utilise la combinaison linéaire :
#   PV(x) = A * [eta * L(x; FWHM) + (1-eta) * G(x; FWHM)]
# avec eta in [0, 1] et FWHM commune aux deux composantes.
# Cette approximation est standard en spectroscopie Raman/IR
# (Thompson-Cox-Hastings est plus précise mais surchargée pour ici).
# ================================================================
# Constantes mathématiques pré-calculées
_FIT_GAUSS_FWHM_TO_SIGMA = 1.0 / (2.0 * np.sqrt(2.0 * np.log(2.0)))  # σ = FWHM × const
_FIT_GAUSS_AREA_FACTOR   = np.sqrt(np.pi / (4.0 * np.log(2.0)))       # ∫ G dx = A·FWHM·const
_FIT_LORENTZ_AREA_FACTOR = np.pi / 2.0                                # ∫ L dx = A·FWHM·π/2


def _peak_gaussian(x, center, amplitude, fwhm):
    """Profil gaussien normalisé en amplitude (A = max value at center)."""
    sigma = fwhm * _FIT_GAUSS_FWHM_TO_SIGMA
    if sigma <= 0:
        return np.zeros_like(x)
    return amplitude * np.exp(-((x - center) ** 2) / (2.0 * sigma * sigma))


def _peak_lorentzian(x, center, amplitude, fwhm):
    """Profil lorentzien normalisé en amplitude."""
    gamma = fwhm / 2.0
    if gamma <= 0:
        return np.zeros_like(x)
    return amplitude * (gamma * gamma) / ((x - center) ** 2 + gamma * gamma)


def _peak_pseudovoigt(x, center, amplitude, fwhm, eta):
    """Pseudo-Voigt : combinaison linéaire L (poids eta) + G (poids 1-eta).
    eta=1 → Lorentz pur, eta=0 → Gauss pur."""
    eta = max(0.0, min(1.0, eta))  # clamp pour stabilité numérique
    g = _peak_gaussian(x, center, 1.0, fwhm)    # amplitude unitaire ; on multiplie après
    l = _peak_lorentzian(x, center, 1.0, fwhm)
    return amplitude * (eta * l + (1.0 - eta) * g)


# ----------------------------------------------------------------
# Variantes "+ baseline linéaire" pour curve_fit.
# Le modèle complet est : profil_pur(x) + b0 + b1 * x
# Permet d'absorber la baseline résiduelle entre pics voisins
# (épaulements) sans abaisser l'amplitude du profil.
#
# Les paramètres baseline b0/b1 sont stockés mais ne contribuent
# PAS aux quantités scientifiques (FWHM, aire, R² du profil) —
# seul le profil pur compte pour l'affichage et l'aire.
# ----------------------------------------------------------------
def _peak_gaussian_bl(x, center, amplitude, fwhm, b0, b1):
    return _peak_gaussian(x, center, amplitude, fwhm) + b0 + b1 * x

def _peak_lorentzian_bl(x, center, amplitude, fwhm, b0, b1):
    return _peak_lorentzian(x, center, amplitude, fwhm) + b0 + b1 * x

def _peak_pseudovoigt_bl(x, center, amplitude, fwhm, eta, b0, b1):
    return _peak_pseudovoigt(x, center, amplitude, fwhm, eta) + b0 + b1 * x


def _peak_area_analytical(shape, amplitude, fwhm, eta=None):
    """Aire intégrée sous un profil, calculée analytiquement.
    Plus précis qu'une intégration numérique (Simpson/trapèze).

    Formules (avec A = amplitude, w = FWHM) :
      • Gauss    : A · w · √(π / (4·ln 2))
      • Lorentz  : A · w · π/2
      • PVoigt   : A · w · [η · π/2 + (1-η) · √(π / (4·ln 2))]
    """
    if amplitude <= 0 or fwhm <= 0:
        return 0.0
    if shape == 'gaussian':
        return amplitude * fwhm * _FIT_GAUSS_AREA_FACTOR
    if shape == 'lorentzian':
        return amplitude * fwhm * _FIT_LORENTZ_AREA_FACTOR
    if shape == 'pseudovoigt':
        eta_c = max(0.0, min(1.0, eta if eta is not None else 0.5))
        return amplitude * fwhm * (eta_c * _FIT_LORENTZ_AREA_FACTOR
                                     + (1.0 - eta_c) * _FIT_GAUSS_AREA_FACTOR)
    return 0.0


def _estimate_fwhm_from_curve(x, y, center, amplitude, max_search=50.0):
    """Estimation grossière de la FWHM en parcourant la courbe à droite et
    à gauche du centre, jusqu'à passer sous amplitude/2.

    Pour gérer correctement les pics qui ne sont pas des maxima globaux
    (par exemple un petit épaulement à côté d'un pic dominant), on s'arrête
    aussi quand :
      • on dépasse 'max_search' cm⁻¹ du centre (limite stricte)
      • la courbe REMONTE significativement (signe qu'on entre dans un
        autre pic voisin) avant d'avoir atteint half-amplitude

    Cas typique : clic manuel sur un épaulement à 303 cm⁻¹ avec amplitude
    0.06, alors qu'à 650 cm⁻¹ la courbe monte à 0.36. Sans cette
    protection on parcourt jusqu'à 650+ et on retourne une FWHM de plusieurs
    centaines de cm⁻¹ → fit délirant ensuite.

    Retourne une valeur strictement positive (1.0 cm⁻¹ minimum)."""
    if amplitude <= 0 or len(x) < 3:
        return 5.0
    half = amplitude / 2.0
    idx_c = int(np.argmin(np.abs(x - center)))

    # Parcours à droite : on s'arrête quand
    #   - on a passé half (idéal)
    #   - on est sorti de la zone [center, center + max_search]
    #   - la courbe REMONTE au-dessus de l'amplitude initiale (signe qu'on
    #     est entré dans un pic voisin plus grand)
    idx_r = idx_c
    while idx_r < len(x) - 1:
        if y[idx_r] <= half:
            break
        if x[idx_r] - center > max_search:
            break
        # Remontée significative : on prend ce point comme "limite"
        if y[idx_r] > 1.5 * amplitude:
            break
        idx_r += 1

    idx_l = idx_c
    while idx_l > 0:
        if y[idx_l] <= half:
            break
        if center - x[idx_l] > max_search:
            break
        if y[idx_l] > 1.5 * amplitude:
            break
        idx_l -= 1

    fwhm_est = float(x[idx_r] - x[idx_l])
    if fwhm_est < 1.0:
        fwhm_est = 5.0
    # Cap : ne jamais retourner une FWHM > 2 × max_search (= 100 cm⁻¹ par défaut)
    fwhm_est = min(fwhm_est, 2.0 * max_search)
    return fwhm_est


def _find_fit_window(x, y, center, fwhm_estimate, search_range=50.0):
    """Détermine [x_min, x_max] autour de 'center' pour fitter un pic.

    Méthode hybride :
      1. Cherche les minima locaux dans [center - search_range, center]
         (gauche) et [center, center + search_range] (droite)
      2. Si aucun minimum n'est trouvé d'un côté : fallback ±3 × FWHM_estimate

    Garantit toujours [x_min < center < x_max] avec une largeur > 0.
    """
    fallback_half = max(3.0 * fwhm_estimate, 5.0)
    x_min_default = max(float(x.min()), center - fallback_half)
    x_max_default = min(float(x.max()), center + fallback_half)

    # Recherche minima locaux à gauche
    mask_left = (x >= center - search_range) & (x <= center)
    if mask_left.sum() >= 3:
        xl = x[mask_left]
        yl = y[mask_left]
        local_min_indices = []
        for i in range(1, len(yl) - 1):
            if yl[i] <= yl[i - 1] and yl[i] <= yl[i + 1]:
                local_min_indices.append(i)
        if local_min_indices:
            x_min = float(xl[local_min_indices[-1]])
        else:
            x_min = x_min_default
    else:
        x_min = x_min_default

    # Recherche minima locaux à droite
    mask_right = (x >= center) & (x <= center + search_range)
    if mask_right.sum() >= 3:
        xr = x[mask_right]
        yr = y[mask_right]
        local_min_indices = []
        for i in range(1, len(yr) - 1):
            if yr[i] <= yr[i - 1] and yr[i] <= yr[i + 1]:
                local_min_indices.append(i)
        if local_min_indices:
            x_max = float(xr[local_min_indices[0]])
        else:
            x_max = x_max_default
    else:
        x_max = x_max_default

    if x_min >= center:
        x_min = max(float(x.min()), center - max(2.0, fwhm_estimate))
    if x_max <= center:
        x_max = min(float(x.max()), center + max(2.0, fwhm_estimate))
    if x_max - x_min < 2.0:
        x_min, x_max = center - 1.0, center + 1.0

    return x_min, x_max


def _fit_single_peak(x_full, y_full, peak, use_baseline=True):
    """Lance scipy.optimize.curve_fit sur un pic isolé, dans sa fenêtre.

    Si use_baseline=True (recommandé pour spectres avec épaulements),
    le modèle est : profil_pur(x) + b0 + b1·x. Cela évite que le profil
    soit "abaissé" pour absorber la baseline résiduelle entre pics
    voisins. b0 et b1 sont stockés mais n'influent pas sur l'aire ni
    le R² du profil pur.

    Retourne un dict 'fitted' en cas de succès. Ne renvoie JAMAIS None
    si le fit a numériquement convergé : à la place, on remplit
    peak['fit_warning'] avec un message si le résultat est suspect, et
    le tableau affichera ⚠ (option B).

    Renvoie None uniquement si :
      - scipy non dispo
      - fenêtre trop étroite (<4 points)
      - curve_fit lève une exception (pas de convergence)
    """
    try:
        from scipy.optimize import curve_fit
    except ImportError:
        peak['fit_error'] = "scipy non disponible"
        peak['fit_warning'] = None
        return None

    shape = peak.get('shape', 'pseudovoigt')
    center0 = float(peak['position'])
    amp0    = max(float(peak['height']), 1e-6)

    fwhm0 = _estimate_fwhm_from_curve(x_full, y_full, center0, amp0)

    if peak.get('window_xmin') is not None and peak.get('window_xmax') is not None:
        x_min = float(peak['window_xmin'])
        x_max = float(peak['window_xmax'])
    else:
        x_min, x_max = _find_fit_window(x_full, y_full, center0, fwhm0)
        # Garantie : la fenêtre doit être au moins 4 × FWHM_estimée
        min_width = 4.0 * fwhm0
        if (x_max - x_min) < min_width:
            half_extra = (min_width - (x_max - x_min)) / 2.0
            x_min = max(float(x_full.min()), x_min - half_extra)
            x_max = min(float(x_full.max()), x_max + half_extra)

    mask = (x_full >= x_min) & (x_full <= x_max)
    if mask.sum() < 4:
        peak['fit_error'] = "fenêtre trop étroite (<4 points)"
        peak['fit_warning'] = None
        return None
    xf = x_full[mask]
    yf = y_full[mask]

    fwhm_max = max(x_max - x_min, 2.0)
    # === Bornes sur le centre : RESTREINTES autour de center0 ===
    # Plutôt que d'autoriser center ∈ [x_min, x_max] (toute la fenêtre),
    # on contraint center à rester dans une bande symétrique autour de la
    # position initiale du clic / détection : ± max(2*FWHM_estimée, 5 cm⁻¹).
    # Ainsi curve_fit ne peut pas migrer vers un pic voisin même si la
    # fenêtre de fit englobe son flanc.
    center_drift_max = max(2.0 * fwhm0, 5.0)
    center_lo = max(x_min, center0 - center_drift_max)
    center_hi = min(x_max, center0 + center_drift_max)
    if center_hi <= center_lo:
        # Cas pathologique (fenêtre très étroite) — fallback large
        center_lo, center_hi = x_min, x_max

    bounds_lower = [center_lo, 0.0,        0.5]
    bounds_upper = [center_hi, 2.0 * amp0, fwhm_max]
    # Clamp p0 dans les bornes (curve_fit lève ValueError sinon)
    fwhm0_clamped = min(max(fwhm0, 0.5 + 1e-6), fwhm_max - 1e-6)
    center0_clamped = min(max(center0, center_lo + 1e-6), center_hi - 1e-6)
    amp0_clamped = min(max(amp0, 1e-6), 2.0 * amp0 - 1e-6)
    p0 = [center0_clamped, amp0_clamped, fwhm0_clamped]

    # Ajout des paramètres selon la forme
    if shape == 'pseudovoigt':
        # eta in [0, 1], guess 0.5
        bounds_lower.append(0.0)
        bounds_upper.append(1.0)
        p0.append(0.5)
        n_peak_params = 4
    elif shape in ('gaussian', 'lorentzian'):
        n_peak_params = 3
    else:
        peak['fit_error'] = f"forme inconnue : {shape}"
        peak['fit_warning'] = None
        return None

    # Ajout des paramètres baseline si activée
    if use_baseline:
        # b0 (offset) et b1 (slope) : bornes larges pour ne pas contraindre
        # b0 ∈ [-2, 2] (vu que les courbes sont normalisées [0,1])
        # b1 ∈ [-0.01, 0.01] (pente faible : 0.01 × 1000 cm⁻¹ = 10 unités)
        bounds_lower.extend([-2.0, -0.01])
        bounds_upper.extend([ 2.0,  0.01])
        # Init : pieds de fenêtre comme estimation initiale de b0 (moyenne
        # des intensités au début et fin de la window)
        n_edge = max(1, len(yf) // 10)
        b0_guess = float((yf[:n_edge].mean() + yf[-n_edge:].mean()) / 2.0)
        b0_guess = min(max(b0_guess, -1.99), 1.99)
        p0.extend([b0_guess, 0.0])

    # Sélection du modèle (avec ou sans baseline)
    if use_baseline:
        if shape == 'gaussian':     model = _peak_gaussian_bl
        elif shape == 'lorentzian': model = _peak_lorentzian_bl
        elif shape == 'pseudovoigt':model = _peak_pseudovoigt_bl
    else:
        if shape == 'gaussian':     model = _peak_gaussian
        elif shape == 'lorentzian': model = _peak_lorentzian
        elif shape == 'pseudovoigt':model = _peak_pseudovoigt

    try:
        popt, pcov = curve_fit(model, xf, yf, p0=p0,
                                 bounds=(bounds_lower, bounds_upper),
                                 maxfev=5000)
    except Exception as e:
        peak['fit_error'] = f"curve_fit a échoué : {type(e).__name__}"
        peak['fit_warning'] = None
        return None

    # Extraire les paramètres et leurs erreurs (1σ depuis la covariance)
    perr = np.sqrt(np.diag(pcov)) if np.all(np.isfinite(pcov)) else np.full(len(popt), np.nan)

    # Décomposer popt selon la structure
    peak_params = popt[:n_peak_params]
    peak_errs   = perr[:n_peak_params]
    if use_baseline:
        b0, b1 = float(popt[-2]), float(popt[-1])
        b0_err = float(perr[-2]) if np.isfinite(perr[-2]) else None
        b1_err = float(perr[-1]) if np.isfinite(perr[-1]) else None
    else:
        b0, b1 = 0.0, 0.0
        b0_err = b1_err = None

    if shape == 'pseudovoigt':
        center, amplitude, fwhm, eta = peak_params
        c_err, a_err, f_err, e_err = peak_errs
    else:
        center, amplitude, fwhm = peak_params
        c_err, a_err, f_err = peak_errs
        eta = None
        e_err = None

    # === R² calculé sur le modèle COMPLET (profil + baseline si active) ===
    y_fit_full = model(xf, *popt)
    ss_res = float(np.sum((yf - y_fit_full) ** 2))
    ss_tot = float(np.sum((yf - np.mean(yf)) ** 2))
    if ss_tot > 1e-15:
        r2 = 1.0 - ss_res / ss_tot
    else:
        r2 = 0.0

    area = _peak_area_analytical(shape, float(amplitude), float(fwhm),
                                    eta=float(eta) if eta is not None else None)

    # === Sanity checks → option B (warning, pas rejet) ===
    # On accepte le fit même si les seuils sont dépassés, mais on remplit
    # peak['fit_warning'] qui sera affiché en orange dans le tableau.
    drift = abs(float(center) - center0)
    fit_window_width = x_max - x_min
    warnings = []
    # Drift : on compare à la FWHM initiale plutôt qu'à la fenêtre, car
    # la fenêtre peut être beaucoup plus large que le pic (épaulement).
    # Seuil : drift > 1.5× FWHM_estimée → suspect.
    if drift > 1.5 * fwhm0:
        warnings.append(f"centre dérivé de {drift:.1f} cm⁻¹ "
                          f"(>1.5× FWHM estimée {fwhm0:.1f})")
    if float(fwhm) > 0.85 * fit_window_width:
        warnings.append(f"FWHM ({fwhm:.1f}) ≥85% de la fenêtre")
    if r2 < 0.30:
        warnings.append(f"R² très bas ({r2:.2f})")
    # Le R² négatif est un cas particulièrement pathologique (le fit est
    # PIRE qu'une simple moyenne) — toujours marquer comme suspect même
    # si pas dans les autres critères.
    if r2 < 0.0:
        warnings.append(f"R² négatif ({r2:.3f}) — fit pathologique")

    peak['fit_warning'] = " ; ".join(warnings) if warnings else None
    peak['fit_error'] = None  # convergence OK, pas d'erreur dure

    return {
        'center':        float(center),
        'center_err':    float(c_err) if np.isfinite(c_err) else None,
        'amplitude':     float(amplitude),
        'amplitude_err': float(a_err) if np.isfinite(a_err) else None,
        'fwhm':          float(fwhm),
        'fwhm_err':      float(f_err) if np.isfinite(f_err) else None,
        'eta':           float(eta) if eta is not None else None,
        'eta_err':       float(e_err) if (e_err is not None and np.isfinite(e_err)) else None,
        'r2':            float(r2),
        'area':          float(area),
        'window_xmin':   float(x_min),
        'window_xmax':   float(x_max),
        # Baseline locale (Q1 — toggle utilisateur dans la fenêtre Fit)
        'baseline_b0':   b0,
        'baseline_b1':   b1,
        'baseline_b0_err': b0_err,
        'baseline_b1_err': b1_err,
        'use_baseline':  bool(use_baseline),
    }


def _eval_peak_profile(peak, x_array):
    """Évalue le profil PUR fitté (sans baseline) d'un pic.
    Retourne un array de zéros si le pic n'a pas été fitté."""
    fitted = peak.get('fitted')
    if not fitted:
        return np.zeros_like(x_array)
    shape = peak.get('shape', 'pseudovoigt')
    if shape == 'gaussian':
        return _peak_gaussian(x_array, fitted['center'],
                                fitted['amplitude'], fitted['fwhm'])
    if shape == 'lorentzian':
        return _peak_lorentzian(x_array, fitted['center'],
                                  fitted['amplitude'], fitted['fwhm'])
    if shape == 'pseudovoigt':
        return _peak_pseudovoigt(x_array, fitted['center'],
                                   fitted['amplitude'], fitted['fwhm'],
                                   fitted.get('eta', 0.5) or 0.5)
    return np.zeros_like(x_array)


def _eval_peak_baseline(peak, x_array):
    """Évalue la baseline locale b0 + b1·x d'un pic fitté.
    Retourne zéro si pas de baseline (use_baseline=False ou pic non fitté)."""
    fitted = peak.get('fitted')
    if not fitted or not fitted.get('use_baseline'):
        return np.zeros_like(x_array)
    b0 = fitted.get('baseline_b0', 0.0)
    b1 = fitted.get('baseline_b1', 0.0)
    return b0 + b1 * x_array


# ================================================================
# 4b.1 — ANALYSE DE MATCH (manuel : 1 ref ↔ spectre fitté)
# ----------------------------------------------------------------
# Algorithme de matching pic-à-pic entre les pics fittés du spectre
# étudié et les pics détectés dans une référence RRUFF.
#
# Le matching est :
#   - 1-to-1 strict (un pic RRUFF ne matche qu'avec un seul pic du fit)
#   - glouton : on prend les paires les plus proches en premier
#   - tolérance adaptative : max(5 cm⁻¹, 3·σ_fit) pour chaque pic fitté
#
# Scores produits :
#   - M1 (coverage)  = N_match / N_fit
#   - M2 (signature) = N_match / N_rruff
#   - M3 (F1-score)  = 2·M1·M2 / (M1+M2)
#   - Δν moyen       = signe = offset systématique suggéré
# ================================================================

def _detect_peaks_in_reference(x_ref, y_ref, prominence=0.05, distance=5):
    """Détecte les pics dans une courbe RRUFF.
    Normalise [0, 1] avant détection pour que le seuil de prominence
    soit cohérent quel que soit l'ordre de grandeur du fichier.

    Retourne une liste de dicts {'position': float, 'height': float}
    triés par position croissante.
    """
    try:
        from scipy.signal import find_peaks
    except ImportError:
        return []
    if x_ref is None or y_ref is None or len(y_ref) < 5:
        return []
    x_ref = np.asarray(x_ref, dtype=float)
    y_ref = np.asarray(y_ref, dtype=float)
    y_max = float(y_ref.max()) if y_ref.size > 0 else 1.0
    if y_max < 1e-12:
        return []
    y_norm = y_ref / y_max
    try:
        idx, props = find_peaks(y_norm, prominence=prominence,
                                  distance=distance)
    except Exception:
        return []
    peaks = []
    for i in idx:
        peaks.append({
            'position': float(x_ref[i]),
            'height':   float(y_norm[i]),  # normalisé [0, 1]
        })
    peaks.sort(key=lambda p: p['position'])
    return peaks


def _match_peaks(fit_peaks, ref_peaks, offset=0.0, tol_floor=5.0,
                   tol_sigma_factor=3.0):
    """Matching pic-à-pic 1-to-1 strict, glouton.

    Args:
      fit_peaks : list de dicts du fit, avec au minimum
                    {'fitted': {'center', 'center_err'}} pour calculer
                    la tolérance adaptative
      ref_peaks : list de dicts de la ref, {'position', 'height'}
      offset    : offset Δ appliqué aux positions de la ref
                    (pos_ref_effective = pos_ref + offset)
      tol_floor : tolérance plancher en cm⁻¹ (défaut 5)
      tol_sigma_factor : multiplicateur de σ_fit (défaut 3)

    Retourne un dict :
      {
        'matches': list de tuples (idx_fit, idx_ref, dnu, tol),
        'unmatched_fit':  list d'indices de fit_peaks non-matchés,
        'unmatched_ref':  list d'indices de ref_peaks non-matchés,
        'offset_used':    float (recopie de offset)
      }

    Algo : on calcule toutes les paires (i, j, |Δν|) candidates dans
    la tolérance, puis on les trie par |Δν| croissant et on prend
    gloutonnement (1-to-1 strict).
    """
    n_fit = len(fit_peaks)
    n_ref = len(ref_peaks)
    if n_fit == 0 or n_ref == 0:
        return {
            'matches': [],
            'unmatched_fit': list(range(n_fit)),
            'unmatched_ref': list(range(n_ref)),
            'offset_used': float(offset),
        }

    # Tolérance par pic fitté (basée sur σ_fit du centre, fallback floor)
    tolerances = []
    for p in fit_peaks:
        fitted = p.get('fitted')
        if fitted and fitted.get('center_err') is not None:
            sigma = float(fitted['center_err'])
            if not np.isfinite(sigma) or sigma <= 0:
                sigma = tol_floor / tol_sigma_factor
            tol = max(tol_floor, tol_sigma_factor * sigma)
        else:
            tol = tol_floor
        tolerances.append(tol)

    # Construire toutes les paires candidates (i, j, |Δν|) dans la tolérance
    candidates = []
    for i, p_fit in enumerate(fit_peaks):
        fitted = p_fit.get('fitted')
        if fitted is None:
            continue  # un pic non fitté n'a pas de center précis
        c_fit = float(fitted['center'])
        tol_i = tolerances[i]
        for j, p_ref in enumerate(ref_peaks):
            c_ref_eff = float(p_ref['position']) + float(offset)
            dnu = c_ref_eff - c_fit  # signé : ref - fit
            if abs(dnu) <= tol_i:
                candidates.append((i, j, dnu, tol_i))

    # Tri par |Δν| croissant pour le matching glouton
    candidates.sort(key=lambda c: abs(c[2]))

    matches = []
    used_fit = set()
    used_ref = set()
    for (i, j, dnu, tol) in candidates:
        if i in used_fit or j in used_ref:
            continue
        matches.append((i, j, dnu, tol))
        used_fit.add(i)
        used_ref.add(j)

    unmatched_fit = [i for i in range(n_fit) if i not in used_fit]
    unmatched_ref = [j for j in range(n_ref) if j not in used_ref]

    return {
        'matches': matches,
        'unmatched_fit': unmatched_fit,
        'unmatched_ref': unmatched_ref,
        'offset_used': float(offset),
    }


def _compute_match_scores(match_result, fit_peaks, ref_peaks):
    """Calcule les scores M1, M2, M3 + statistiques Δν.

    Retourne un dict :
      {
        'M1_coverage':  float in [0, 1],
        'M2_signature': float in [0, 1],
        'M3_f1':        float in [0, 1],
        'dnu_mean':     float (cm⁻¹, signé),
        'dnu_std':      float,
        'n_match':      int,
        'n_fit':        int,
        'n_ref':        int,
      }
    """
    n_match = len(match_result['matches'])
    # On compte uniquement les pics fittés (avec 'fitted' non-None) car
    # un pic init non fitté ne pouvait pas matcher dans _match_peaks
    n_fit_eligible = sum(1 for p in fit_peaks if p.get('fitted'))
    n_ref = len(ref_peaks)

    M1 = (n_match / n_fit_eligible) if n_fit_eligible > 0 else 0.0
    M2 = (n_match / n_ref) if n_ref > 0 else 0.0
    if (M1 + M2) > 1e-12:
        M3 = 2.0 * M1 * M2 / (M1 + M2)
    else:
        M3 = 0.0

    dnus = [m[2] for m in match_result['matches']]
    dnu_mean = float(np.mean(dnus)) if dnus else 0.0
    dnu_std = float(np.std(dnus)) if len(dnus) > 1 else 0.0

    return {
        'M1_coverage':  float(M1),
        'M2_signature': float(M2),
        'M3_f1':        float(M3),
        'dnu_mean':     dnu_mean,
        'dnu_std':      dnu_std,
        'n_match':      int(n_match),
        'n_fit':        int(n_fit_eligible),
        'n_ref':        int(n_ref),
    }


def _optimize_offset_for_match(fit_peaks, ref_peaks,
                                  offset_range=(-25.0, 25.0),
                                  step=0.5):
    """Scanne l'offset Δ ∈ [-25, +25] cm⁻¹ pour maximiser le score M3
    (F1) du matching. Retourne (offset_optimal, score_M3, scan_results).

    scan_results = list de tuples (offset, M1, M2, M3) pour visualisation
    optionnelle d'un graphe de score vs offset.
    """
    if not fit_peaks or not ref_peaks:
        return 0.0, 0.0, []
    offsets = np.arange(offset_range[0], offset_range[1] + step, step)
    best_offset = 0.0
    best_score = -1.0
    scan = []
    for off in offsets:
        m = _match_peaks(fit_peaks, ref_peaks, offset=float(off))
        s = _compute_match_scores(m, fit_peaks, ref_peaks)
        scan.append((float(off), s['M1_coverage'], s['M2_signature'],
                       s['M3_f1']))
        # Tie-break : à F1 égal, on préfère l'offset le plus proche de 0
        if (s['M3_f1'] > best_score + 1e-9 or
            (abs(s['M3_f1'] - best_score) < 1e-9 and
             abs(off) < abs(best_offset))):
            best_score = s['M3_f1']
            best_offset = float(off)
    return float(best_offset), float(best_score), scan


def _scan_database_for_match(fit_peaks, lib_path, file_to_mineral=None,
                                progress_callback=None, abort_flag=None,
                                offset_search=True):
    """Scanne tous les fichiers .txt d'un dossier RRUFF, calcule le score
    de match contre fit_peaks, et retourne une liste de candidats agrégés
    par minéral (Q4 option b).

    Args:
      fit_peaks         : list de pics fittés du spectre étudié
      lib_path          : str, chemin du dossier RRUFF à scanner
      file_to_mineral   : dict optionnel {fname: mineral} pour éviter le
                            re-parsing. Si None, on extrait le nom du
                            minéral depuis chaque filename (1er token).
      progress_callback : callable(i, n, current_file) appelé à chaque
                            fichier traité (pour barre de progression UI)
      abort_flag        : list de 1 élément [bool] que l'UI peut mettre
                            à True pour annuler le scan.
      offset_search     : bool, si True (défaut), on optimise l'offset Δ
                            par scan pour chaque ref. Sinon offset=0.

    Retourne une list de dicts triés par M3 décroissant :
      [
        {
          'mineral': str,
          'best_filename': str,    # fichier RRUFF qui donne le meilleur M3
          'all_files': list[str],  # tous les fichiers du minéral scannés
          'M1': float, 'M2': float, 'M3': float,
          'dnu_mean': float, 'dnu_std': float,
          'offset_auto': float,
          'n_match': int, 'n_fit': int, 'n_ref': int,
          'n_files_scanned': int,
        }, ...
      ]
    """
    # Pas de pic fitté → pas de scan
    fit_peaks_eligible = [p for p in fit_peaks if p.get('fitted')]
    if not fit_peaks_eligible:
        return []

    # Lister les fichiers
    if not os.path.isdir(lib_path):
        return []
    try:
        all_files = [f for f in os.listdir(lib_path)
                       if os.path.isfile(os.path.join(lib_path, f))
                       and f.lower().endswith(('.txt', '.csv'))]
    except Exception:
        return []
    all_files.sort()
    n_total = len(all_files)
    if n_total == 0:
        return []

    # Map fichier → minéral (depuis le filename si pas fourni)
    if file_to_mineral is None:
        file_to_mineral = {}
        for fname in all_files:
            base = os.path.splitext(fname)[0]
            parts = base.replace('__', '_').split('_')
            file_to_mineral[fname] = parts[0].lower() if parts else 'inconnu'

    # Pour chaque fichier : calculer son score
    # On collecte tout par minéral pour faire l'agrégation à la fin
    by_mineral = {}  # mineral → list de dicts {filename, scores, offset, ...}

    for i, fname in enumerate(all_files):
        # Vérifier annulation
        if abort_flag and abort_flag[0]:
            break
        if progress_callback is not None:
            try:
                progress_callback(i, n_total, fname)
            except Exception:
                pass
        full_path = os.path.join(lib_path, fname)
        # Charger le spectre RRUFF
        try:
            xr, yr = _load_spectrum_safe(full_path)
        except Exception:
            continue
        if xr is None or yr is None or len(xr) < 5:
            continue
        # Détecter les pics RRUFF
        ref_peaks = _detect_peaks_in_reference(xr, yr)
        if not ref_peaks:
            # Aucun pic détecté → score = 0, on saute
            continue
        # Optimiser l'offset (ou pas)
        if offset_search:
            best_off, _best_M3, _scan = _optimize_offset_for_match(
                fit_peaks_eligible, ref_peaks)
        else:
            best_off = 0.0
        # Match final avec cet offset
        m = _match_peaks(fit_peaks_eligible, ref_peaks, offset=best_off)
        scores = _compute_match_scores(m, fit_peaks_eligible, ref_peaks)
        mineral = file_to_mineral.get(fname, 'inconnu')
        by_mineral.setdefault(mineral, []).append({
            'filename':    fname,
            'offset':      best_off,
            'M1':          scores['M1_coverage'],
            'M2':          scores['M2_signature'],
            'M3':          scores['M3_f1'],
            'dnu_mean':    scores['dnu_mean'],
            'dnu_std':     scores['dnu_std'],
            'n_match':     scores['n_match'],
            'n_fit':       scores['n_fit'],
            'n_ref':       scores['n_ref'],
        })

    # Agrégation par minéral : on prend le meilleur fichier (par M3)
    # mais on conserve TOUS les fichiers comme 'variants' pour permettre
    # à l'UI d'afficher les variantes (Option B 4b.4).
    candidates = []
    for mineral, results in by_mineral.items():
        if not results:
            continue
        # Tri par M3 décroissant pour prendre le meilleur
        results.sort(key=lambda r: -r['M3'])
        best = results[0]
        candidates.append({
            'mineral':         mineral,
            'best_filename':   best['filename'],
            'all_files':       [r['filename'] for r in results],
            'variants':        results,  # liste complète {filename, M1, M2, M3, ...}
            'M1':              best['M1'],
            'M2':              best['M2'],
            'M3':              best['M3'],
            'dnu_mean':        best['dnu_mean'],
            'dnu_std':         best['dnu_std'],
            'offset_auto':     best['offset'],
            'n_match':         best['n_match'],
            'n_fit':           best['n_fit'],
            'n_ref':           best['n_ref'],
            'n_files_scanned': len(results),
        })
    # Tri final par M3 décroissant
    candidates.sort(key=lambda c: -c['M3'])
    return candidates


def _load_spectrum_safe(path):
    """Wrapper safe autour de load_spectrum() (lui-même défini plus bas
    dans le fichier). Importé tardivement via globals() pour éviter
    la dépendance d'ordre."""
    try:
        # load_spectrum est défini plus bas dans le module ; on y accède
        # via le namespace global au moment de l'appel (lazy lookup).
        return globals()['load_spectrum'](path)
    except Exception:
        return None, None


# ----------------------------------------------------------------
# Cache persistant des pics RRUFF (Option G — 4b.4)
# ----------------------------------------------------------------
# Format du cache (JSON, dans <lib_path>/_pic_cache.json) :
#   {
#     "_meta": {
#       "version": 1,                         # bump si algo change
#       "algo":    "find_peaks_p0.05_d5",     # tag descriptif
#       "created_at": "2026-04-29T14:32:00",
#     },
#     "files": {
#       "albite__R040068__Raman__532__1.txt": {
#         "mtime": 1761828442.123,
#         "size":  4521,
#         "peaks": [{"position": 290.5, "height": 0.6, ...}, ...],
#       },
#       ...
#     }
#   }
# Une entrée est valide si mtime+size matchent le fichier disque (Q3 d).
# Si _meta.version diffère, tout le cache est invalidé (Q4).
# ----------------------------------------------------------------

PIC_CACHE_FILENAME = "_pic_cache.json"
PIC_CACHE_VERSION = 1
PIC_CACHE_ALGO_TAG = "find_peaks_p0.05_d5"


def _pic_cache_path(lib_path):
    """Chemin du fichier cache pour un dossier de database donné."""
    return os.path.join(lib_path, PIC_CACHE_FILENAME)


def _load_pic_cache(lib_path):
    """Charge le cache des pics depuis <lib_path>/_pic_cache.json.

    Retourne un dict { 'files': {fname: {mtime, size, peaks}}, 'meta': {...} }.
    Si le fichier n'existe pas ou si la version ne correspond pas, retourne
    un cache vide (ce qui force la re-détection complète au prochain scan)."""
    cache_path = _pic_cache_path(lib_path)
    empty_cache = {
        '_meta': {
            'version':    PIC_CACHE_VERSION,
            'algo':       PIC_CACHE_ALGO_TAG,
            'created_at': datetime.datetime.now().isoformat(timespec='seconds'),
        },
        'files': {},
    }
    if not os.path.isfile(cache_path):
        return empty_cache
    try:
        with open(cache_path, 'r', encoding='utf-8') as f:
            data = json.load(f)
    except Exception:
        return empty_cache
    # Vérifier version (Q4 — si l'algo change, on invalide tout)
    meta = data.get('_meta', {})
    if not isinstance(meta, dict) or meta.get('version') != PIC_CACHE_VERSION:
        return empty_cache
    # Vérifier structure de base
    if not isinstance(data.get('files'), dict):
        return empty_cache
    return data


def _save_pic_cache(lib_path, cache):
    """Sauvegarde le cache des pics. Ignore les erreurs (le cache n'est
    qu'une optimisation, pas critique).

    Sécurité : on évite de planter si le dossier est en lecture seule."""
    try:
        cache_path = _pic_cache_path(lib_path)
        # Mise à jour du timestamp meta
        if '_meta' not in cache:
            cache['_meta'] = {}
        cache['_meta']['version'] = PIC_CACHE_VERSION
        cache['_meta']['algo'] = PIC_CACHE_ALGO_TAG
        cache['_meta']['saved_at'] = datetime.datetime.now().isoformat(
            timespec='seconds')
        with open(cache_path, 'w', encoding='utf-8') as f:
            json.dump(cache, f, indent=1)
        return True
    except Exception:
        return False


def _get_cached_or_detect_peaks(file_path, cache):
    """Retourne (peaks, was_cached, valid_entry_dict).

    - Si le fichier est dans le cache ET mtime+size correspondent (Q3 d) :
      on retourne les pics du cache, was_cached=True, valid_entry=l'entrée.
    - Sinon : on lit le spectre, on détecte les pics, et on met à jour
      le cache. was_cached=False.

    L'appelant est responsable d'appeler _save_pic_cache() à la fin pour
    persister les modifications (sinon le cache reste en mémoire seulement)."""
    fname = os.path.basename(file_path)
    try:
        st = os.stat(file_path)
        cur_mtime = float(st.st_mtime)
        cur_size = int(st.st_size)
    except OSError:
        return [], False, None

    files_cache = cache.setdefault('files', {})
    entry = files_cache.get(fname)
    if isinstance(entry, dict):
        cached_mtime = entry.get('mtime')
        cached_size = entry.get('size')
        # Tolérance flottante minime sur mtime (filesystems FAT ont précision 2s)
        if (cached_size == cur_size
                and cached_mtime is not None
                and abs(float(cached_mtime) - cur_mtime) < 1.0):
            cached_peaks = entry.get('peaks', [])
            if isinstance(cached_peaks, list):
                return cached_peaks, True, entry

    # Cache miss ou entrée invalide → détection
    try:
        xr, yr = globals()['load_spectrum'](file_path)
    except Exception:
        xr, yr = None, None
    if xr is None or yr is None or len(xr) < 5:
        return [], False, None
    peaks = _detect_peaks_in_reference(xr, yr)
    # Mettre à jour le cache (en mémoire)
    files_cache[fname] = {
        'mtime': cur_mtime,
        'size':  cur_size,
        'peaks': peaks,
    }
    return peaks, False, files_cache[fname]


def _clear_pic_cache(lib_path):
    """Supprime le fichier cache du dossier donné. Retourne True si
    suppression réussie ou si le fichier n'existait pas."""
    cache_path = _pic_cache_path(lib_path)
    if not os.path.isfile(cache_path):
        return True
    try:
        os.remove(cache_path)
        return True
    except OSError:
        return False


# ----------------------------------------------------------------
# Attribution des modes diagnostiques (Option E — 4b.4)
# ----------------------------------------------------------------
# Pour un pic Raman observé d'un minéral identifié, on cherche dans
# RAMAN_DB[mineral]['pics'] le mode vibrationnel le plus proche en
# position, dans une tolérance donnée. Le mode est dit "diagnostique"
# si son intensité relative dans la DB est >= 0.5 (Q1, cohérent avec
# le seuil 'main peaks' utilisé ailleurs dans le code).
#
# Format DB : RAMAN_DB[mineral]['pics'] = liste de tuples (pos, label, rel)
#   - pos    : position du mode en cm-1
#   - label  : description LaTeX (ex: "$E_g^{(1)}$", "T-O-T sym")
#   - rel    : intensité relative 0..1 (1.0 = pic principal)

DIAGNOSTIC_REL_THRESHOLD = 0.5  # Q1 : seuil intensité relative pour
                                  # qu'un mode soit dit 'diagnostique'


def _get_diagnostic_mode_for_peak(mineral, peak_position, tolerance=5.0):
    """Cherche le mode vibrationnel correspondant à un pic observé.

    Args:
      mineral       : str, nom du minéral (clé dans RAMAN_DB)
      peak_position : float, position du pic observé (cm-1, déjà
                        offset-corrigé pour matcher la DB)
      tolerance     : float, tolérance en cm-1 pour la correspondance

    Retourne un dict {label, position, rel, is_diagnostic, dnu}
    si un mode est trouvé dans la tolérance, sinon None.

    Q4 : si plusieurs modes dans la tolérance, on prend le PLUS
    PROCHE en position. Plus rigoureux scientifiquement qu'un
    arbitraire 'premier de la liste'."""
    if not mineral:
        return None
    info = RAMAN_DB.get(mineral.strip().lower())
    if not info:
        return None
    pics_db = info.get('pics', [])
    if not pics_db:
        return None
    # Chercher le mode le plus proche dans la tolérance
    best = None
    best_dist = float('inf')
    for entry in pics_db:
        # entry peut être (pos, label, rel) ou (pos, label) sans rel
        try:
            if len(entry) >= 3:
                pos_db, label_db, rel_db = entry[0], entry[1], entry[2]
            else:
                pos_db, label_db = entry[0], entry[1]
                rel_db = 1.0  # défaut conservateur
        except (TypeError, IndexError):
            continue
        dist = abs(float(pos_db) - float(peak_position))
        if dist <= tolerance and dist < best_dist:
            best = {
                'label':         (label_db or '').strip(),
                'position':      float(pos_db),
                'rel':           float(rel_db),
                'is_diagnostic': float(rel_db) >= DIAGNOSTIC_REL_THRESHOLD,
                'dnu':           float(peak_position) - float(pos_db),
            }
            best_dist = dist
    return best


def _format_mode_tooltip(mineral, mode_info, pos_fit=None,
                            pos_ref_observed=None, status='matched'):
    """Construit le texte multi-ligne du tooltip pour un pic (Option H,
    contenu γ — riche).

    Args:
      mineral           : str, nom du minéral identifié
      mode_info         : dict retourné par _get_diagnostic_mode_for_peak,
                            ou None si pas d'attribution
      pos_fit           : float optionnel, position fittée du pic dans le
                            spectre étudié (pour les pics matched)
      pos_ref_observed  : float optionnel, position du pic RRUFF observé
                            (avec offset déjà appliqué pour matched ; sans
                            offset pour ref_only — peu importe ici)
      status            : 'matched', 'unmatched', ou 'ref_only'

    Retourne une string multi-ligne prête à afficher dans un tooltip.
    Retourne None si aucune info utile à afficher (cas où mode_info=None
    ET status=unmatched : on ne peut rien dire d'intéressant)."""
    if mode_info is None:
        if status == 'unmatched' and pos_fit is not None:
            # Pas d'attribution mais on peut quand même donner une
            # info contextuelle utile
            return (f"{t('tooltip.unmatched_header')}\n"
                      f"─────────────────\n"
                      f"{t('tooltip.fitted_position')} : {pos_fit:.2f} cm⁻¹\n"
                      f"\n"
                      f"{t('tooltip.unmatched_explanation')}")
        return None

    # Header — type de mode
    if mode_info['is_diagnostic']:
        header = t('tooltip.header_diagnostic')
    else:
        header = t('tooltip.header_secondary')

    # Section spéciale pour les modes ref_only (théoriques non-observés)
    if status == 'ref_only':
        header = (t('tooltip.header_ref_diagnostic')
                    if mode_info['is_diagnostic']
                    else t('tooltip.header_ref_secondary'))

    label_unicode = latex_to_unicode(mode_info['label']) or t('tooltip.no_label')
    pos_db = mode_info['position']
    rel = mode_info['rel']
    diag_marker = (t('tooltip.diagnostic') if mode_info['is_diagnostic']
                      else t('tooltip.non_diagnostic'))

    lines = [
        header,
        '─────────────────────────────────',
        f"{t('tooltip.label')} : {label_unicode}",
        f"{t('tooltip.mineral')} : {mineral.capitalize() if mineral else '?'}",
        f"{t('tooltip.theoretical_position')} : {pos_db:.2f} cm⁻¹",
    ]
    if pos_ref_observed is not None and status == 'matched':
        lines.append(
            f"{t('tooltip.observed_rruff_position')} : {pos_ref_observed:.2f} cm⁻¹")
    if pos_fit is not None and status == 'matched':
        lines.append(
            f"{t('tooltip.fitted_position')} : {pos_fit:.2f} cm⁻¹")
        # Δν observé/théorique = pos fit - pos théorique DB
        dnu_obs_theo = pos_fit - pos_db
        lines.append(
            f"{t('tooltip.dnu_obs_theo')} : {dnu_obs_theo:+.2f} cm⁻¹")
    lines.append(
        f"{t('tooltip.relative_intensity')} : {rel:.2f} ({diag_marker}, "
        f"{t('tooltip.threshold')} ≥ {DIAGNOSTIC_REL_THRESHOLD:.2f})")
    if status == 'ref_only':
        lines.append('')
        lines.append(t('tooltip.ref_only_warning_l1'))
        lines.append(t('tooltip.ref_only_warning_l2'))
    return '\n'.join(lines)


# ----------------------------------------------------------------
# Export multi-format des figures du rapport (Option C bis)
# ----------------------------------------------------------------
HI_RES_DPI = 600   # standard publication scientifique
HI_RES_FORMATS = ('pdf', 'png', 'svg')


def _save_fig_multiformat(fig, base_path_no_ext, formats=('pdf',),
                            dpi=HI_RES_DPI):
    """Sauvegarde une figure matplotlib dans plusieurs formats à haute
    résolution.

    Args:
      fig               : matplotlib Figure
      base_path_no_ext  : chemin de base SANS extension
                            (ex: '/dir/figures_hi-res/preprocessing')
      formats           : tuple/list parmi 'pdf', 'png', 'svg'
      dpi               : résolution pour les rasters (défaut 600)

    Note pour SVG/PDF (vectoriel) : le DPI sert juste de hint pour
    le viewport, la qualité est en principe infinie. Pour PNG (raster),
    600 dpi donne ~5000 pixels de large pour une figure 8x6 inches.

    Retourne la liste des chemins effectivement créés.
    """
    out_paths = []
    if not formats or fig is None:
        return out_paths
    for fmt in formats:
        fmt = fmt.lower().strip().lstrip('.')
        if fmt not in HI_RES_FORMATS:
            continue
        out_path = f"{base_path_no_ext}.{fmt}"
        try:
            # bbox_inches='tight' pour cropper les marges
            fig.savefig(out_path, dpi=dpi, format=fmt,
                          bbox_inches='tight', pad_inches=0.1)
            out_paths.append(out_path)
        except Exception:
            # On continue avec les autres formats même si un échoue
            pass
    return out_paths


# ----------------------------------------------------------------
# Initialisation customtkinter (mode d'apparence + thème couleur)
# ----------------------------------------------------------------
if HAS_CTK:
    # System = suit le thème Windows (Light/Dark)
    ctk.set_appearance_mode("System")
    # Bleu par défaut (d'autres options : "green", "dark-blue")
    ctk.set_default_color_theme("blue")

    # === DPI auto-scaling ===
    # Sur écrans HiDPI/4K, l'UI peut paraître trop petite (et inversement
    # trop grande sur écrans basse résolution). On détecte le DPI réel et on
    # ajuste les facteurs de scaling de CTk pour avoir une UI cohérente.
    def _detect_and_apply_dpi_scaling():
        try:
            # Créer un root Tk temporaire pour mesurer le DPI
            tmp = tk.Tk()
            tmp.withdraw()
            # Sous Windows, faire 'aware' du DPI scaling système
            try:
                from ctypes import windll
                windll.shcore.SetProcessDpiAwareness(1)
            except Exception:
                pass
            # winfo_fpixels('1i') = nombre de pixels par inch (DPI réel)
            dpi = tmp.winfo_fpixels('1i')
            tmp.destroy()
            # Référence : 96 DPI = scaling 1.0 (Windows par défaut)
            scale = dpi / 96.0
            # Limiter le scaling à [0.8, 2.0] pour éviter les extrêmes
            scale = max(0.8, min(2.0, scale))
            ctk.set_widget_scaling(scale)
            ctk.set_window_scaling(scale)
            print(f"ℹ DPI détecté : {dpi:.0f} → scaling : {scale:.2f}")
        except Exception as e:
            print(f"⚠ DPI scaling non appliqué : {e}")

    _detect_and_apply_dpi_scaling()


# ----------------------------------------------------------------
# Helpers : retourne des widgets CTk si disponible, sinon ttk
# ----------------------------------------------------------------
def _Button(parent, **kwargs):
    """Bouton moderne (CTkButton) ou ttk.Button en fallback.
    Convertit quelques paramètres courants entre les 2 backends."""
    if HAS_CTK:
        # CTk utilise des pixels pour width/height (vs caractères pour ttk)
        # Si l'utilisateur passe width=3 (caractères ttk), on convertit en px
        if 'width' in kwargs and kwargs['width'] < 20:
            kwargs['width'] = kwargs['width'] * 12  # ~12px par caractère
        return ctk.CTkButton(parent, **kwargs)
    # ttk.Button n'accepte ni 'height' ni 'fg_color' : on les filtre
    kwargs.pop('height', None)
    kwargs.pop('fg_color', None)
    return ttk.Button(parent, **kwargs)


def _Label(parent, **kwargs):
    if HAS_CTK:
        # foreground → text_color pour CTk
        if 'foreground' in kwargs:
            kwargs['text_color'] = kwargs.pop('foreground')
        if 'font' in kwargs and isinstance(kwargs['font'], tuple):
            # Les tuples de fontes tkinter passent tels quels en CTk
            pass
        return ctk.CTkLabel(parent, **kwargs)
    return ttk.Label(parent, **kwargs)


def _label_configure(label, **kwargs):
    """Helper : appelle label.configure() en convertissant 'foreground'
    en 'text_color' si on est en mode CTk. Sinon transmet tel quel à ttk.

    À utiliser pour modifier dynamiquement la couleur d'un _Label après
    sa création. Sans ce wrapper, configure(foreground=...) crashe sous
    CTk car la clé n'est pas reconnue."""
    if HAS_CTK and 'foreground' in kwargs:
        kwargs['text_color'] = kwargs.pop('foreground')
    try:
        label.configure(**kwargs)
    except Exception:
        # Fallback silencieux : si même text_color échoue, on essaie
        # juste le text (cas rare où le widget est dans un état dégradé)
        if 'text' in kwargs:
            try:
                label.configure(text=kwargs['text'])
            except Exception:
                pass


def _Entry(parent, **kwargs):
    if HAS_CTK:
        # CTk width en pixels, ttk en caractères
        if 'width' in kwargs and kwargs['width'] < 50:
            kwargs['width'] = max(kwargs['width'] * 9, 60)
        return ctk.CTkEntry(parent, **kwargs)
    return ttk.Entry(parent, **kwargs)


def _Spinbox(parent, **kwargs):
    """Un vrai Spinbox avec flèches up/down — CTk ou ttk.

    En CTk on construit un widget composite : Entry + 2 mini-boutons ▲ et ▼
    qui incrémentent la valeur du textvariable par 'increment' à chaque clic.
    Les paramètres supportés : textvariable, from_, to, increment, format, width.
    """
    if HAS_CTK:
        from_val = kwargs.get('from_', 0)
        to_val   = kwargs.get('to', 100)
        incr     = kwargs.get('increment', 1)
        fmt      = kwargs.get('format', None)
        var      = kwargs.get('textvariable')
        width    = kwargs.get('width', 80)
        if width < 50:
            width = max(width * 9, 60)
        # Frame conteneur transparent
        container = ctk.CTkFrame(parent, fg_color='transparent', width=width + 26,
                                  height=30)
        container.pack_propagate(False)
        # Entry à gauche, prend toute la largeur dispo
        entry = ctk.CTkEntry(container, textvariable=var, width=width)
        entry.pack(side='left', fill='both', expand=False)

        def _format_value(v):
            """Formate selon fmt si donné, sinon renvoie tel quel."""
            try:
                if fmt:
                    # fmt est de la forme '%.2f' → utilise % style
                    return fmt % float(v)
                # Si pas de format, garder tel quel mais nettoyer un peu
                fv = float(v)
                if fv == int(fv):
                    return str(int(fv))
                return str(fv)
            except (ValueError, TypeError):
                return str(v)

        def _step(delta):
            try:
                cur = float(var.get()) if var else 0.0
            except (ValueError, TypeError, tk.TclError):
                cur = 0.0
            new_val = cur + delta
            # Clamp dans [from_val, to_val]
            new_val = max(from_val, min(to_val, new_val))
            if var is not None:
                try:
                    var.set(_format_value(new_val))
                except tk.TclError:
                    pass

        # Boutons empilés à droite (▲ en haut, ▼ en bas)
        btn_frame = ctk.CTkFrame(container, fg_color='transparent', width=24, height=30)
        btn_frame.pack(side='left', padx=(2, 0))
        btn_frame.pack_propagate(False)
        btn_up = ctk.CTkButton(btn_frame, text='▲', width=22, height=14,
                                font=('TkDefaultFont', 8),
                                command=lambda: _step(incr))
        btn_up.pack(fill='x', pady=(0, 1))
        btn_dn = ctk.CTkButton(btn_frame, text='▼', width=22, height=14,
                                font=('TkDefaultFont', 8),
                                command=lambda: _step(-incr))
        btn_dn.pack(fill='x')
        # Pour que .grid()/.pack() sur le retour appliquent au container, on retourne
        # le container ; le contenu est interne.
        return container
    return ttk.Spinbox(parent, **kwargs)


def _Frame(parent, **kwargs):
    if HAS_CTK:
        # Par défaut transparent pour suivre le parent
        kwargs.setdefault('fg_color', 'transparent')
        return ctk.CTkFrame(parent, **kwargs)
    return ttk.Frame(parent, **kwargs)


def _Checkbutton(parent, **kwargs):
    if HAS_CTK:
        # CTk: 'variable' OK, pas de 'text' différent
        return ctk.CTkCheckBox(parent, **kwargs)
    return ttk.Checkbutton(parent, **kwargs)


def _Combobox(parent, values=None, textvariable=None, width=None,
              state='normal', **kwargs):
    """Combobox/dropdown — CTkComboBox (éditable) ou CTkOptionMenu (readonly).
    Synchronise l'affichage avec la valeur initiale de textvariable."""
    if HAS_CTK:
        vals = list(values) if values is not None else []
        # Récupérer la valeur actuelle de la textvariable (s'il y en a une)
        initial_value = ''
        if textvariable is not None:
            try:
                initial_value = textvariable.get()
            except Exception:
                initial_value = ''

        # Déterminer la largeur pixel
        if width is not None and width < 50:
            px_width = max(width * 10, 80)
        elif width is not None:
            px_width = width
        else:
            px_width = 140

        if state == 'readonly':
            # CTkOptionMenu = liste fermée (choix exclusifs), plus propre
            # pour un dropdown readonly que CTkComboBox en mode readonly.
            ck = {
                'values': vals if vals else [''],
                'variable': textvariable,
                'width': px_width,
            }
            # Propager d'éventuels kwargs supplémentaires (sauf incompatibles)
            for k in ('fg_color', 'button_color', 'button_hover_color',
                      'text_color', 'font', 'dynamic_resizing'):
                if k in kwargs:
                    ck[k] = kwargs[k]
            widget = ctk.CTkOptionMenu(parent, **ck)
        else:
            ck = {
                'values': vals,
                'variable': textvariable,
                'width': px_width,
            }
            for k in ('fg_color', 'button_color', 'button_hover_color',
                      'border_color', 'text_color', 'font', 'dropdown_fg_color',
                      'dropdown_text_color'):
                if k in kwargs:
                    ck[k] = kwargs[k]
            widget = ctk.CTkComboBox(parent, **ck)

        # Forcer l'affichage de la valeur initiale (sinon CTk affiche
        # "CTkComboBox" ou la première entrée des values)
        if initial_value:
            try:
                widget.set(initial_value)
            except Exception:
                pass
        elif vals:
            try:
                widget.set(vals[0])
                if textvariable is not None:
                    textvariable.set(vals[0])
            except Exception:
                pass
        return widget

    # ttk fallback
    tk_args = {}
    if values is not None:
        tk_args['values'] = values
    if textvariable is not None:
        tk_args['textvariable'] = textvariable
    if width is not None:
        tk_args['width'] = width
    if state:
        tk_args['state'] = state
    tk_args.update(kwargs)
    return ttk.Combobox(parent, **tk_args)


def _set_combo_values(combo, values):
    """Met à jour les valeurs d'un combobox/optionmenu (CTk ou ttk)."""
    try:
        combo.configure(values=list(values))
    except Exception:
        try:
            combo['values'] = list(values)
        except Exception:
            pass


def _Toplevel(parent, **kwargs):
    """Fenêtre secondaire — CTkToplevel ou tk.Toplevel en fallback."""
    if HAS_CTK:
        return ctk.CTkToplevel(parent, **kwargs)
    return tk.Toplevel(parent, **kwargs)


def _Textbox(parent, **kwargs):
    """Zone de texte multiligne."""
    if HAS_CTK:
        # CTk width/height en pixels
        return ctk.CTkTextbox(parent, **kwargs)
    # tk.Text en fallback
    return tk.Text(parent, **kwargs)


def _LabelFrame(parent, text='', **kwargs):
    """Encadré avec titre — CTkFrame + label en tête (pas d'équivalent direct)."""
    if HAS_CTK:
        outer = ctk.CTkFrame(parent, **kwargs)
        # Label titre en haut, avec un peu de padding
        lbl = ctk.CTkLabel(outer, text=text,
                            font=ctk.CTkFont(size=12, weight="bold"),
                            anchor='w')
        lbl.pack(fill='x', padx=10, pady=(6, 2))
        # Ligne de séparation visuelle
        sep = ctk.CTkFrame(outer, height=1, fg_color=('gray70', 'gray30'))
        sep.pack(fill='x', padx=10, pady=(0, 4))
        # Frame interne où on ajoute les widgets
        inner = ctk.CTkFrame(outer, fg_color='transparent')
        inner.pack(fill='both', expand=True, padx=4, pady=(0, 4))
        # On retourne un proxy : pack() sur outer, mais ajouts sur inner
        outer._inner = inner
        outer.inner = lambda: inner
        return outer
    return ttk.LabelFrame(parent, text=text, **kwargs)


def _lf_inner(lf):
    """Retourne le frame interne d'un LabelFrame (CTk ou ttk)."""
    if HAS_CTK and hasattr(lf, '_inner'):
        return lf._inner
    return lf


def _make_scrollable_frame(parent):
    """Crée un panneau avec scrollbar verticale.

    Retourne (outer_container, inner_frame) :
      - outer_container : à pack/grid dans le parent (= un Frame qui
        contient le canvas + scrollbar)
      - inner_frame : à utiliser pour packer les widgets enfants
        (s'agrandit selon le contenu, le canvas scroll si nécessaire)

    IMPORTANT : on utilise tk.Frame natif (pas _Frame helper) pour
    garantir un comportement standard avec bind('<Configure>') et la
    gestion du Canvas. Avec CTkFrame, le Configure ne se propage pas
    comme attendu et la scrollbar peut ne jamais s'activer.

    Le canvas adopte un bg neutre (mode foncé / clair selon CTk) pour
    se fondre dans l'UI.
    """
    outer = tk.Frame(parent, highlightthickness=0, borderwidth=0)

    # Couleur de fond : si on est en mode CTk, on prend une couleur
    # cohérente (gris foncé/clair selon le thème)
    bg_color = None
    if HAS_CTK:
        try:
            # Détection mode sombre/clair depuis CTk
            mode = ctk.get_appearance_mode()  # 'Dark' / 'Light'
            bg_color = '#212121' if mode == 'Dark' else '#ebebeb'
        except Exception:
            bg_color = None

    # Canvas + scrollbar — TK natifs
    canvas_kwargs = {'highlightthickness': 0, 'borderwidth': 0}
    if bg_color:
        canvas_kwargs['bg'] = bg_color
    canvas = tk.Canvas(outer, **canvas_kwargs)
    sb = ttk.Scrollbar(outer, orient='vertical', command=canvas.yview)
    canvas.configure(yscrollcommand=sb.set)

    # Pack : canvas à gauche (extensible), scrollbar à droite
    canvas.pack(side=tk.LEFT, fill=tk.BOTH, expand=True)
    sb.pack(side=tk.RIGHT, fill=tk.Y)

    # Inner frame TK natif. Si on utilisait CTkFrame, le bind Configure
    # ne se propagerait pas correctement et la scrollbar resterait inactive.
    if bg_color:
        inner = tk.Frame(canvas, bg=bg_color)
    else:
        inner = tk.Frame(canvas)
    # On positionne 'inner' dans le canvas via create_window. anchor='nw'
    # pour qu'il commence en haut à gauche.
    inner_window_id = canvas.create_window((0, 0), window=inner, anchor='nw')

    # Quand l'inner change de taille (ajout/retrait de widget), met à
    # jour le scrollregion pour que la scrollbar reflète la bonne plage.
    def _on_inner_configure(_event=None):
        try:
            canvas.configure(scrollregion=canvas.bbox('all'))
        except tk.TclError:
            pass
    inner.bind('<Configure>', _on_inner_configure)

    # Quand le canvas est redimensionné, on adapte la largeur de
    # 'inner' à celle du canvas (pour éviter qu'il déborde à droite ou
    # qu'il soit trop étroit). La hauteur reste libre selon contenu.
    def _on_canvas_configure(event):
        try:
            canvas.itemconfig(inner_window_id, width=event.width)
        except tk.TclError:
            pass
    canvas.bind('<Configure>', _on_canvas_configure)

    # Molette souris : binder uniquement quand le pointeur est sur le
    # canvas, sinon on perturbe le scroll global de l'app. On bind/unbind
    # via Enter/Leave.
    def _bind_wheel(_e):
        # Windows / macOS : <MouseWheel>
        canvas.bind_all('<MouseWheel>', _on_wheel)
        # Linux : <Button-4> / <Button-5>
        canvas.bind_all('<Button-4>', _on_wheel)
        canvas.bind_all('<Button-5>', _on_wheel)
    def _unbind_wheel(_e):
        canvas.unbind_all('<MouseWheel>')
        canvas.unbind_all('<Button-4>')
        canvas.unbind_all('<Button-5>')
    def _on_wheel(event):
        # Direction (Windows: event.delta = ±120 par cran ; Linux: num=4/5)
        delta = 0
        if hasattr(event, 'delta') and event.delta:
            delta = -1 if event.delta > 0 else 1
        elif hasattr(event, 'num'):
            if event.num == 4:
                delta = -1
            elif event.num == 5:
                delta = 1
        if delta:
            canvas.yview_scroll(delta, 'units')
    outer.bind('<Enter>', _bind_wheel)
    outer.bind('<Leave>', _unbind_wheel)

    return outer, inner


