class Tooltip:
    """Info-bulle légère pour tk/ttk/CTk widgets.
    Usage : Tooltip(widget, "Mon texte d'aide")"""
    _active = None  # tooltip actuellement affiché (un seul à la fois)

    def __init__(self, widget, text, delay=500):
        self.widget = widget
        self.text = text
        self.delay = delay
        self._after_id = None
        self._tip_window = None
        widget.bind('<Enter>', self._schedule, add='+')
        widget.bind('<Leave>', self._hide, add='+')
        widget.bind('<ButtonPress>', self._hide, add='+')

    def _schedule(self, event=None):
        self._cancel()
        self._after_id = self.widget.after(self.delay, self._show)

    def _cancel(self):
        if self._after_id:
            try:
                self.widget.after_cancel(self._after_id)
            except Exception:
                pass
            self._after_id = None

    def _show(self):
        # Masquer tout autre tooltip actif
        if Tooltip._active is not None and Tooltip._active is not self:
            Tooltip._active._hide()
        if self._tip_window:
            return
        # Position juste sous le widget
        try:
            x = self.widget.winfo_rootx() + 20
            y = self.widget.winfo_rooty() + self.widget.winfo_height() + 5
        except Exception:
            return
        self._tip_window = tk.Toplevel(self.widget)
        self._tip_window.wm_overrideredirect(True)  # pas de déco fenêtre
        self._tip_window.wm_geometry(f"+{x}+{y}")
        # Apparence : fond jaune pâle clair / gris sombre selon le thème CTk
        if HAS_CTK:
            try:
                mode = ctk.get_appearance_mode().lower()
                bg = '#2b2b2b' if mode == 'dark' else '#fffbe0'
                fg = '#e0e0e0' if mode == 'dark' else '#222222'
            except Exception:
                bg, fg = '#fffbe0', '#222222'
        else:
            bg, fg = '#fffbe0', '#222222'
        label = tk.Label(self._tip_window, text=self.text,
                         bg=bg, fg=fg,
                         relief='solid', borderwidth=1,
                         padx=8, pady=4,
                         font=('TkDefaultFont', 9),
                         justify='left')
        label.pack()
        Tooltip._active = self

    def _hide(self, event=None):
        self._cancel()
        if self._tip_window:
            try:
                self._tip_window.destroy()
            except Exception:
                pass
            self._tip_window = None
        if Tooltip._active is self:
            Tooltip._active = None


def _AccentButton(parent, **kwargs):
    """Bouton d'accent (vert pour actions positives, bleu foncé pour principales).
    Utilise CTkButton avec fg_color custom si disponible."""
    color = kwargs.pop('accent', 'primary')
    if HAS_CTK:
        if 'width' in kwargs and kwargs['width'] < 20:
            kwargs['width'] = kwargs['width'] * 12
        # Palettes d'accents
        palettes = {
            'primary': {'fg_color': ('#1976d2', '#1565c0'),
                        'hover_color': ('#1565c0', '#0d47a1')},
            'success': {'fg_color': ('#2e7d32', '#1b5e20'),
                        'hover_color': ('#1b5e20', '#0d3d0d')},
            'danger':  {'fg_color': ('#c62828', '#8e1919'),
                        'hover_color': ('#8e1919', '#611010')},
        }
        kwargs.setdefault('font', ctk.CTkFont(weight='bold'))
        kwargs.update(palettes.get(color, palettes['primary']))
        return ctk.CTkButton(parent, **kwargs)
    return ttk.Button(parent, **kwargs)


