def load_spectrum(path):
    try:
        data = np.loadtxt(path, delimiter=',', comments=('#', '##'))
    except ValueError:
        data = np.loadtxt(path, comments=('#', '##'))
    if data.ndim == 1 and data.size >= 2:
        data = data.reshape(-1, 2)
    return data[:, 0], data[:, 1]


def normalize_in_window(x, y, xmin, xmax):
    mask = (x >= xmin) & (x <= xmax)
    if mask.sum() < 2:
        return y
    y_win = y[mask]
    return (y - y_win.min()) / (y_win.max() - y_win.min())


def clean_label(fname, prefix=''):
    base = os.path.splitext(fname)[0]
    base = re.sub(r'([A-Za-z]+)(R\d+)', r'\1 \2', base)
    base = base.replace('_', ' ')
    return f'{prefix}{base}' if prefix else base


def latex_to_unicode(s):
    """Convertit un texte LaTeX simple en Unicode pour affichage dans un
    Tk Label (qui ne sait pas rendre du mathtext matplotlib).

    Gère :
      - $...$ → contenu mathématique simplifié
      - _{...} et _x → indices Unicode
      - ^{...} et ^x → exposants Unicode
      - \\alpha, \\beta, ... → lettres grecques

    Exemples :
      'TiO$_2$'                   → 'TiO₂'
      r'$E_g^{(1)}$'              → 'E_g⁽¹⁾'
      r'Fe$_2$O$_3$'              → 'Fe₂O₃'
      r'$\\alpha$-Fe$_2$O$_3$'    → 'α-Fe₂O₃'
    """
    if not s or not isinstance(s, str):
        return s

    # Lettres grecques courantes
    GREEK = {
        r'\alpha': 'α', r'\beta': 'β', r'\gamma': 'γ', r'\delta': 'δ',
        r'\epsilon': 'ε', r'\zeta': 'ζ', r'\eta': 'η', r'\theta': 'θ',
        r'\iota': 'ι', r'\kappa': 'κ', r'\lambda': 'λ', r'\mu': 'μ',
        r'\nu': 'ν', r'\xi': 'ξ', r'\omicron': 'ο', r'\pi': 'π',
        r'\rho': 'ρ', r'\sigma': 'σ', r'\tau': 'τ', r'\upsilon': 'υ',
        r'\phi': 'φ', r'\chi': 'χ', r'\psi': 'ψ', r'\omega': 'ω',
        r'\Alpha': 'Α', r'\Beta': 'Β', r'\Gamma': 'Γ', r'\Delta': 'Δ',
        r'\Theta': 'Θ', r'\Lambda': 'Λ', r'\Pi': 'Π', r'\Sigma': 'Σ',
        r'\Phi': 'Φ', r'\Psi': 'Ψ', r'\Omega': 'Ω',
    }
    # Tables d'indices et exposants Unicode
    SUB_DIGITS = str.maketrans('0123456789+-=()',  '₀₁₂₃₄₅₆₇₈₉₊₋₌₍₎')
    SUP_DIGITS = str.maketrans('0123456789+-=()',  '⁰¹²³⁴⁵⁶⁷⁸⁹⁺⁻⁼⁽⁾')

    out = s
    # 1) Retirer les $...$ délimiteurs (mais garder le contenu)
    out = re.sub(r'\$([^$]*)\$', r'\1', out)
    # 2) Lettres grecques
    for tex, uni in GREEK.items():
        out = out.replace(tex, uni)
    # 3) Indices : _{xxx} → traduire xxx en chiffres bas si possible
    def _sub_braces(m):
        content = m.group(1)
        # Si que des chiffres/+/-/=/() → traduit en indice Unicode
        if re.fullmatch(r'[0-9+\-=()]+', content):
            return content.translate(SUB_DIGITS)
        # Sinon : on garde la forme _xxx (lisible mais pas Unicode pur)
        return '_' + content
    out = re.sub(r'_\{([^}]+)\}', _sub_braces, out)
    # 4) Indices simples _x (un seul caractère après _)
    def _sub_single(m):
        c = m.group(1)
        if c in '0123456789':
            return c.translate(SUB_DIGITS)
        return '_' + c
    out = re.sub(r'_([0-9a-zA-Z])', _sub_single, out)
    # 5) Exposants : ^{xxx}
    def _sup_braces(m):
        content = m.group(1)
        if re.fullmatch(r'[0-9+\-=()]+', content):
            return content.translate(SUP_DIGITS)
        return '^' + content
    out = re.sub(r'\^\{([^}]+)\}', _sup_braces, out)
    # 6) Exposants simples ^x
    def _sup_single(m):
        c = m.group(1)
        if c in '0123456789':
            return c.translate(SUP_DIGITS)
        return '^' + c
    out = re.sub(r'\^([0-9a-zA-Z])', _sup_single, out)
    # 7) Backslashes orphelins (commandes LaTeX inconnues) → garder mot brut
    out = re.sub(r'\\([a-zA-Z]+)', r'\1', out)
    return out


def _latex_to_reportlab_html(s):
    """Convertit un texte type LaTeX/chimique en HTML ReportLab Paragraph.

    La différence avec latex_to_unicode : on produit des balises
    <sub>/<super> ReportLab (rendues correctement par les fontes
    standards Times/Helvetica) plutôt que des caractères Unicode
    subscript/superscript (qui ne sont PAS dans les fontes built-in
    ReportLab et apparaissent comme des carrés noirs dans le PDF).

    Convertit :
      'NaAlSi_3O_8'    → 'NaAlSi<sub>3</sub>O<sub>8</sub>'
      'Fe_2O_3'        → 'Fe<sub>2</sub>O<sub>3</sub>'
      'cm^-1'          → 'cm<super>-1</super>'
      r'$\alpha$-Fe2O3'→ 'α-Fe2O3'  (lettre grecque OK en Times/Helvetica)
      'TiO_{2}'        → 'TiO<sub>2</sub>'
    """
    if not s or not isinstance(s, str):
        return s or ''

    # Échapper les caractères dangereux pour ReportLab AVANT d'ajouter
    # les balises <sub>/<super> (sinon les '<' présents dans le texte
    # seraient interprétés comme des balises)
    GREEK = {
        r'\alpha': 'α', r'\beta': 'β', r'\gamma': 'γ', r'\delta': 'δ',
        r'\epsilon': 'ε', r'\zeta': 'ζ', r'\eta': 'η', r'\theta': 'θ',
        r'\iota': 'ι', r'\kappa': 'κ', r'\lambda': 'λ', r'\mu': 'μ',
        r'\nu': 'ν', r'\xi': 'ξ', r'\omicron': 'ο', r'\pi': 'π',
        r'\rho': 'ρ', r'\sigma': 'σ', r'\tau': 'τ', r'\upsilon': 'υ',
        r'\phi': 'φ', r'\chi': 'χ', r'\psi': 'ψ', r'\omega': 'ω',
    }
    out = s
    # 1) Retirer les délimiteurs $...$
    out = re.sub(r'\$([^$]*)\$', r'\1', out)
    # 2) Lettres grecques (Unicode OK pour ces caractères)
    for tex, uni in GREEK.items():
        out = out.replace(tex, uni)
    # 3) Échapper les caractères XML
    out = out.replace('&', '&amp;')
    # On NE remplace PAS '<' et '>' car on va les utiliser pour les balises
    # → mais on traite d'abord les patterns LaTeX, puis on protège ce qui reste
    # 4) Indices : _{...} et _x → <sub>...</sub>
    out = re.sub(r'_\{([^}]+)\}', r'<sub>\1</sub>', out)
    out = re.sub(r'_([0-9a-zA-Z+\-])', r'<sub>\1</sub>', out)
    # 5) Exposants : ^{...} et ^x → <super>...</super>
    out = re.sub(r'\^\{([^}]+)\}', r'<super>\1</super>', out)
    out = re.sub(r'\^([0-9a-zA-Z+\-])', r'<super>\1</super>', out)
    # 6) Backslashes orphelins
    out = re.sub(r'\\([a-zA-Z]+)', r'\1', out)
    # 7) Convertir les Unicode subscript/superscript résiduels (cas où
    # latex_to_unicode a déjà été appliqué avant nous) en <sub>/<super>
    # pour éviter les carrés noirs.
    SUB_TO_HTML = {
        '₀':'<sub>0</sub>', '₁':'<sub>1</sub>', '₂':'<sub>2</sub>',
        '₃':'<sub>3</sub>', '₄':'<sub>4</sub>', '₅':'<sub>5</sub>',
        '₆':'<sub>6</sub>', '₇':'<sub>7</sub>', '₈':'<sub>8</sub>',
        '₉':'<sub>9</sub>', '₊':'<sub>+</sub>', '₋':'<sub>-</sub>',
        '₌':'<sub>=</sub>', '₍':'<sub>(</sub>', '₎':'<sub>)</sub>',
    }
    SUP_TO_HTML = {
        '⁰':'<super>0</super>', '¹':'<super>1</super>', '²':'<super>2</super>',
        '³':'<super>3</super>', '⁴':'<super>4</super>', '⁵':'<super>5</super>',
        '⁶':'<super>6</super>', '⁷':'<super>7</super>', '⁸':'<super>8</super>',
        '⁹':'<super>9</super>', '⁺':'<super>+</super>', '⁻':'<super>-</super>',
        '⁼':'<super>=</super>', '⁽':'<super>(</super>', '⁾':'<super>)</super>',
    }
    for c, html in SUB_TO_HTML.items():
        out = out.replace(c, html)
    for c, html in SUP_TO_HTML.items():
        out = out.replace(c, html)
    return out


def detect_laser_from_filename(fname):
    """Détecte la longueur d'onde du laser depuis un nom de fichier RRUFF.
    Le format standard RRUFF contient __Raman__XXX__ où XXX est la longueur
    d'onde en nm (325, 405, 457, 488, 514, 532, 633, 647, 785, 830, 1064).
    Retourne la chaîne formatée (ex: '532 nm') ou None si non détecté."""
    VALID_LASERS = {325, 405, 457, 488, 514, 532, 633, 647, 780, 785, 830, 1064}
    # Pattern RRUFF : __Raman__532__ ou __Raman__532.0__
    m = re.search(r'[_\s\W]Raman[_\s\W]+(\d{3,4})(?:\.\d+)?[_\s\W]', fname, re.IGNORECASE)
    if m:
        val = int(m.group(1))
        if val in VALID_LASERS:
            return f'{val} nm'
    # Fallback générique : chercher un nombre à 3-4 chiffres suivi de "nm"
    m = re.search(r'(\d{3,4})\s*nm', fname, re.IGNORECASE)
    if m:
        val = int(m.group(1))
        if val in VALID_LASERS:
            return f'{val} nm'
    return None


def safe_filename(s):
    s = re.sub(r'[^\w\-.]+', '_', s)
    return s.strip('_')


def search_minerals(query):
    q = query.lower().strip()
    results = []
    if not q:
        return results
    for m, info in RAMAN_DB.items():
        if q == m:
            results.append((m, 100, 'exact'))
        elif m.startswith(q):
            results.append((m, 90, f'starts with "{q}"'))
        elif q in m:
            results.append((m, 70, f'name contains "{q}"'))
        elif q in info.get('formula', '').lower():
            results.append((m, 60, f'formula: {info["formula"]}'))
        elif q in info.get('group', '').lower():
            results.append((m, 50, f'group: {info["group"]}'))
    return sorted(results, key=lambda r: -r[1])


def get_palette(name, n):
    palettes = {
        'tab10':       plt.cm.tab10,
        'viridis':     plt.cm.viridis,
        'plasma':      plt.cm.plasma,
        'inferno':      plt.cm.inferno,
        'magma':      plt.cm.magma,
        'cividis':      plt.cm.cividis,
        'dark2':       plt.cm.Dark2,
        'gris (N&B)':  plt.cm.gray,
        'Pastel1':  plt.cm.Pastel1,
        'Pastel2':  plt.cm.Pastel2,
        'Paired':  plt.cm.Paired,
        'Accent':  plt.cm.Accent,
        'Dark2':  plt.cm.Dark2,
        'Set1':  plt.cm.Set1,
        'Set2':  plt.cm.Set2,
        'Set3':  plt.cm.Set3,
        'tab20':  plt.cm.tab20,
        'tab20b':  plt.cm.tab20b,
        'tab20c':  plt.cm.tab20c,
        'gist_rainbow':  plt.cm.gist_rainbow,
        'ocean':  plt.cm.ocean,
        'gist_earth':  plt.cm.gist_earth,
        'terrain':  plt.cm.terrain,
        'gist_stern':  plt.cm.gist_stern,
        'gnuplot':  plt.cm.gnuplot,
        'gnuplot2':  plt.cm.gnuplot2,
        'CMRmap':  plt.cm.CMRmap,
        'cubehelix':  plt.cm.cubehelix,
        'brg':  plt.cm.brg,
        'rainbow':  plt.cm.rainbow,
        'jet':  plt.cm.jet,
        'turbo':  plt.cm.turbo,
        'nipy_spectral':  plt.cm.nipy_spectral,
        'gist_ncar':  plt.cm.gist_ncar,
    }
    cmap = palettes.get(name, plt.cm.tab10)
    if cmap in (plt.cm.tab10, plt.cm.Set1, plt.cm.Set2, plt.cm.Dark2):
        return [cmap(i) for i in range(n)]
    return [cmap(v) for v in np.linspace(0.15, 0.75, max(n, 1))]


def value_at(x_array, y_array, x0):
    if x0 < x_array.min() or x0 > x_array.max():
        return np.nan
    return float(np.interp(x0, x_array, y_array))


def parse_float_or_none(s):
    """Parse une string en float, retourne None si vide/invalide."""
    s = (s or '').strip()
    if not s:
        return None
    try:
        return float(s)
    except ValueError:
        return None


