CURRENT_LANG = 'fr'  # défaut — peut être changé via set_language()


def t(key, **kwargs):
    """Traduit une clé dans la langue courante.
    Si la clé n'existe pas, retourne la clé elle-même (debug friendly).
    Supporte le formatage : t('splash.recent_dir', path='/home/...')"""
    lang = CURRENT_LANG if CURRENT_LANG in LANG else 'fr'
    s = LANG.get(lang, {}).get(key)
    if s is None:
        # Fallback vers FR, sinon retourner la clé
        s = LANG.get('fr', {}).get(key, key)
    if kwargs:
        try:
            s = s.format(**kwargs)
        except Exception:
            pass
    return s


def set_language(lang_code):
    """Change la langue active. Retourne True si la langue est supportée."""
    global CURRENT_LANG
    if lang_code in LANG:
        CURRENT_LANG = lang_code
        return True
    return False


def _load_saved_language():
    """Charge la langue choisie depuis un fichier de config utilisateur,
    retourne 'fr' par défaut."""
    try:
        cfg = os.path.join(os.path.expanduser('~'), '.raman_plot_builder.cfg')
        if os.path.isfile(cfg):
            with open(cfg, 'r', encoding='utf-8') as f:
                data = json.load(f)
            lang = data.get('language', 'fr')
            if lang in LANG:
                return lang
    except Exception:
        pass
    return 'fr'


def _save_language(lang_code):
    """Sauvegarde la langue dans la config utilisateur."""
    try:
        cfg = os.path.join(os.path.expanduser('~'), '.raman_plot_builder.cfg')
        data = {}
        if os.path.isfile(cfg):
            try:
                with open(cfg, 'r', encoding='utf-8') as f:
                    data = json.load(f)
            except Exception:
                data = {}
        data['language'] = lang_code
        with open(cfg, 'w', encoding='utf-8') as f:
            json.dump(data, f)
    except Exception:
        pass


def _load_user_profile():
    """Charge le profil utilisateur depuis ~/.raman_plot_builder.cfg.
    Retourne un dict {title, firstname, lastname, email}, vide si pas défini.

    Rétro-compatibilité : un ancien dialog de Match Search écrivait les
    clés 'first_name'/'last_name' (snake_case) au lieu de 'firstname'/
    'lastname'. Si on détecte ces clés, on les utilise comme fallback
    pour ne pas perdre les données saisies avant le fix."""
    try:
        cfg = os.path.join(os.path.expanduser('~'), '.raman_plot_builder.cfg')
        if os.path.isfile(cfg):
            with open(cfg, 'r', encoding='utf-8') as f:
                data = json.load(f)
            profile = data.get('user_profile', {})
            if isinstance(profile, dict):
                return {
                    'title':     profile.get('title', '').strip(),
                    'firstname': (profile.get('firstname')
                                    or profile.get('first_name')
                                    or '').strip(),
                    'lastname':  (profile.get('lastname')
                                    or profile.get('last_name')
                                    or '').strip(),
                    'email':     profile.get('email', '').strip(),
                }
    except Exception:
        pass
    return {'title': '', 'firstname': '', 'lastname': '', 'email': ''}


def _save_user_profile(profile):
    """Sauvegarde le profil utilisateur dans le cfg."""
    try:
        cfg = os.path.join(os.path.expanduser('~'), '.raman_plot_builder.cfg')
        data = {}
        if os.path.isfile(cfg):
            try:
                with open(cfg, 'r', encoding='utf-8') as f:
                    data = json.load(f)
            except Exception:
                data = {}
        data['user_profile'] = {
            'title':     (profile.get('title') or '').strip(),
            'firstname': (profile.get('firstname') or '').strip(),
            'lastname':  (profile.get('lastname') or '').strip(),
            'email':     (profile.get('email') or '').strip(),
        }
        with open(cfg, 'w', encoding='utf-8') as f:
            json.dump(data, f)
    except Exception:
        pass


def _profile_is_complete(profile):
    """Retourne True si firstname, lastname, email sont tous renseignés."""
    return bool(profile.get('firstname') and profile.get('lastname')
                and profile.get('email'))


def _format_profile(profile):
    """Formate le profil en chaîne 'Titre Prénom Nom — email'."""
    title = profile.get('title', '').strip()
    fn    = profile.get('firstname', '').strip()
    ln    = profile.get('lastname', '').strip()
    email = profile.get('email', '').strip()
    name = f"{fn} {ln}".strip()
    if title:
        name = f"{title} {name}".strip()
    if email:
        return f"{name} — {email}"
    return name


def _load_saved_theme():
    """Charge le thème sauvegardé. Retourne 'system' par défaut."""
    try:
        cfg = os.path.join(os.path.expanduser('~'), '.raman_plot_builder.cfg')
        if os.path.isfile(cfg):
            with open(cfg, 'r', encoding='utf-8') as f:
                data = json.load(f)
            theme = data.get('theme', 'system')
            if theme in ('light', 'dark', 'system'):
                return theme
    except Exception:
        pass
    return 'system'


def _save_theme(theme):
    """Sauvegarde le thème dans la config."""
    try:
        cfg = os.path.join(os.path.expanduser('~'), '.raman_plot_builder.cfg')
        data = {}
        if os.path.isfile(cfg):
            try:
                with open(cfg, 'r', encoding='utf-8') as f:
                    data = json.load(f)
            except Exception:
                data = {}
        data['theme'] = theme
        with open(cfg, 'w', encoding='utf-8') as f:
            json.dump(data, f)
    except Exception:
        pass


def _normalize_path(path):
    """Normalise un chemin pour comparaison cohérente :
    - séparateurs OS-natif (\\ sous Windows)
    - chemin absolu
    - casse uniformisée (Windows insensible à la casse)
    - résolution des liens symboliques si possible
    """
    if not path or not isinstance(path, str):
        return path
    try:
        # abspath puis normpath puis normcase (lower sous Windows)
        p = os.path.normcase(os.path.normpath(os.path.abspath(path)))
        # Tenter aussi realpath pour résoudre les liens
        try:
            p = os.path.normcase(os.path.realpath(p))
        except Exception:
            pass
        return p
    except Exception:
        return path


def _load_recent_projects():
    """Retourne la liste des 10 derniers projets ouverts (Plot Builder + Match Search).
    On agrège recent_projects (.rpm) et recent_match_projects (.rms).
    Les chemins sont normalisés et dédupliqués."""
    try:
        cfg = os.path.join(os.path.expanduser('~'), '.raman_plot_builder.cfg')
        if not os.path.isfile(cfg):
            return []
        with open(cfg, 'r', encoding='utf-8') as f:
            data = json.load(f)
        # Concaténer les deux listes en gardant l'ordre cfg : Plot Builder
        # (.rpm) en premier, puis Match Search (.rms)
        rpm_list   = data.get('recent_projects', [])
        rms_list   = data.get('recent_match_projects', [])
        projects   = list(rpm_list) + list(rms_list)
        # Normaliser + filtrer + dédupliquer
        seen = set()
        result = []
        had_duplicate = False
        for p in projects:
            if not isinstance(p, str):
                had_duplicate = True
                continue
            norm = _normalize_path(p)
            if norm in seen:
                had_duplicate = True
                continue
            if not os.path.isfile(norm):
                had_duplicate = True
                continue
            if norm != p:
                had_duplicate = True
            seen.add(norm)
            result.append(norm)
        # Si on a trouvé des doublons ou des entrées invalides, réécrire les
        # listes pour nettoyer
        if had_duplicate:
            try:
                # Re-séparer par extension pour réécrire chaque liste
                clean_rpm = [p for p in result if p.lower().endswith('.rpm')]
                clean_rms = [p for p in result if p.lower().endswith('.rms')]
                data['recent_projects']       = clean_rpm
                data['recent_match_projects'] = clean_rms
                with open(cfg, 'w', encoding='utf-8') as f:
                    json.dump(data, f)
            except Exception:
                pass
        return result
    except Exception:
        pass
    return []


def _push_recent_project(path):
    """Ajoute un projet à la liste des récents (en tête). Garde les 10 derniers.
    Normalise les séparateurs de chemins pour éviter les doublons
    (ex : Windows mélange '\\' et '/' selon la source du chemin).
    Nettoie aussi les doublons pré-existants dans le cfg."""
    if not path:
        return
    path = _normalize_path(path)
    try:
        cfg = os.path.join(os.path.expanduser('~'), '.raman_plot_builder.cfg')
        data = {}
        if os.path.isfile(cfg):
            try:
                with open(cfg, 'r', encoding='utf-8') as f:
                    data = json.load(f)
            except Exception:
                data = {}
        recent_raw = data.get('recent_projects', [])
        # 1) Normaliser TOUTES les entrées existantes
        # 2) Exclure celle qu'on va insérer en tête
        # 3) Dédupliquer en conservant l'ordre (1er apparu = gardé)
        seen = {path}  # le nouveau path déjà "vu"
        cleaned = []
        for p in recent_raw:
            if not isinstance(p, str):
                continue
            norm = _normalize_path(p)
            if norm in seen:
                continue
            seen.add(norm)
            cleaned.append(norm)
        # Insérer le nouveau en tête
        recent = [path] + cleaned
        # Garder les 10 plus récents
        data['recent_projects'] = recent[:10]
        with open(cfg, 'w', encoding='utf-8') as f:
            json.dump(data, f)
    except Exception:
        pass


