# ================================================================
# MODÈLES DEEP LEARNING POUR MATCH SEARCH (CDAE + CBRAE)
# ================================================================
# Architectures inspirées du pipeline développé dans le notebook
# RAMAN_CBRAE_tuning_THEONLYONE_GOOD.ipynb par B-V Fauconnier (TFE UdeS 2025).
#
# CDAE (Convolutional Denoising AutoEncoder) :
#   - U-Net 1D classique avec skip connections
#   - Entrée : (B, 1, 1024) normalisé [0,1]
#   - Sortie : spectre débruité, même shape
#
# CBRAE (Convolutional Baseline Removal AutoEncoder) :
#   - U-Net 1D multi-échelle (3 branches parallèles avec kernels 75/25/7)
#   - Capte tendances lentes + intermédiaires + détails fins
#   - Entrée : spectre débruité (sortie CDAE)
#   - Sortie : baseline estimée, contrainte ≤ signal via min-trick
#
# Les classes sont définies seulement si PyTorch est installé.
# ================================================================
if HAS_TORCH:

    # ---- CDAE ----
    class _ConvBlock(nn.Module):
        """3× (Conv1d → BatchNorm → SELU)"""
        def __init__(self, in_ch, out_ch, kernel_size=3):
            super().__init__()
            self.block = nn.Sequential(
                nn.Conv1d(in_ch,  out_ch, kernel_size, padding='same'),
                nn.BatchNorm1d(out_ch), nn.SELU(),
                nn.Conv1d(out_ch, out_ch, kernel_size, padding='same'),
                nn.BatchNorm1d(out_ch), nn.SELU(),
                nn.Conv1d(out_ch, out_ch, kernel_size, padding='same'),
                nn.BatchNorm1d(out_ch), nn.SELU(),
            )
        def forward(self, x):
            return self.block(x)

    class _EncoderBlock(nn.Module):
        def __init__(self, in_ch, out_ch, kernel_size=3):
            super().__init__()
            self.conv  = _ConvBlock(in_ch, out_ch, kernel_size)
            self.pool  = nn.MaxPool1d(2)
        def forward(self, x):
            skip = self.conv(x)
            return self.pool(skip), skip

    class _DecoderBlock(nn.Module):
        def __init__(self, in_ch, skip_ch, out_ch, kernel_size=3):
            super().__init__()
            self.up   = nn.Upsample(scale_factor=2, mode='linear', align_corners=False)
            self.conv = _ConvBlock(in_ch + skip_ch, out_ch, kernel_size)
        def forward(self, x, skip):
            x = self.up(x)
            x = torch.cat([x, skip], dim=1)
            return self.conv(x)

    class CDAE(nn.Module):
        """Convolutional Denoising AutoEncoder pour spectres Raman (1×1024 pts)."""
        def __init__(self, n_points=1024):
            super().__init__()
            self.n_points = n_points
            self.enc1 = _EncoderBlock(  1,   8, kernel_size=2)  # 1024 → 512
            self.enc2 = _EncoderBlock(  8,  16, kernel_size=2)  # 512  → 256
            self.enc3 = _EncoderBlock( 16,  32, kernel_size=3)  # 256  → 128
            self.enc4 = _EncoderBlock( 32,  64, kernel_size=3)  # 128  → 64
            self.enc5 = _EncoderBlock( 64, 128, kernel_size=5)  # 64   → 32
            self.bottleneck = nn.Sequential(
                nn.Conv1d(128, 256, 7, padding=3), nn.BatchNorm1d(256), nn.SELU(),
                nn.Conv1d(256, 256, 7, padding=3), nn.BatchNorm1d(256), nn.SELU(),
                nn.Conv1d(256, 128, 7, padding=3), nn.BatchNorm1d(128), nn.SELU(),
            )
            self.dec5 = _DecoderBlock(128, 128, 128, kernel_size=5)
            self.dec4 = _DecoderBlock(128,  64,  64, kernel_size=3)
            self.dec3 = _DecoderBlock( 64,  32,  32, kernel_size=3)
            self.dec2 = _DecoderBlock( 32,  16,  16, kernel_size=2)
            self.dec1 = _DecoderBlock( 16,   8,   8, kernel_size=2)
            self.out_conv = nn.Conv1d(8, 1, kernel_size=1)

        def forward(self, x):
            x, s1 = self.enc1(x); x, s2 = self.enc2(x)
            x, s3 = self.enc3(x); x, s4 = self.enc4(x); x, s5 = self.enc5(x)
            x = self.bottleneck(x)
            x = self.dec5(x, s5); x = self.dec4(x, s4)
            x = self.dec3(x, s3); x = self.dec2(x, s2); x = self.dec1(x, s1)
            return self.out_conv(x)

    # ---- CBRAE ----
    class _MultiScaleBaselineBlock(nn.Module):
        """3 branches parallèles à kernels différents (lent / moyen / rapide).
        Capte simultanément tendance globale et détails de courbure."""
        def __init__(self, in_ch, out_ch, kernels=(75, 25, 7)):
            super().__init__()
            assert out_ch % 3 == 0
            branch_ch = out_ch // 3
            self.branch_large  = nn.Sequential(
                nn.Conv1d(in_ch, branch_ch, kernels[0], padding='same'),
                nn.BatchNorm1d(branch_ch), nn.ReLU())
            self.branch_medium = nn.Sequential(
                nn.Conv1d(in_ch, branch_ch, kernels[1], padding='same'),
                nn.BatchNorm1d(branch_ch), nn.ReLU())
            self.branch_small  = nn.Sequential(
                nn.Conv1d(in_ch, branch_ch, kernels[2], padding='same'),
                nn.BatchNorm1d(branch_ch), nn.ReLU())
            self.fuse = nn.Sequential(
                nn.Conv1d(out_ch, out_ch, 7, padding='same'),
                nn.BatchNorm1d(out_ch), nn.ReLU())
        def forward(self, x):
            x = torch.cat([self.branch_large(x), self.branch_medium(x),
                            self.branch_small(x)], dim=1)
            return self.fuse(x)

    class _MSEncoderBlock(nn.Module):
        def __init__(self, in_ch, out_ch, kernels=(75, 25, 7)):
            super().__init__()
            self.conv = _MultiScaleBaselineBlock(in_ch, out_ch, kernels)
            self.pool = nn.MaxPool1d(2)
        def forward(self, x):
            skip = self.conv(x)
            return self.pool(skip), skip

    class _MSDecoderBlock(nn.Module):
        def __init__(self, in_ch, skip_ch, out_ch, kernels=(75, 25, 7)):
            super().__init__()
            self.up   = nn.Upsample(scale_factor=2, mode='linear', align_corners=False)
            self.conv = _MultiScaleBaselineBlock(in_ch + skip_ch, out_ch, kernels)
        def forward(self, x, skip):
            x = self.up(x)
            x = torch.cat([x, skip], dim=1)
            return self.conv(x)

    class CBRAE(nn.Module):
        """Convolutional Baseline Removal AutoEncoder, multi-scale."""
        def __init__(self, n_points=1024):
            super().__init__()
            self.n_points = n_points
            self.enc1 = _MSEncoderBlock(  1,  48, kernels=(75, 25,  7))
            self.enc2 = _MSEncoderBlock( 48,  96, kernels=(45, 15,  5))
            self.enc3 = _MSEncoderBlock( 96,  96, kernels=(25,  9,  3))
            self.enc4 = _MSEncoderBlock( 96,  96, kernels=(15,  7,  3))
            self.bottleneck = _MultiScaleBaselineBlock(96, 96, kernels=(15, 7, 3))
            self.dec4 = _MSDecoderBlock( 96,  96,  96, kernels=(15,  7,  3))
            self.dec3 = _MSDecoderBlock( 96,  96,  96, kernels=(25,  9,  3))
            self.dec2 = _MSDecoderBlock( 96,  96,  48, kernels=(45, 15,  5))
            self.dec1 = _MSDecoderBlock( 48,  48,  48, kernels=(75, 25,  7))
            self.out_conv = nn.Sequential(
                nn.Conv1d(48, 1, kernel_size=3, padding=1), nn.Sigmoid())

        def forward(self, x):
            x, s1 = self.enc1(x); x, s2 = self.enc2(x)
            x, s3 = self.enc3(x); x, s4 = self.enc4(x)
            x = self.bottleneck(x)
            x = self.dec4(x, s4); x = self.dec3(x, s3)
            x = self.dec2(x, s2); x = self.dec1(x, s1)
            return self.out_conv(x)


# ================================================================
# HELPERS DE PRÉTRAITEMENT (utilisés par Match Search)
# ================================================================
def preprocess_for_dl(x, y, n_points=1024):
    """Prépare un spectre pour le pipeline CDAE+CBRAE.

    Pipeline :
      1. Interpolation cubique sur n_points (1024 par défaut)
      2. Normalisation min-max → [0, 1]

    Retourne : (x_resampled, y_normalized, y_min, y_max)
    Le y_min/y_max permet de dénormaliser après inférence si besoin.
    """
    from scipy.signal import medfilt
    from scipy.interpolate import interp1d

    # 2. Resample à n_points
    x = np.asarray(x, dtype=float)
    f = interp1d(x, y, kind='cubic', fill_value='extrapolate', assume_sorted=False)
    x_new = np.linspace(x.min(), x.max(), n_points)
    y_new = f(x_new)

    # 3. Normaliser [0, 1]
    y_min, y_max = float(y_new.min()), float(y_new.max())
    if y_max - y_min < 1e-10:
        return x_new, y_new, y_min, y_max
    y_norm = (y_new - y_min) / (y_max - y_min)
    return x_new, y_norm, y_min, y_max


def resample_back(x_dl, y_dl, x_target):
    """Re-interpole un spectre traité par DL (1024 pts) vers la grille originale."""
    from scipy.interpolate import interp1d
    f = interp1d(x_dl, y_dl, kind='cubic', fill_value='extrapolate', assume_sorted=False)
    return f(np.asarray(x_target, dtype=float))


def baseline_asls(y, lam=1e6, p=0.01, niter=100):
    """Asymmetric Least Squares (Eilers & Boelens 2005).

    Algorithme baseline classique, robuste, pure NumPy/SciPy.
      lam   : pénalité de lissage (10^5 à 10^9 typique pour Raman)
      p     : asymétrie (0.001 à 0.1, plus petit = plus d'asymétrie)
      niter : nombre d'itérations (10 suffit en pratique)
    Retourne la baseline (même shape que y).
    """
    from scipy.sparse import diags, eye
    from scipy.sparse.linalg import spsolve
    y = np.asarray(y, dtype=float)
    L = len(y)
    D = diags([1, -2, 1], [0, 1, 2], shape=(L - 2, L))
    D = lam * (D.T @ D)
    w = np.ones(L)
    z = y.copy()
    for _ in range(niter):
        W = diags(w, 0, shape=(L, L))
        Z = W + D
        z = spsolve(Z.tocsc(), w * y)
        w = p * (y > z) + (1 - p) * (y < z)
    return z


def baseline_polynomial(y, degree=3):
    """Fit polynomial baseline. Simple et rapide, mais grossier."""
    y = np.asarray(y, dtype=float)
    x = np.arange(len(y), dtype=float)
    coeffs = np.polyfit(x, y, deg=degree)
    return np.polyval(coeffs, x)


def baseline_snip(y, niter=24, decreasing=True):
    """SNIP (Statistics-sensitive Non-linear Iterative Peak-clipping).
    Très utilisé en gamma-spec et adapté au Raman.
      niter      : largeur de fenêtre maximale (24 = robuste, plus = plus lent)
      decreasing : True = clipping de niter à 1 (plus stable)
    Retourne la baseline.
    """
    y = np.asarray(y, dtype=float).copy()
    # Transformation LLS (Log-Log-Sqrt) pour stabiliser
    z = np.log(np.log(np.sqrt(y - y.min() + 1) + 1) + 1)
    iters = range(niter, 0, -1) if decreasing else range(1, niter + 1)
    for w in iters:
        z_new = z.copy()
        for i in range(w, len(z) - w):
            avg = 0.5 * (z[i - w] + z[i + w])
            if z[i] > avg:
                z_new[i] = avg
        z = z_new
    # Inverse de la transformation LLS
    baseline = (np.exp(np.exp(z) - 1) - 1) ** 2 - 1 + y.min()
    return baseline


class StartupDialog(_BASE_TK):
    """Page d'accueil au lancement de l'application.
    Laisse l'utilisateur choisir :
      - Un mode : Plot Builder (actif) ou Match Search (à venir)
      - Une action : nouveau projet, ouvrir un projet, ou choisir dans la liste
        des projets récents trouvés dans le dossier PROJETS/.

    Retourne via les attributs :
      - self.result_mode     : 'plot' | 'match' | None (si annulé)
      - self.result_project  : chemin du .rpm à ouvrir, ou None pour nouveau
      - self.result_projets_folder : chemin du dossier PROJETS/ effectif
    """

    def __init__(self):
        super().__init__()
        self.title(t('splash.title'))
        # Taille augmentée pour voir tous les boutons en bas sur un écran standard.
        # On calcule une hauteur qui tient sur la plupart des écrans (min 720p)
        self.geometry("860x720")
        self.minsize(760, 680)

        # Icône
        script_dir = _get_app_dir()
        ico = _find_icon_path()
        if ico:
            try:
                self.iconbitmap(ico)
            except Exception as e:
                print(f"⚠ Icône splash non chargée : {e}")

        # Résultats (remplis avant destroy)
        self.result_mode = None
        self.result_project = None
        self.projets_folder = os.path.join(script_dir, SUBDIR_PROJETS)
        # Sous-dossiers dédiés par type de projet
        self.projets_plot_folder  = os.path.join(self.projets_folder,
                                                   SUBDIR_PROJETS_PLOT)
        self.projets_match_folder = os.path.join(self.projets_folder,
                                                   SUBDIR_PROJETS_MATCH)
        try:
            os.makedirs(self.projets_folder, exist_ok=True)
            os.makedirs(self.projets_plot_folder, exist_ok=True)
            os.makedirs(self.projets_match_folder, exist_ok=True)
        except Exception:
            pass
        self.result_projets_folder = self.projets_folder

        # Mode sélectionné : RIEN par défaut (l'utilisateur doit choisir
        # explicitement). value='' = aucune carte n'est en évidence.
        self._selected_mode = tk.StringVar(value='')

        self._build_ui()

        # Centrer à l'écran
        self.update_idletasks()
        w = self.winfo_width()
        h = self.winfo_height()
        x = (self.winfo_screenwidth() - w) // 2
        y = (self.winfo_screenheight() - h) // 2
        self.geometry(f'+{x}+{y}')

        # Quand l'utilisateur ferme la croix, considérer comme annulation
        self.protocol("WM_DELETE_WINDOW", self._on_close)

    def _build_ui(self):
        main = _Frame(self)
        main.pack(fill=tk.BOTH, expand=True, padx=24, pady=18)

        # STRATÉGIE LAYOUT :
        # On pack d'ABORD les éléments du BAS avec side=BOTTOM pour qu'ils
        # soient toujours visibles, puis le reste remplit l'espace restant.

        # ==== FOOTER (ligne Annuler / Ouvrir sélectionné) — PACKÉ EN 1ER ====
        open_sel_row = _Frame(main)
        open_sel_row.pack(side=tk.BOTTOM, fill=tk.X, pady=(10, 0))
        _Button(open_sel_row, text=t('splash.cancel'),
                width=9, command=self._on_close).pack(side=tk.LEFT)
        _AccentButton(open_sel_row,
                       text=f"{ICONS['open']}  {t('splash.open_selected')}",
                       accent='success',
                       command=self._on_open_selected,
                       width=28).pack(side=tk.RIGHT)

        # ==== VERSION + LANGUE + THÈME en tout bas (ligne discrete) ====
        footer = _Frame(main)
        footer.pack(side=tk.BOTTOM, fill=tk.X, pady=(8, 0))
        _Label(footer, text=f"{APP_NAME} — v{APP_VERSION}",
               font=('TkDefaultFont', 8),
               foreground='gray').pack(side=tk.LEFT)
        # Côté droit : thème (tout à droite) puis langue
        self._lang_var = tk.StringVar(value=CURRENT_LANG.upper())
        lang_combo = _Combobox(footer, textvariable=self._lang_var,
                                values=('FR', 'EN'),
                                width=6, state='readonly')
        lang_combo.pack(side=tk.RIGHT, padx=(4, 12))
        _Label(footer, text=t('splash.language'),
               font=('TkDefaultFont', 9)).pack(side=tk.RIGHT)
        self._lang_var.trace_add('write', lambda *a: self._on_language_change())

        # Sélecteur de thème
        self._splash_theme_var = tk.StringVar(value=_load_saved_theme())
        theme_combo = _Combobox(footer, textvariable=self._splash_theme_var,
                                 values=(t('menu.theme_light'),
                                          t('menu.theme_dark'),
                                          t('menu.theme_system')),
                                 width=14, state='readonly')
        # Mettre la valeur d'affichage correspondant au thème courant
        _theme_display = {
            'light':  t('menu.theme_light'),
            'dark':   t('menu.theme_dark'),
            'system': t('menu.theme_system'),
        }
        self._splash_theme_var.set(_theme_display.get(_load_saved_theme(),
                                                       t('menu.theme_system')))
        theme_combo.pack(side=tk.RIGHT, padx=(4, 0))
        _Label(footer, text=t('splash.theme'),
               font=('TkDefaultFont', 9)).pack(side=tk.RIGHT)
        self._splash_theme_var.trace_add('write', lambda *a: self._on_theme_change())

        # ==== HAUT : En-tête ====
        _Label(main, text=APP_NAME,
               font=('TkDefaultFont', 20, 'bold')).pack(anchor='w')
        _Label(main,
               text=t('app.author'),
               font=('TkDefaultFont', 9),
               foreground='gray').pack(anchor='w', pady=(0, 14))

        # ==== Choix du mode (2 cartes côte à côte) ====
        _Label(main, text=t('splash.step1'),
               font=('TkDefaultFont', 11, 'bold')).pack(anchor='w', pady=(0, 6))

        mode_row = _Frame(main)
        mode_row.pack(fill=tk.X, pady=(0, 14))

        self._card_plot = self._build_mode_card(
            parent=mode_row,
            mode_id='plot',
            title=t('splash.plot_title'),
            subtitle=t('splash.plot_subtitle'),
            description=t('splash.plot_desc'),
            active=True)
        self._card_plot.pack(side=tk.LEFT, fill=tk.BOTH, expand=True, padx=(0, 8))

        self._card_match = self._build_mode_card(
            parent=mode_row,
            mode_id='match',
            title=t('splash.match_title'),
            subtitle=t('splash.match_subtitle'),
            description=t('splash.match_desc'),
            active=True)
        self._card_match.pack(side=tk.LEFT, fill=tk.BOTH, expand=True, padx=(8, 0))

        # ==== Actions (nouveau / ouvrir) ====
        _Label(main, text=t('splash.step2'),
               font=('TkDefaultFont', 11, 'bold')).pack(anchor='w', pady=(0, 6))

        action_row = _Frame(main)
        action_row.pack(fill=tk.X, pady=(0, 10))

        _AccentButton(action_row,
                      text=f"{ICONS['add']}   {t('splash.new')}",
                      accent='primary', height=42,
                      command=self._on_new).pack(
            side=tk.LEFT, fill=tk.X, expand=True, padx=(0, 6))

        _Button(action_row,
                text=f"{ICONS['open']}   {t('splash.open')}",
                height=42, command=self._on_open_file).pack(
            side=tk.LEFT, fill=tk.X, expand=True, padx=(6, 0))

        # ==== Liste des projets récents (prend l'espace restant) ====
        header_row = _Frame(main)
        header_row.pack(fill=tk.X, pady=(8, 4))
        _Label(header_row, text=t('splash.recent'),
               font=('TkDefaultFont', 11, 'bold')).pack(side=tk.LEFT)
        _Label(header_row,
               text=t('splash.recent_dir', path=self.projets_folder),
               font=('TkDefaultFont', 8),
               foreground='gray').pack(side=tk.LEFT)
        _Button(header_row,
                text=f"{ICONS['refresh']} {t('splash.refresh')}",
                width=12,
                command=self._refresh_recent_list).pack(side=tk.RIGHT)

        tree_frame = _Frame(main)
        tree_frame.pack(fill=tk.BOTH, expand=True, pady=(2, 0))
        self.recent_tree = ttk.Treeview(tree_frame,
                                         columns=('name', 'date', 'size'),
                                         show='headings', height=7,
                                         selectmode='browse')
        self.recent_tree.heading('name', text=t('splash.col_name'))
        self.recent_tree.heading('date', text=t('splash.col_date'))
        self.recent_tree.heading('size', text=t('splash.col_size'))
        self.recent_tree.column('name', width=380, anchor='w')
        self.recent_tree.column('date', width=160, anchor='w')
        self.recent_tree.column('size', width=90,  anchor='e')
        self.recent_tree.pack(side=tk.LEFT, fill=tk.BOTH, expand=True)
        sb = ttk.Scrollbar(tree_frame, orient='vertical',
                           command=self.recent_tree.yview)
        self.recent_tree.configure(yscrollcommand=sb.set)
        sb.pack(side=tk.RIGHT, fill=tk.Y)

        self.recent_tree.bind('<Double-Button-1>', lambda e: self._on_open_selected())

        # Charger la liste initiale
        self._refresh_recent_list()

    def _on_language_change(self):
        """Change la langue et rebuild le splash pour refléter les nouveaux textes."""
        new_lang = self._lang_var.get().lower()
        if set_language(new_lang):
            _save_language(new_lang)
            # Rebuild la fenêtre : on détruit tous les widgets et on recommence
            for child in self.winfo_children():
                child.destroy()
            self.title(t('splash.title'))
            self._build_ui()

    def _on_theme_change(self):
        """Change le thème du splash et le sauvegarde pour la fenêtre principale."""
        display_val = self._splash_theme_var.get()
        # Inverser le display pour retrouver le code
        reverse_map = {
            t('menu.theme_light'):  'light',
            t('menu.theme_dark'):   'dark',
            t('menu.theme_system'): 'system',
        }
        theme_code = reverse_map.get(display_val, 'system')
        _save_theme(theme_code)
        # Appliquer immédiatement via CustomTkinter
        if HAS_CTK:
            try:
                ctk.set_appearance_mode(theme_code)
            except Exception:
                pass

    def _build_mode_card(self, parent, mode_id, title, subtitle, description,
                          active=True, tag=None):
        """Crée une 'carte' cliquable pour un mode."""
        if HAS_CTK:
            if active:
                fg = ('gray95', 'gray20')
                hover = ('#cfe4ff', '#2c4a6b')
                text_col = ('black', 'white')
                subtitle_col = ('gray30', 'gray70')
            else:
                fg = ('gray92', 'gray18')
                hover = fg
                text_col = ('gray60', 'gray50')
                subtitle_col = ('gray65', 'gray50')
            card = ctk.CTkFrame(parent, fg_color=fg, corner_radius=10,
                                 border_width=2,
                                 border_color=('#1976d2', '#1565c0') if
                                     (active and self._selected_mode.get() == mode_id)
                                     else ('gray80', 'gray30'))
        else:
            card = ttk.Frame(parent, relief='raised', borderwidth=2)
            text_col = None
            subtitle_col = None

        # Titre
        if HAS_CTK:
            ctk.CTkLabel(card, text=title,
                          font=ctk.CTkFont(size=16, weight='bold'),
                          text_color=text_col).pack(anchor='w', padx=14, pady=(12, 0))
            ctk.CTkLabel(card, text=subtitle,
                          text_color=subtitle_col,
                          font=ctk.CTkFont(size=10)).pack(anchor='w', padx=14, pady=(0, 8))
            ctk.CTkLabel(card, text=description,
                          text_color=subtitle_col,
                          justify='left',
                          font=ctk.CTkFont(size=10)).pack(anchor='w', padx=14, pady=(0, 12))
        else:
            ttk.Label(card, text=title, font=('TkDefaultFont', 13, 'bold')).pack(anchor='w', padx=12, pady=(10, 0))
            ttk.Label(card, text=subtitle, foreground='gray').pack(anchor='w', padx=12)
            ttk.Label(card, text=description, justify='left').pack(anchor='w', padx=12, pady=(4, 10))

        # Tag "Bientôt disponible"
        if tag:
            if HAS_CTK:
                tag_lbl = ctk.CTkLabel(card, text=f"  {tag}  ",
                                        fg_color=('#ff9800', '#e68900'),
                                        text_color='white',
                                        corner_radius=10,
                                        font=ctk.CTkFont(size=9, weight='bold'))
                tag_lbl.pack(anchor='w', padx=14, pady=(0, 12))
            else:
                ttk.Label(card, text=f"[{tag}]", foreground='#e68900').pack(anchor='w', padx=12, pady=(0, 10))

        # Rendre la carte cliquable (seulement si active)
        if active:
            def _on_click(event=None):
                self._select_mode(mode_id)
            # Bind sur la carte et tous ses enfants
            card.bind('<Button-1>', _on_click)
            for child in card.winfo_children():
                try:
                    child.bind('<Button-1>', _on_click)
                except Exception:
                    pass

        return card

    def _select_mode(self, mode_id):
        """Change le mode sélectionné et met à jour la bordure des cartes."""
        self._selected_mode.set(mode_id)
        if HAS_CTK:
            try:
                self._card_plot.configure(
                    border_color=('#1976d2', '#1565c0')
                        if mode_id == 'plot' else ('gray80', 'gray30'))
                self._card_match.configure(
                    border_color=('#1976d2', '#1565c0')
                        if mode_id == 'match' else ('gray80', 'gray30'))
            except Exception:
                pass

    def _refresh_recent_list(self):
        """Scanne PROJETS/PlotBuilder/ (.rpm) ET PROJETS/MatchSearch/ (.rms)
        et remplit le Treeview avec les deux. La colonne 'Type' indique
        de quel mode est le projet."""
        for item in self.recent_tree.get_children():
            self.recent_tree.delete(item)
        # Collecter les fichiers des deux sous-dossiers
        projets = []
        for sub_dir, ext, kind in [
            (self.projets_plot_folder,  '.rpm', 'PlotBuilder'),
            (self.projets_match_folder, '.rms', 'MatchSearch'),
        ]:
            if not os.path.isdir(sub_dir):
                continue
            try:
                files = os.listdir(sub_dir)
            except OSError:
                continue
            for f in files:
                if not f.lower().endswith(ext):
                    continue
                full = os.path.join(sub_dir, f)
                try:
                    st = os.stat(full)
                    projets.append((f, full, st.st_mtime, st.st_size, kind))
                except OSError:
                    continue
        # Aussi les anciens .rpm directement dans PROJETS/ (compat ascendante)
        if os.path.isdir(self.projets_folder):
            try:
                for f in os.listdir(self.projets_folder):
                    full = os.path.join(self.projets_folder, f)
                    if not os.path.isfile(full):
                        continue
                    if f.lower().endswith('.rpm'):
                        try:
                            st = os.stat(full)
                            projets.append((f, full, st.st_mtime, st.st_size, 'PlotBuilder'))
                        except OSError:
                            continue
                    elif f.lower().endswith('.rms'):
                        try:
                            st = os.stat(full)
                            projets.append((f, full, st.st_mtime, st.st_size, 'MatchSearch'))
                        except OSError:
                            continue
            except OSError:
                pass
        # Trier par date descendante
        projets.sort(key=lambda x: x[2], reverse=True)

        import datetime
        for name, path, mtime, size, kind in projets:
            date_str = datetime.datetime.fromtimestamp(mtime).strftime('%Y-%m-%d %H:%M')
            if size < 1024:
                size_str = f"{size} o"
            elif size < 1024 * 1024:
                size_str = f"{size / 1024:.1f} Ko"
            else:
                size_str = f"{size / (1024 * 1024):.1f} Mo"
            # Préfixer le nom avec [kind] pour visibilité
            display_name = f"[{kind}] {name}"
            self.recent_tree.insert('', 'end', iid=path,
                                    values=(display_name, date_str, size_str))

    def _on_open_selected(self):
        """Ouvrir le projet actuellement sélectionné dans la liste."""
        sel = self.recent_tree.selection()
        if not sel:
            messagebox.showinfo("Info", t('splash.sel_none'))
            return
        path = sel[0]
        if not os.path.isfile(path):
            messagebox.showerror("Erreur", t('splash.file_missing', path=path))
            self._refresh_recent_list()
            return
        # Le mode est déduit de l'extension (.rpm = plot, .rms = match)
        # Cela évite le besoin de pré-sélectionner un mode pour les projets récents.
        ext = os.path.splitext(path)[1].lower()
        if ext == '.rpm':
            self.result_mode = 'plot'
        elif ext == '.rms':
            self.result_mode = 'match'
        else:
            messagebox.showerror("Format inconnu",
                f"Extension non reconnue : {ext}\n"
                f"Seuls .rpm (Plot Builder) et .rms (Match Search) sont supportés.",
                parent=self)
            return
        self.result_project = path
        # Cette méthode peut être appelée depuis un double-clic sur le
        # Treeview → on utilise la variante after_idle pour laisser
        # ttk::treeview::DoubleClick finir avant de détruire le widget.
        self._safe_destroy_after_dclick()

    def _on_new(self):
        """Démarrer un nouveau projet vide. Si aucun mode n'est sélectionné,
        on demande à l'utilisateur de choisir."""
        mode = self._selected_mode.get()
        if not mode:
            messagebox.showinfo("Choisis un mode",
                "Sélectionne d'abord 'Plot Builder' ou 'Match Search'\n"
                "en cliquant sur la carte correspondante en haut.",
                parent=self)
            return
        self.result_mode = mode
        self.result_project = None
        self._safe_destroy()

    def _on_open_file(self):
        """Ouvrir un projet via filedialog. Le sous-dossier et le filtre
        d'extension dépendent du mode sélectionné :
          - 'plot'  → PROJETS/PlotBuilder/  + filtre *.rpm
          - 'match' → PROJETS/MatchSearch/  + filtre *.rms
          - ''      → racine PROJETS/       + filtre *.rpm;*.rms (aucun mode)
        """
        mode = self._selected_mode.get()
        if mode == 'plot':
            initdir = self.projets_plot_folder
            filetypes = [("Plot Builder Project", "*.rpm"), ("Tous", "*.*")]
            title = "Ouvrir un projet Plot Builder (.rpm)"
            defext = ".rpm"
        elif mode == 'match':
            initdir = self.projets_match_folder
            filetypes = [("Match Search Project", "*.rms"), ("Tous", "*.*")]
            title = "Ouvrir un projet Match Search (.rms)"
            defext = ".rms"
        else:
            # Aucun mode sélectionné → on présente les deux types
            initdir = self.projets_folder
            filetypes = [
                ("Projets Raman (.rpm/.rms)", "*.rpm *.rms"),
                ("Plot Builder", "*.rpm"),
                ("Match Search", "*.rms"),
                ("Tous", "*.*"),
            ]
            title = "Ouvrir un projet"
            defext = ""

        path = filedialog.askopenfilename(
            title=title, initialdir=initdir, filetypes=filetypes,
            defaultextension=defext)
        if not path:
            return

        # Si l'utilisateur n'a pas pré-sélectionné de mode, on déduit du suffixe
        if not mode:
            ext = os.path.splitext(path)[1].lower()
            if ext == '.rpm':
                mode = 'plot'
            elif ext == '.rms':
                mode = 'match'
            else:
                messagebox.showerror("Format inconnu",
                    f"Extension inconnue : {ext}\nChoisis un .rpm ou un .rms.",
                    parent=self)
                return

        self.result_mode = mode
        self.result_project = path
        self._safe_destroy()

    def _on_close(self):
        """Fermer sans rien sélectionner → quitte l'application."""
        self.result_mode = None
        self.result_project = None
        self._safe_destroy()

    def _safe_destroy(self):
        """Détruit la fenêtre splash sans casser CTk.

        Version minimale et conservative :
          - On ne touche PAS aux callbacks `after()` (CTk en a beaucoup
            d'internes pour ses animations / DPI scaling, et les annuler
            casse le destruction CTk avec 'can't delete Tcl command')
          - On ne fait PAS de after_idle(self.destroy) (sauf cas double-clic
            Treeview, voir _safe_destroy_after_dclick)
          - On unbind juste les events de recent_tree pour éviter que le
            handler interne ttk::treeview::DoubleClick s'exécute en boucle
            après destruction.

        Pour les boutons (Nouveau / Ouvrir / croix X), un destroy() direct
        marche bien — le seul cas problématique est le double-clic dans
        le Treeview, qui doit utiliser _safe_destroy_after_dclick à la place.
        """
        try:
            if hasattr(self, 'recent_tree') and self.recent_tree.winfo_exists():
                self.recent_tree.unbind('<Double-Button-1>')
                self.recent_tree.unbind('<<TreeviewSelect>>')
        except Exception:
            pass
        # Destroy direct — laisse CTk gérer son cleanup interne
        try:
            self.destroy()
        except Exception:
            pass

    def _safe_destroy_after_dclick(self):
        """Variante UNIQUEMENT pour le handler de double-clic du Treeview.
        Diffère le destroy() à l'idle pour laisser ttk::treeview::DoubleClick
        finir son traitement interne avant que le widget disparaisse."""
        try:
            if hasattr(self, 'recent_tree') and self.recent_tree.winfo_exists():
                self.recent_tree.unbind('<Double-Button-1>')
                self.recent_tree.unbind('<<TreeviewSelect>>')
        except Exception:
            pass
        try:
            self.after_idle(self.destroy)
        except Exception:
            try:
                self.destroy()
            except Exception:
                pass


class RamanPlotGUI(_BASE_TK):

    def __init__(self, initial_project=None, mode='plot',
                 initial_sample_folder=None, initial_spectrum_file=None,
                 _skip_super_init=False):
        """initial_project : chemin d'un .rpm à charger au démarrage (ou None).
        mode : 'plot' (Plot Builder) — 'match' à venir.
        initial_sample_folder : dossier sample à activer automatiquement (typiquement
            utilisé par Match Search pour passer un spectre nettoyé).
        initial_spectrum_file : nom du fichier .txt à pré-cocher comme visible.
        _skip_super_init : flag interne — si True, on ne fait PAS le
            super().__init__() (utilisé par le wrapper Toplevel qui a déjà
            initialisé la fenêtre Tk avant d'appeler ce __init__). Ne JAMAIS
            mettre à True manuellement."""
        if not _skip_super_init:
            super().__init__()
        self.initial_project = initial_project
        self.app_mode = mode
        self.initial_sample_folder  = initial_sample_folder
        self.initial_spectrum_file  = initial_spectrum_file

        # --- Résolution du dossier principal ---
        # _get_app_dir() gère le cas PyInstaller : dossier de l'exe au lieu de _internal/
        script_dir = _get_app_dir()

        self.root_dir = script_dir

        icon_path = _find_icon_path()
        if icon_path:
            try:
                self.iconbitmap(icon_path)
                self.iconbitmap(default=icon_path)
            except Exception as e:
                print(f"⚠ Icône fenêtre non chargée : {e}")
        else:
            print("⚠ Icône Raman_GUI.ico introuvable")

        self.title("Raman Plot|Match Builder")
        self.geometry("1600x900")
        self.minsize(1280, 720)

        # --- Dossiers (tous relatifs au dossier principal) ---
        samples_path = os.path.join(script_dir, SUBDIR_SAMPLES)
        rruff_path   = os.path.join(script_dir, SUBDIR_RRUFF)
        # Plot Builder sauve ses .rpm dans PROJETS/PlotBuilder/ (au lieu de
        # PROJETS/ directement) pour bien séparer des .rms de Match Search.
        projets_path = os.path.join(script_dir, SUBDIR_PROJETS, SUBDIR_PROJETS_PLOT)
        save_path    = os.path.join(script_dir, SUBDIR_SAVE)
        csv_save_path = os.path.join(save_path, SUBDIR_CSV_SAVE)
        figure_save_path = os.path.join(save_path, SUBDIR_FIGURE_SAVE)
        rapport_save_path = os.path.join(save_path, SUBDIR_RAPPORTS_SAVE)
        # Créer PROJETS et SAUVEGARDE automatiquement s'ils n'existent pas
        for p, label in ((projets_path, 'PROJETS/PlotBuilder'), (save_path, 'SAUVEGARDE'),
                         (csv_save_path, 'CSV_SAVE'), (figure_save_path, 'FIGURE_SAVE'), (rapport_save_path, 'RAPPORTS_SAVE')):
            try:
                os.makedirs(p, exist_ok=True)
            except Exception as e:
                print(f"⚠ Impossible de créer le dossier {label} : {e}")

        # -------- État interne --------
        # base_folder = dossier contenant les samples (SAMPLES/ par défaut)
        self.base_folder_var    = tk.StringVar(value=samples_path)
        self.lib_folder_var     = tk.StringVar(value=rruff_path)
        self.projets_folder_var = tk.StringVar(value=projets_path)
        self.save_root_var      = tk.StringVar(value=save_path)
        self.csv_save_folder_var = tk.StringVar(value=csv_save_path)
        self.figure_save_folder_var = tk.StringVar(value=figure_save_path)
        self.rapport_save_folder_var = tk.StringVar(value=rapport_save_path)
        self.sample_folder_var  = tk.StringVar(value='')
        # Sous-dossier actif à l'intérieur de DATABASE_RRUFF (si la base est
        # organisée en sous-collections, comme RRUFF_oriented/, RRUFF_unoriented/)
        # Chaîne vide = pas de sous-dossier, on scanne directement lib_folder.
        self.database_folder_var = tk.StringVar(value='')

        self.spectrum_files = []
        # Spectres : liste de dicts {'filename': str, 'display_name': str, 'visible': bool, 'color': str or None}
        self.spectra_meta   = []
        # Refs : liste de dicts {'mineral', 'filename', 'laser', 'display_name', 'visible', 'color': str or None}
        self.refs           = []
        # Pics : liste de dicts avec champs étendus
        self.peaks          = []
        # Annotations libres : liste de dicts {'x': float, 'y': float, 'text': str, 'color': str}
        self.annotations    = []
        # Mode d'ajout d'annotation (False = normal, True = en attente de clic)
        self._annotation_mode = False
        # État du drag d'annotation
        self._drag_annotation_idx = None
        self._drag_start_xy = None
        self._drag_orig_xy = None

        # -------- Undo / Redo --------
        # Stacks d'états sérialisés. Chaque entrée est un tuple (label, state_dict).
        # On limite à 50 états pour éviter l'explosion mémoire.
        from collections import deque
        self._undo_stack = deque(maxlen=50)
        self._redo_stack = deque(maxlen=50)
        # Flag pour bloquer les appels à _push_undo pendant restore (évite les boucles)
        self._restoring_state = False

        # -------- Options de plot --------
        self.title_var        = tk.StringVar(value='')
        self.x_margin_var     = tk.DoubleVar(value=DEFAULTS['x_margin'])
        self.sample_laser_var = tk.StringVar(value=DEFAULTS['sample_laser'])
        self.default_ref_laser_var = tk.StringVar(value=DEFAULTS['ref_laser'])

        # Plage X / Y — vide = auto
        self.xmin_var = tk.StringVar(value='')
        self.xmax_var = tk.StringVar(value='')
        self.ymin_var = tk.StringVar(value='')
        self.ymax_var = tk.StringVar(value='')

        # Dimensions de la figure (pouces)
        self.fig_width_var  = tk.DoubleVar(value=DEFAULTS['fig_width'])
        self.fig_height_var = tk.DoubleVar(value=DEFAULTS['fig_height'])
        # Ajustement automatique de la largeur du graph à celle du panneau
        self.fit_width_var = tk.BooleanVar(value=True)

        # Status bar vars — créées tôt pour que _schedule_update puisse
        # les utiliser avant que _build_ui soit appelé
        self.status_var        = tk.StringVar(value="Prêt.")
        self.status_counts_var = tk.StringVar(value="")
        self.status_theme_var  = tk.StringVar(value="")

        # Options visuelles
        self.label_mode_var       = tk.StringVar(value=DEFAULTS['label_mode'])
        self.color_by_mineral_var = tk.BooleanVar(value=True)
        self.show_peak_marker_var = tk.BooleanVar(value=True)  # défaut global
        self.auto_stagger_var     = tk.BooleanVar(value=True)
        self.sample_palette_var   = tk.StringVar(value=DEFAULTS['sample_palette'])
        self.ref_palette_var      = tk.StringVar(value=DEFAULTS['ref_palette'])
        self.sample_linestyle_var = tk.StringVar(value=DEFAULTS['sample_linestyle'])
        self.ref_linestyle_var    = tk.StringVar(value=DEFAULTS['ref_linestyle'])
        # Offset horizontal (translation X) appliqué LIVE aux spectres samples
        # uniquement (pas aux références). Permet de re-caler visuellement
        # un sample dont la calibration en cm⁻¹ est légèrement décalée.
        # Valeur en cm⁻¹, signée (positif = décale vers la droite).
        self.sample_x_offset_var  = tk.DoubleVar(value=0.0)
        # Thème : charger celui sauvegardé (modifiable depuis le splash ou l'app)
        self.theme_var            = tk.StringVar(value=_load_saved_theme())
        self.panel_collapsed      = False  # état du repli du panneau gauche

        # Sauvegarde
        self.save_dir_var  = tk.StringVar(value=save_path)
        self.save_name_var = tk.StringVar(value=DEFAULTS['save_name'])
        self.dpi_var       = tk.IntVar(value=DEFAULTS['dpi'])
        self.fmt_png_var   = tk.BooleanVar(value=True)
        self.fmt_pdf_var   = tk.BooleanVar(value=True)
        self.fmt_svg_var   = tk.BooleanVar(value=False)
        # Signature / watermark discrète en bas de figure
        self.watermark_var = tk.BooleanVar(value=False)

        # Live update
        self.live_update_var = tk.BooleanVar(value=True)
        self._update_job = None

        # cache : couleur par minéral (calculé à chaque tracé)
        self._mineral_colors = {}

        # cache : minéraux disponibles dans le dossier RRUFF
        # (calculé une fois, invalidé quand le dossier change)
        self._rruff_cache = None
        self._rruff_cache_key = None

        self._build_ui()
        self._refresh_sample_folders()
        self._setup_auto_updates()
        self._setup_keyboard_shortcuts()

        # Synchroniser save_dir_var quand save_root_var change (dossier racine
        # SAUVEGARDE/ modifié depuis la section 1)
        self.save_root_var.trace_add('write',
            lambda *a: self.save_dir_var.set(self.save_root_var.get()))

        # Appliquer le thème initial (après la construction complète de la GUI)
        self._apply_theme(self.theme_var.get())

        # --- Système de détection des changements non sauvegardés ---
        self._dirty = False
        self._current_project_path = None
        self.protocol("WM_DELETE_WINDOW", self._on_close_request)

        # Si un projet initial a été fourni (depuis le splash), le charger
        if self.initial_project and os.path.isfile(self.initial_project):
            self.after(100, lambda: self._load_project_path(self.initial_project))

        # Si un sample folder initial a été fourni (depuis Match Search),
        # l'ajouter aux samples chargés et activer le spectre désigné
        elif self.initial_sample_folder and os.path.isdir(self.initial_sample_folder):
            self.after(150, self._apply_initial_sample_from_match)

    # ============================================================
    # CONSTRUCTION UI
    # ============================================================
    def _build_ui(self):
        # --- Préparer les menus déroulants (tk.Menu pour compatibilité) ---
        self._build_menubar()

        # Container principal (toolbar en haut, paned en dessous)
        main = _Frame(self)
        main.pack(fill=tk.BOTH, expand=True)

        # --- Barre d'outils moderne (CTk) avec les menus Fichier/Édition/… ---
        self._build_toolbar(main)

        # --- Status bar en bas (réserver l'espace AVANT le paned) ---
        self._build_statusbar(main)

        # PanedWindow horizontal : panneau gauche (config), bouton repli, plot
        self.paned = tk.PanedWindow(main, orient=tk.HORIZONTAL,
                                     sashrelief='raised', sashwidth=5,
                                     sashpad=2, bg='#d9d9d9')
        self.paned.pack(fill=tk.BOTH, expand=True)

        # === Panneau gauche ===
        self.left_frame = ttk.Frame(self.paned)
        self.paned.add(self.left_frame, minsize=600, width=600, stretch='never')

        canvas_cfg = tk.Canvas(self.left_frame, borderwidth=0, highlightthickness=0)
        scrollbar = ttk.Scrollbar(self.left_frame, orient="vertical",
                                  command=canvas_cfg.yview)
        scroll_frame = ttk.Frame(canvas_cfg)
        scroll_frame.bind(
            "<Configure>",
            lambda e: canvas_cfg.configure(scrollregion=canvas_cfg.bbox("all"))
        )
        canvas_cfg.create_window((0, 0), window=scroll_frame, anchor="nw")
        canvas_cfg.configure(yscrollcommand=scrollbar.set)
        canvas_cfg.pack(side="left", fill="both", expand=True)
        scrollbar.pack(side="right", fill="y")
        self._canvas_cfg = canvas_cfg

        def _on_mousewheel(event):
            widget = self.winfo_containing(event.x_root, event.y_root)
            if widget is None:
                return
            w = widget
            in_main = False
            # Delta normalisé : 3 "units" par cran de molette pour glisser plus vite
            scroll_units = int(-1 * (event.delta / 120)) * 3
            while w is not None:
                if isinstance(w, (tk.Listbox, tk.Text, ttk.Treeview)):
                    try:
                        w.yview_scroll(scroll_units, "units")
                    except tk.TclError:
                        pass
                    return "break"
                if w is canvas_cfg or w is scroll_frame:
                    in_main = True
                    break
                w = w.master
            if in_main:
                canvas_cfg.yview_scroll(scroll_units, "units")

        canvas_cfg.bind_all("<MouseWheel>", _on_mousewheel)
        canvas_cfg.bind_all("<Button-4>", lambda e: _on_mousewheel(
            type('E', (), {'x_root': e.x_root, 'y_root': e.y_root, 'delta': 120})()))
        canvas_cfg.bind_all("<Button-5>", lambda e: _on_mousewheel(
            type('E', (), {'x_root': e.x_root, 'y_root': e.y_root, 'delta': -120})()))

        self._build_config_panel(scroll_frame)

        # === Panneau droit (plot) + bouton de repli en haut ===
        self.right_frame = ttk.Frame(self.paned)
        self.paned.add(self.right_frame, minsize=500, stretch='always')

        # Bouton flottant de repli / déploiement, placé en haut à gauche du plot
        self.toggle_panel_btn = ttk.Button(
            self.right_frame, text='◀', width=3,
            command=self._toggle_left_panel)
        # On va placer ce bouton après _build_plot_panel
        self._build_plot_panel(self.right_frame)
        self.toggle_panel_btn.place(x=2, y=2)  # coin haut-gauche

    # ------------------------------------------------------------
    def _build_statusbar(self, parent):
        """Barre de statut persistante en bas de la fenêtre — 3 zones."""
        # On la met en side=BOTTOM pour qu'elle reste fixée en bas,
        # au-dessus de la zone systeme.
        bar = _Frame(parent, height=26)
        bar.pack(side=tk.BOTTOM, fill=tk.X)

        # Zone 1 (gauche) : message principal
        lbl_main = _Label(bar, textvariable=self.status_var,
                          anchor='w',
                          font=('TkDefaultFont', 9))
        lbl_main.pack(side=tk.LEFT, fill=tk.X, expand=True, padx=10, pady=2)

        # Barre de progression (cachée par défaut, visible pendant loads longs)
        if HAS_CTK:
            self.status_progress = ctk.CTkProgressBar(bar, width=140, height=14)
            self.status_progress.set(0)
        else:
            self.status_progress = ttk.Progressbar(bar, length=140, mode='determinate',
                                                     maximum=100)
        # Pas pack par défaut (affiché à la demande via _show_progress)

        # Séparateur vertical
        ttk.Separator(bar, orient='vertical').pack(side=tk.LEFT, fill=tk.Y,
                                                     padx=4, pady=3)

        # Zone 2 (centre) : compteurs (nb spectres visibles / refs / pics)
        lbl_counts = _Label(bar, textvariable=self.status_counts_var,
                             anchor='center',
                             font=('TkDefaultFont', 9))
        lbl_counts.pack(side=tk.LEFT, padx=10)

        ttk.Separator(bar, orient='vertical').pack(side=tk.LEFT, fill=tk.Y,
                                                     padx=4, pady=3)

        # Zone 3 (droite) : thème actif
        lbl_theme = _Label(bar, textvariable=self.status_theme_var,
                            anchor='e',
                            font=('TkDefaultFont', 9))
        lbl_theme.pack(side=tk.RIGHT, padx=10)

        # Mettre à jour les zones 2 et 3 régulièrement
        self._update_status_counts()
        self._update_status_theme()

    def _show_progress(self, initial=0):
        """Affiche la barre de progression dans la status bar (cachée par défaut)."""
        try:
            if HAS_CTK:
                self.status_progress.set(initial / 100)
            else:
                self.status_progress['value'] = initial
            # Pack à gauche de la zone compteurs
            self.status_progress.pack(side=tk.LEFT, padx=6, pady=3)
            self.update_idletasks()
        except Exception:
            pass

    def _set_progress(self, value):
        """Met à jour la barre (0-100). update_idletasks pour rafraîchissement live."""
        try:
            if HAS_CTK:
                self.status_progress.set(max(0, min(100, value)) / 100)
            else:
                self.status_progress['value'] = max(0, min(100, value))
            self.update_idletasks()
        except Exception:
            pass

    def _hide_progress(self):
        """Cache la barre."""
        try:
            self.status_progress.pack_forget()
        except Exception:
            pass

    def _update_status_counts(self):
        """Met à jour la zone centrale de la barre de statut."""
        try:
            n_spec = sum(1 for s in getattr(self, 'spectra_meta', [])
                         if s.get('visible', False))
            n_refs = sum(1 for r in getattr(self, 'refs', [])
                         if r.get('visible', True))
            n_peaks = len(getattr(self, 'peaks', []))
            base = t('status.counts',
                     n_spec=n_spec, n_refs=n_refs, n_peaks=n_peaks)
            # Enrichissement : plage spectrale couverte (bornes X actuelles du plot)
            extra = ""
            try:
                if hasattr(self, 'figure') and (n_spec + n_refs) > 0:
                    axes = self.figure.axes
                    if axes:
                        xmin, xmax = axes[0].get_xlim()
                        # N'afficher que si plage raisonnable
                        if xmax - xmin > 10 and 0 < xmax < 5000:
                            extra = f"  ·  {xmin:.0f}–{xmax:.0f} cm⁻¹"
            except Exception:
                pass
            self.status_counts_var.set(base + extra)
        except Exception:
            pass

    def _update_status_theme(self):
        """Met à jour l'affichage du thème courant."""
        theme = self.theme_var.get()
        label = {'light':  t('status.theme_light'),
                 'dark':   t('status.theme_dark'),
                 'system': t('status.theme_system')}.get(theme, theme)
        self.status_theme_var.set(label)

    # ------------------------------------------------------------
    def _build_menubar(self):
        """Barre de menu moderne (CTk) avec menus déroulants — traduits."""
        # --- Menu Fichier ---
        self._m_file = tk.Menu(self, tearoff=0)
        self._m_file.add_command(label=t('menu.new_project'),
                           accelerator="Ctrl+R", command=self._reset_all)
        self._m_file.add_separator()
        self._m_file.add_command(label=t('menu.open_project'),
                           accelerator="Ctrl+O", command=self.load_project)
        self._m_file.add_command(label=t('menu.save_project'),
                           accelerator="Ctrl+S", command=self.save_project)
        self._m_file.add_command(label=t('menu.save_project_as'),
                           accelerator="Ctrl+Shift+S", command=self.save_project_as)
        # Sous-menu "Projets récents"
        self._m_recent = tk.Menu(self._m_file, tearoff=0)
        self._m_file.add_cascade(label=t('menu.recent_projects'), menu=self._m_recent)
        # Configure un postcommand sur le menu file pour rebuild la liste
        # à chaque ouverture (ainsi la liste est toujours à jour)
        self._m_file.configure(postcommand=self._refresh_recent_menu)
        self._m_file.add_separator()
        self._m_file.add_command(label=t('menu.export_fig'),
                           accelerator="Ctrl+E", command=self.save_figure)
        self._m_file.add_command(label=t('menu.export_peaks'),
                           command=self._export_peaks_csv)
        self._m_file.add_separator()
        self._m_file.add_command(label=t('menu.back_home'),
                           command=self._return_to_startup)
        self._m_file.add_command(label=t('menu.quit'), accelerator="Ctrl+Q",
                           command=self._on_close_request)

        # --- Menu Édition ---
        self._m_edit = tk.Menu(self, tearoff=0)
        self._m_edit.add_command(label=t('menu.undo'), accelerator="Ctrl+Z",
                           command=self.undo)
        self._m_edit.add_command(label=t('menu.redo'), accelerator="Ctrl+Y",
                           command=self.redo)
        self._m_edit.add_separator()
        self._m_edit.add_command(label=t('menu.force_update'),
                           accelerator="F5", command=self.update_plot)
        self._m_edit.add_separator()
        self._m_edit.add_command(label=t('menu.select_all'),
                           command=self._select_all_spectra)
        self._m_edit.add_command(label=t('menu.deselect_all'),
                           command=self._deselect_all_spectra)
        self._m_edit.add_separator()
        self._m_edit.add_command(label=t('menu.clear_peaks'),
                           command=self._clear_peaks)

        # --- Menu Affichage ---
        self._m_view = tk.Menu(self, tearoff=0)
        self._theme_menu_var = tk.StringVar(value=self.theme_var.get())
        self._m_view.add_radiobutton(label=t('menu.theme_light'), value='light',
                                variable=self._theme_menu_var,
                                command=lambda: self._apply_theme('light'))
        self._m_view.add_radiobutton(label=t('menu.theme_dark'), value='dark',
                                variable=self._theme_menu_var,
                                command=lambda: self._apply_theme('dark'))
        self._m_view.add_radiobutton(label=t('menu.theme_system'), value='system',
                                variable=self._theme_menu_var,
                                command=lambda: self._apply_theme('system'))
        self._m_view.add_separator()
        self._m_view.add_command(label=t('menu.toggle_panel'),
                           command=self._toggle_left_panel)
        self._m_view.add_command(label=t('menu.live_toggle'),
                           command=lambda: self.live_update_var.set(
                               not self.live_update_var.get()))
        self._m_view.add_separator()
        # --- Sous-menu Langue ---
        self._m_lang = tk.Menu(self._m_view, tearoff=0)
        self._lang_menu_var = tk.StringVar(value=CURRENT_LANG)
        self._m_lang.add_radiobutton(label="Français", value='fr',
                                      variable=self._lang_menu_var,
                                      command=lambda: self._change_language('fr'))
        self._m_lang.add_radiobutton(label="English", value='en',
                                      variable=self._lang_menu_var,
                                      command=lambda: self._change_language('en'))
        self._m_view.add_cascade(label=t('menu.language'), menu=self._m_lang)

        # --- Menu Aide ---
        self._m_help = tk.Menu(self, tearoff=0)
