    def _build_config_panel(self, parent):
        pad = dict(padx=8, pady=4)

        # === 1. DOSSIERS RACINES ===
        grp = _LabelFrame(parent,
            text=t('panel.sec1.title', root=os.path.basename(self.root_dir)))
        grp.pack(fill=tk.X, **pad)
        grp_in = _lf_inner(grp)

        # Ligne 1 : SAMPLES
        _Label(grp_in, text=f"{SUBDIR_SAMPLES}/ :").grid(row=0, column=0, sticky='w', padx=4, pady=2)
        e_s = _Entry(grp_in, textvariable=self.base_folder_var, width=55)
        e_s.grid(row=0, column=1, sticky='ew', padx=4, pady=2)
        Tooltip(e_s, "Dossier contenant les sous-dossiers par sample.\n"
                     "Chaque sous-dossier héberge les .txt d'un échantillon.")
        b_s = _Button(grp_in, text="…", width=3, command=self._browse_base_folder)
        b_s.grid(row=0, column=2, padx=2)
        Tooltip(b_s, "Parcourir pour changer le dossier SAMPLES")

        # Ligne 2 : DATABASE_RRUFF
        _Label(grp_in, text=f"{SUBDIR_RRUFF}/ :").grid(row=1, column=0, sticky='w', padx=4, pady=2)
        e_r = _Entry(grp_in, textvariable=self.lib_folder_var, width=55)
        e_r.grid(row=1, column=1, sticky='ew', padx=4, pady=2)
        Tooltip(e_r, "Dossier racine contenant les fichiers .txt RRUFF\n"
                     "(ou sous-dossiers de collections distinctes)")
        b_r = _Button(grp_in, text="…", width=3, command=self._browse_lib_folder)
        b_r.grid(row=1, column=2, padx=2)
        Tooltip(b_r, "Parcourir pour changer le dossier RRUFF")

        # Ligne 3 : PROJETS
        _Label(grp_in, text=f"{SUBDIR_PROJETS}/ :").grid(row=2, column=0, sticky='w', padx=4, pady=2)
        e_p = _Entry(grp_in, textvariable=self.projets_folder_var, width=55)
        e_p.grid(row=2, column=1, sticky='ew', padx=4, pady=2)
        Tooltip(e_p, "Dossier où sont sauvegardés/ouverts les fichiers .rpm")
        b_p = _Button(grp_in, text="…", width=3, command=self._browse_projets_folder)
        b_p.grid(row=2, column=2, padx=2)
        Tooltip(b_p, "Parcourir pour changer le dossier des projets")

        # Ligne 4 : SAUVEGARDE (figures exportées)
        _Label(grp_in, text=f"{SUBDIR_SAVE}/ :").grid(row=3, column=0, sticky='w', padx=4, pady=2)
        e_sv = _Entry(grp_in, textvariable=self.save_root_var, width=55)
        e_sv.grid(row=3, column=1, sticky='ew', padx=4, pady=2)
        Tooltip(e_sv, "Dossier par défaut où les figures sont exportées\n"
                      "(PNG/PDF/SVG via le bouton SAUVEGARDER)")
        b_sv = _Button(grp_in, text="…", width=3, command=self._browse_save_root)
        b_sv.grid(row=3, column=2, padx=2)
        Tooltip(b_sv, "Parcourir pour changer le dossier de sauvegarde")

        grp_in.columnconfigure(1, weight=1)

        # === 2. SPECTRES ===
        grp2 = _LabelFrame(parent, text=t('panel.sec2.title'))
        grp2.pack(fill=tk.X, **pad)
        grp2_in = _lf_inner(grp2)

        # Sample actif (déplacé depuis section 1)
        sample_row = _Frame(grp2_in)
        sample_row.pack(fill=tk.X, padx=4, pady=(4, 2))
        _Label(sample_row, text=t('panel.sample_active'), width=16).pack(side=tk.LEFT)
        self.sample_combo = _Combobox(sample_row, textvariable=self.sample_folder_var,
                                       state='readonly')
        self.sample_combo.pack(side=tk.LEFT, fill=tk.X, expand=True, padx=4)
        # Pas de trace_add ici : le changement de sample_folder_var ne doit PAS
        # remplir automatiquement la liste de spectres. La liste ne se remplit
        # qu'explicitement via le bouton ➕ (dialog de sélection) ou via le load
        # d'un projet sauvegardé. Le combobox ne sert qu'à pointer le dossier
        # source pour le bouton ➕.
        # Bouton ➕ pour AJOUTER (cumuler) les fichiers du sample courant à
        # la liste sans remplacer ce qui y est déjà. Pratique pour comparer
        # des spectres venant de plusieurs samples.
        self._btn_add_folder = _Button(sample_row, text="➕", width=3,
                                         command=self._add_current_sample_folder)
        self._btn_add_folder.pack(side=tk.LEFT, padx=2)
        try:
            Tooltip(self._btn_add_folder, t('panel.btn_add_folder_tip'))
        except Exception:
            pass
        _Button(sample_row, text="↻", width=3,
                command=self._refresh_sample_folders).pack(side=tk.LEFT, padx=2)

        # Laser sample
        laser_sample_row = _Frame(grp2_in)
        laser_sample_row.pack(fill=tk.X, padx=4, pady=(2, 4))
        _Label(laser_sample_row, text=t('panel.sample_laser'), width=16).pack(side=tk.LEFT)
        _Combobox(laser_sample_row, textvariable=self.sample_laser_var, width=10,
                  values=('325 nm', '405 nm', '457 nm', '488 nm', '514 nm',
                          '532 nm', '633 nm', '647 nm', '785 nm', '830 nm', '1064 nm')).pack(side=tk.LEFT, padx=4)

        tree_frame2 = _Frame(grp2_in)
        tree_frame2.pack(fill=tk.X, padx=4, pady=4)
        self.spectra_tree = ttk.Treeview(tree_frame2,
                                          columns=('vis', 'color', 'ls', 'file', 'alias', 'laser'),
                                          show='headings', height=6,
                                          selectmode='extended')
        self.spectra_tree.heading('vis',   text='✓')
        self.spectra_tree.heading('color', text='🎨')
        self.spectra_tree.heading('ls',    text='╌')
        self.spectra_tree.heading('file',  text=t('panel.col_file'))
        self.spectra_tree.heading('alias', text=t('panel.col_alias'))
        self.spectra_tree.heading('laser', text=t('panel.col_laser'))
        self.spectra_tree.column('vis',   width=28,  anchor='center', stretch=False)
        self.spectra_tree.column('color', width=32,  anchor='center', stretch=False)
        self.spectra_tree.column('ls',    width=32,  anchor='center', stretch=False)
        self.spectra_tree.column('file',  width=160, anchor='w')
        self.spectra_tree.column('alias', width=120, anchor='w')
        self.spectra_tree.column('laser', width=64,  anchor='center', stretch=False)
        self.spectra_tree.pack(side=tk.LEFT, fill=tk.X, expand=True)
        spec_sb = ttk.Scrollbar(tree_frame2, orient='vertical',
                                 command=self.spectra_tree.yview)
        self.spectra_tree.configure(yscrollcommand=spec_sb.set)
        spec_sb.pack(side=tk.RIGHT, fill=tk.Y)

        self.spectra_tree.bind('<Button-1>', self._on_spectrum_click)
        self.spectra_tree.bind('<Double-Button-1>', self._on_spectrum_dblclick)
        self.spectra_tree.bind('<Button-3>', self._on_spectrum_rightclick)

        btns = _Frame(grp2_in)
        btns.pack(fill=tk.X, padx=4, pady=(0, 4))
        # Largeur + hauteur fixes pour éviter d'agrandir le panneau quand on
        # ajoute des boutons. En CTk : pixels ; en ttk : caractères pour width
        # (height ignoré sur ttk.Button).
        _BTN_W = 88 if HAS_CTK else 10
        _BTN_H = 24
        b1 = _Button(btns, text=f"{ICONS['check']} {t('panel.btn_select_all')}",
                     command=self._select_all_spectra, width=_BTN_W, height=_BTN_H)
        b1.pack(side=tk.LEFT, padx=2)
        Tooltip(b1, t('tip.btn_select_all'))

        b2 = _Button(btns, text=f"{ICONS['cancel']} {t('panel.btn_deselect')}",
                     command=self._deselect_all_spectra, width=_BTN_W, height=_BTN_H)
        b2.pack(side=tk.LEFT, padx=2)
        Tooltip(b2, t('tip.btn_deselect'))

        b3 = _Button(btns, text=f"{ICONS['edit']} {t('panel.btn_rename')}",
                     command=self._rename_spectrum_dialog, width=_BTN_W, height=_BTN_H)
        b3.pack(side=tk.LEFT, padx=2)
        Tooltip(b3, t('tip.btn_modify_spec'))

        b4 = _Button(btns, text=f"{ICONS['eye']} {t('panel.btn_toggle_vis')}",
                     command=self._toggle_spectra_visibility, width=_BTN_W, height=_BTN_H)
        b4.pack(side=tk.LEFT, padx=2)
        Tooltip(b4, t('tip.btn_toggle'))

        # Retirer un (ou plusieurs) spectre(s) de la liste, sans toucher au disque.
        # Utile en multi-dossiers pour nettoyer la liste après un ➕ massif.
