        _Label(grp5_in, text=t('panel.opt_ymax')).grid(row=row, column=2, sticky='e', padx=4)
        _Entry(grp5_in, textvariable=self.ymax_var, width=8).grid(row=row, column=3, sticky='w', padx=2)

