        _Combobox(grp5_in, textvariable=self.ref_linestyle_var, width=12, state='readonly',
                  values=ls_values).grid(row=row, column=2, columnspan=2, sticky='w', padx=4)

        # --- Offset horizontal (translation X) pour les samples ---
        row += 1
        ttk.Separator(grp5_in, orient='horizontal').grid(
            row=row, column=0, columnspan=4, sticky='ew', pady=6)
        row += 1
        _Label(grp5_in, text="Offset X samples (cm⁻¹) :",
               font=('TkDefaultFont', 9, 'bold')).grid(
            row=row, column=0, columnspan=2, sticky='w', padx=4, pady=2)
        # Slider + Entry liés via la même var
        # Pour gérer l'undo proprement sans pusher 1 snapshot par pixel
        # de glissement, on utilise une stratégie ButtonPress/Release :
        # - ButtonPress  → on mémorise la valeur avant glissement
        # - ButtonRelease → si la valeur a changé, on push 1 seul undo
        # Le snapshot est généré APRÈS coup avec la valeur d'origine.
        self._offset_drag_start_value = None
        offset_row = _Frame(grp5_in)
        offset_row.grid(row=row, column=2, columnspan=2, sticky='ew', padx=4)
        offset_scale = ttk.Scale(offset_row, from_=-100, to=100,
                                   orient='horizontal',
                                   variable=self.sample_x_offset_var,
                                   command=lambda v: self._on_offset_changed())
        offset_scale.pack(side=tk.LEFT, fill=tk.X, expand=True)
        # Capturer la valeur au début du glissement et pusher undo au release
        offset_scale.bind('<ButtonPress-1>',
                           lambda e: self._on_offset_drag_start())
        offset_scale.bind('<ButtonRelease-1>',
                           lambda e: self._on_offset_drag_end())
        offset_entry = _Entry(offset_row, textvariable=self.sample_x_offset_var,
                                width=8)
        offset_entry.pack(side=tk.LEFT, padx=(4, 0))
        # Pour l'Entry, push undo sur Return ou perte de focus si valeur changée
        offset_entry.bind('<FocusIn>',
                           lambda e: self._on_offset_drag_start())
        offset_entry.bind('<Return>',
                           lambda e: self._on_offset_drag_end())
        offset_entry.bind('<FocusOut>',
                           lambda e: self._on_offset_drag_end())
        # Bouton reset offset
        row += 1
        def _reset_offset_with_undo():
            # Push undo SEULEMENT si la valeur change vraiment
            try:
                cur = float(self.sample_x_offset_var.get())
            except (tk.TclError, ValueError):
                cur = 0.0
            if cur != 0.0:
                self._push_undo("Reset offset X")
            self.sample_x_offset_var.set(0.0)
            self._on_offset_changed()
        offset_reset = _Button(grp5_in, text=t('btn.reset_offset_zero'),
                                command=_reset_offset_with_undo,
                                width=22)
        offset_reset.grid(row=row, column=0, columnspan=4,
                           sticky='w', padx=4, pady=(2, 4))
        Tooltip(offset_reset, "Translate horizontalement les courbes Sample\n"
                                "dans le plot (calibration cm⁻¹ — utile si le\n"
                                "spectre est légèrement décalé par rapport aux\n"
                                "références RRUFF). N'affecte PAS les données\n"
                                "originales — uniquement l'affichage.")

        grp5_in.columnconfigure(1, weight=1)
        grp5_in.columnconfigure(3, weight=1)

        # === 6. ACTIONS ===
        grp6 = _LabelFrame(parent, text=t('panel.sec6.title'))
