    # ------------------------------------------------------------
    def _build_plot_panel(self, parent):
        # Container avec scrollbars : la figure garde sa taille même si la
        # fenêtre est plus grande ou plus petite (scrollbars au besoin).
        container = ttk.Frame(parent)
        container.pack(fill=tk.BOTH, expand=True)

        self.plot_scroll_canvas = tk.Canvas(container, bg='#f5f5f5',
                                             highlightthickness=0, borderwidth=0)
        h_sb = ttk.Scrollbar(container, orient='horizontal',
                             command=self.plot_scroll_canvas.xview)
        v_sb = ttk.Scrollbar(container, orient='vertical',
                             command=self.plot_scroll_canvas.yview)
        self.plot_scroll_canvas.configure(
            xscrollcommand=h_sb.set, yscrollcommand=v_sb.set)

        self.plot_scroll_canvas.grid(row=0, column=0, sticky='nsew')
        v_sb.grid(row=0, column=1, sticky='ns')
        h_sb.grid(row=1, column=0, sticky='ew')
        container.rowconfigure(0, weight=1)
        container.columnconfigure(0, weight=1)

        # Figure matplotlib à la taille demandée (DPI=100 pour avoir
        # 1 pouce = 100 pixels dans l'aperçu)
        self.figure = Figure(
            figsize=(self.fig_width_var.get(), self.fig_height_var.get()),
            dpi=100)
        self.ax = self.figure.add_subplot(111)
        self.ax.text(0.5, 0.5, t('plot.select_hint'),
                     ha='center', va='center', transform=self.ax.transAxes,
                     fontsize=14, color='gray')
        self.ax.axis('off')

        self.canvas = FigureCanvasTkAgg(self.figure, master=self.plot_scroll_canvas)
        self.mpl_widget = self.canvas.get_tk_widget()

        # On place le widget matplotlib dans le Tk canvas via create_window.
        # Ainsi, la taille du widget est RESPECTÉE (pas écrasée par fill/expand).
        self._plot_window_id = self.plot_scroll_canvas.create_window(
            0, 0, anchor='nw', window=self.mpl_widget)

        # Taille initiale
        self._update_plot_canvas_size()

        # Recentrer la figure quand la fenêtre change de taille
        self.plot_scroll_canvas.bind('<Configure>', self._center_plot_in_canvas)

        toolbar_frame = ttk.Frame(parent)
        toolbar_frame.pack(fill=tk.X)
        self.toolbar = NavigationToolbar2Tk(self.canvas, toolbar_frame)
        self.toolbar.update()

        # Clic droit sur le plot : menu contextuel (ajouter pic, éditer pic proche)
        # + support du drag d'annotations libres
        self.canvas.mpl_connect('button_press_event', self._on_plot_click)
        self.canvas.mpl_connect('motion_notify_event', self._on_plot_motion)
        self.canvas.mpl_connect('button_release_event', self._on_plot_release)

    def _update_plot_canvas_size(self):
        """Met la taille du widget matplotlib.
        Si fit_width_var activé : largeur = largeur du panneau droit.
        Sinon : largeur = fig_width_var * 100 px."""
        if not hasattr(self, 'mpl_widget'):
            return
        # Déterminer la largeur effective
        if self.fit_width_var.get() and hasattr(self, 'plot_scroll_canvas'):
            canvas_w = self.plot_scroll_canvas.winfo_width()
            if canvas_w > 20:  # widget déjà affiché
                # Mettre à jour fig_width_var pour refléter la taille réelle
                # (utile pour la sauvegarde et l'export)
                new_w_inch = canvas_w / 100.0
                try:
                    self.fig_width_var.set(round(new_w_inch, 1))
                except Exception:
                    pass
                w_px = canvas_w
            else:
                w_px = max(100, int(self.fig_width_var.get() * 100))
        else:
            w_px = max(100, int(self.fig_width_var.get() * 100))
        h_px = max(100, int(self.fig_height_var.get() * 100))
        self.mpl_widget.config(width=w_px, height=h_px)
        # Ajuster aussi la figure matplotlib (en pouces)
        try:
            self.figure.set_size_inches(w_px / 100.0, h_px / 100.0, forward=False)
        except Exception:
            pass
        self._center_plot_in_canvas()

    def _center_plot_in_canvas(self, event=None):
        """Point d'entrée du binding <Configure> — débouncé pour fluidité.
        Pendant un drag actif, on retarde le redimensionnement matplotlib."""
        if not hasattr(self, 'plot_scroll_canvas') or not hasattr(self, 'mpl_widget'):
            return
        # Annule tout redimensionnement planifié
        if getattr(self, '_resize_job', None):
            try:
                self.after_cancel(self._resize_job)
            except Exception:
                pass
        # Repositionnement LÉGER immédiat (scroll / coords, pas de redraw mpl)
        self._quick_reposition()
        # Redessin mpl lourd différé (200 ms)
        self._resize_job = self.after(200, self._do_center_plot)

    def _quick_reposition(self):
        """Repositionne uniquement le widget dans son canvas (opération légère,
        sans toucher à la figure matplotlib)."""
        if not hasattr(self, 'plot_scroll_canvas') or not hasattr(self, 'mpl_widget'):
            return
        try:
            canvas_w = self.plot_scroll_canvas.winfo_width()
            canvas_h = self.plot_scroll_canvas.winfo_height()
            # Taille actuelle du widget (on ne la change PAS ici)
            w_px = self.mpl_widget.winfo_reqwidth()
            h_px = self.mpl_widget.winfo_reqheight()
            # Centrer
            x = max(0, (canvas_w - w_px) // 2)
            y = max(0, (canvas_h - h_px) // 2)
            self.plot_scroll_canvas.coords(self._plot_window_id, x, y)
            sr_w = max(w_px, canvas_w)
            sr_h = max(h_px, canvas_h)
            self.plot_scroll_canvas.configure(scrollregion=(0, 0, sr_w, sr_h))
        except Exception:
            pass

    def _do_center_plot(self):
        """Redimensionne réellement la figure matplotlib (coûteux) — exécuté
        après debounce de 200 ms pour laisser l'utilisateur finir son drag."""
        self._resize_job = None
        if not hasattr(self, 'plot_scroll_canvas') or not hasattr(self, 'mpl_widget'):
            return
        canvas_w = self.plot_scroll_canvas.winfo_width()
        canvas_h = self.plot_scroll_canvas.winfo_height()

        # Flag de protection contre les full redraws pendant le resize complet
        self._resizing = True
        try:
            # Mode fit : on redimensionne le widget à la largeur du canvas
            if self.fit_width_var.get() and canvas_w > 20:
                new_w_inch = canvas_w / 100.0
                current_w = self.fig_width_var.get()
                # Seuil large (0.3 pouce = 30 px) pour éviter les micro-ajustements
                need_update = abs(current_w - round(new_w_inch, 1)) > 0.3
                if need_update:
                    try:
                        self.fig_width_var.set(round(new_w_inch, 1))
                    except Exception:
                        pass
                    # Appliquer à matplotlib
                    try:
                        self.mpl_widget.config(width=canvas_w)
                        self.figure.set_size_inches(new_w_inch, self.fig_height_var.get(),
                                                     forward=False)
                        self.canvas.draw_idle()
                    except Exception:
                        pass
                w_px = canvas_w
            else:
                w_px = max(100, int(self.fig_width_var.get() * 100))

            h_px = max(100, int(self.fig_height_var.get() * 100))

            # Position finale + scrollregion
            x = max(0, (canvas_w - w_px) // 2)
            y = max(0, (canvas_h - h_px) // 2)
            self.plot_scroll_canvas.coords(self._plot_window_id, x, y)
            sr_w = max(w_px, canvas_w)
            sr_h = max(h_px, canvas_h)
            self.plot_scroll_canvas.configure(scrollregion=(0, 0, sr_w, sr_h))
        finally:
            self._resizing = False

