    def _refresh_sample_folders(self):
        """Rafraîchit uniquement la liste des SOUS-DOSSIERS samples disponibles
        dans le combobox. Ne touche PAS à la liste de spectres : celle-ci se
        remplit uniquement via le bouton ➕ (dialog de sélection) ou via le
        chargement d'un projet sauvegardé."""
        base = self.base_folder_var.get()
        if not os.path.isdir(base):
            _set_combo_values(self.sample_combo, [])
            return
        subs = sorted(d for d in os.listdir(base) if os.path.isdir(os.path.join(base, d)))
        _set_combo_values(self.sample_combo, subs)
        # Préselectionner le premier sous-dossier si rien n'est encore choisi,
        # mais SANS remplir la liste de spectres (l'utilisateur doit cliquer ➕).
        if subs and not self.sample_folder_var.get():
            self.sample_folder_var.set(subs[0])

    def _add_current_sample_folder(self):
        """Ouvre un dialog pour sélectionner les spectres à AJOUTER (cumuler) à
        la liste depuis un autre sample folder. Permet à l'utilisateur de choisir
        explicitement quels .txt importer plutôt que de tout ajouter en bloc.

        Workflow : choisir d'abord le sample dans le combobox principal, puis
        cliquer ➕ → ce dialog liste les .txt du dossier avec cases à cocher.
        Les fichiers déjà présents dans la liste sont marqués (déjà ajoutés).

        Mode automatique :
          - Si le sample contient UNIQUEMENT des .txt à plat (cas habituel) :
            liste plate avec cases à cocher (comportement classique).
          - Si le sample contient des SOUS-DOSSIERS avec des .txt
            (cas MatchSearch_Cleaned/CR-G3-05/22042026/) :
            arborescence avec cases à cocher hiérarchiques.
        """
        folder = self._current_sample_path()
        if not folder or not os.path.isdir(folder):
            messagebox.showinfo(t('msg.info_title'), t('msg.no_sample_folder'))
            return

        # Détecter la présence de sous-dossiers contenant des .txt
        # On scanne récursivement pour repérer la structure
        files_flat = []   # .txt à la racine
        nested_files = []  # liste de (chemin_relatif, nom_fichier) pour sous-dossiers
        try:
            for root, dirs, fs in os.walk(folder):
                dirs[:] = [d for d in dirs if not d.startswith('.')]
                for f in sorted(fs):
                    if not f.lower().endswith('.txt'):
                        continue
                    if os.path.normpath(root) == os.path.normpath(folder):
                        files_flat.append(f)
                    else:
                        rel_dir = os.path.relpath(root, folder).replace('\\', '/')
                        nested_files.append((rel_dir, f))
        except (PermissionError, OSError) as e:
            messagebox.showerror(t('msg.error_title'),
                                  f"Impossible de lire le dossier :\n{e}")
            return

        if not files_flat and not nested_files:
            messagebox.showinfo(t('msg.info_title'),
                                 t('msg.no_txt_in_folder', folder=os.path.basename(folder)))
            return

        # Choix du mode : arborescent si des sous-dossiers ont des .txt
        is_tree_mode = bool(nested_files)

        if is_tree_mode:
            self._add_dialog_tree_mode(folder, files_flat, nested_files)
        else:
            self._add_dialog_flat_mode(folder, files_flat)

    def _add_dialog_flat_mode(self, folder, files):
        """Dialog d'ajout classique (liste plate). Comportement historique
        pour les samples sans sous-dossiers."""
        # Fichiers déjà dans spectra_meta pour ce dossier
        already = {s['filename'] for s in self.spectra_meta
                   if s.get('sample_folder') and
                      os.path.normpath(s['sample_folder']) == os.path.normpath(folder)}

        # === Dialog ===
        win = _Toplevel(self)
        win.title(t('add_folder.dialog_title'))
        win.geometry("560x500")
        win.transient(self)
        win.grab_set()
        try:
            win.lift(); win.focus_force()
        except Exception:
            pass

        frm = _Frame(win)
        frm.pack(fill=tk.BOTH, expand=True, padx=14, pady=12)

        sample_name = os.path.basename(folder)
        _Label(frm, text=t('add_folder.intro', sample=sample_name),
               font=('TkDefaultFont', 10, 'bold')).pack(anchor='w')
        _Label(frm, text=t('add_folder.hint'),
               font=('TkDefaultFont', 9), foreground='gray',
               wraplength=520, justify='left').pack(anchor='w', pady=(2, 8))

        # Treeview avec une colonne ✓ et une colonne fichier
        tree_frame = _Frame(frm)
        tree_frame.pack(fill=tk.BOTH, expand=True, pady=4)
        tree = ttk.Treeview(tree_frame, columns=('check', 'file', 'status'),
                             show='headings', selectmode='extended', height=14)
        tree.heading('check', text='✓')
        tree.heading('file', text=t('add_folder.col_file'))
        tree.heading('status', text=t('add_folder.col_status'))
        tree.column('check', width=40, anchor='center', stretch=False)
        tree.column('file', width=320, anchor='w')
        tree.column('status', width=140, anchor='w')
        tree.pack(side=tk.LEFT, fill=tk.BOTH, expand=True)
        sb = ttk.Scrollbar(tree_frame, orient='vertical', command=tree.yview)
        tree.configure(yscrollcommand=sb.set)
        sb.pack(side=tk.RIGHT, fill=tk.Y)

        # État coché par fichier (par défaut : non coché, sauf si déjà ajouté → grisé)
        check_state = {}  # iid → bool
        for i, f in enumerate(files):
            iid = str(i)
            is_already = f in already
            check_state[iid] = False
            mark = '☐' if not is_already else '─'
            status = '' if not is_already else t('add_folder.already_in_list')
            tree.insert('', 'end', iid=iid, values=(mark, f, status),
                         tags=('disabled',) if is_already else ())
        tree.tag_configure('disabled', foreground='gray')

        already_iid_set = {str(i) for i, f in enumerate(files) if f in already}

        def _on_click(event):
            region = tree.identify('region', event.x, event.y)
            if region != 'cell':
                return
            iid = tree.identify_row(event.y)
            if not iid:
                return
            if iid in already_iid_set:
                return
            check_state[iid] = not check_state[iid]
            mark = '☑' if check_state[iid] else '☐'
            current = list(tree.item(iid, 'values'))
            current[0] = mark
            tree.item(iid, values=current)

        tree.bind('<Button-1>', _on_click)

        # Boutons select all / deselect all
        sel_btns = _Frame(frm)
        sel_btns.pack(fill=tk.X, pady=(6, 0))

        def _select_all():
            for iid in tree.get_children():
                if iid in already_iid_set:
                    continue
                check_state[iid] = True
                cur = list(tree.item(iid, 'values'))
                cur[0] = '☑'
                tree.item(iid, values=cur)

        def _deselect_all():
            for iid in tree.get_children():
                if iid in already_iid_set:
                    continue
                check_state[iid] = False
                cur = list(tree.item(iid, 'values'))
                cur[0] = '☐'
                tree.item(iid, values=cur)

        _Button(sel_btns, text=t('panel.btn_select_all'),
                command=_select_all).pack(side=tk.LEFT, padx=2)
        _Button(sel_btns, text=t('panel.btn_deselect'),
                command=_deselect_all).pack(side=tk.LEFT, padx=2)

        # Boutons OK/Cancel
        btn_frm = _Frame(win)
        btn_frm.pack(fill=tk.X, padx=14, pady=(0, 12))

        result = {'selected_files': []}

        def _ok():
            selected = [files[int(iid)] for iid, checked in check_state.items()
                        if checked and iid not in already_iid_set]
            if not selected:
                messagebox.showinfo(t('msg.info_title'),
                                     t('add_folder.none_selected'), parent=win)
                return
            result['selected_files'] = selected
            win.destroy()

        _AccentButton(btn_frm, text=f"{ICONS['add']} {t('add_folder.add_selected')}",
                       accent='primary', command=_ok, width=15).pack(side=tk.RIGHT, padx=4)
        _Button(btn_frm, text=t('common.cancel'),
                command=win.destroy, width=9).pack(side=tk.RIGHT, padx=4)

        win.bind('<Escape>', lambda e: win.destroy())

        self.wait_window(win)

        if not result['selected_files']:
            return
        self._push_undo(t('action.add_folder'))
        for f in result['selected_files']:
            self.spectra_meta.append({
                'sample_folder': folder,
                'filename': f,
                'display_name': clean_label(f),
                'visible': True,
                'color': None,
                'linestyle': None,
                'laser': self.sample_laser_var.get(),
            })
        self._refresh_spectra_tree()
        self._schedule_update()

    def _add_dialog_tree_mode(self, folder, files_flat, nested_files):
        """Dialog d'ajout en mode ARBORESCENT (sample avec sous-dossiers).
        Affiche un Treeview hiérarchique permettant de naviguer dans les
        sous-dossiers. Cocher un dossier coche tous ses .txt enfants.

        nested_files : liste de tuples (rel_dir, filename)
        files_flat   : liste de filenames à la racine du sample
        """
        # Index des fichiers déjà chargés (par chemin absolu pour éviter
        # ambiguïté entre sous-dossiers de même nom)
        already_paths = {os.path.normpath(os.path.join(s['sample_folder'], s['filename']))
                         for s in self.spectra_meta if s.get('sample_folder')}

        win = _Toplevel(self)
        win.title(t('add_folder.dialog_title'))
        win.geometry("700x600")
        win.transient(self)
        win.grab_set()
        try:
            win.lift(); win.focus_force()
        except Exception:
            pass

        frm = _Frame(win)
        frm.pack(fill=tk.BOTH, expand=True, padx=14, pady=12)

        sample_name = os.path.basename(folder)
        _Label(frm, text=f"Ajouter des spectres depuis : {sample_name} (mode arborescent)",
               font=('TkDefaultFont', 10, 'bold')).pack(anchor='w')
        _Label(frm, text="Le sample contient des sous-dossiers. "
                          "Coche chaque .txt à ajouter, ou clique sur un dossier "
                          "pour cocher/décocher toute son arborescence.",
               font=('TkDefaultFont', 9), foreground='gray',
               wraplength=660, justify='left').pack(anchor='w', pady=(2, 8))

        # Treeview hiérarchique
        tree_frame = _Frame(frm)
        tree_frame.pack(fill=tk.BOTH, expand=True, pady=4)
        tree = ttk.Treeview(tree_frame, columns=('check', 'status'),
                             show='tree headings', selectmode='browse', height=18)
        tree.heading('#0', text='Fichier / Dossier')
        tree.heading('check', text='✓')
        tree.heading('status', text='Statut')
        tree.column('#0', width=380, anchor='w')
        tree.column('check', width=50, anchor='center', stretch=False)
        tree.column('status', width=180, anchor='w')
        tree.pack(side=tk.LEFT, fill=tk.BOTH, expand=True)
        sb = ttk.Scrollbar(tree_frame, orient='vertical', command=tree.yview)
        tree.configure(yscrollcommand=sb.set)
        sb.pack(side=tk.RIGHT, fill=tk.Y)

        # État : iid → {'kind': 'file'|'dir', 'path': abs_path, 'rel_dir': str,
        #               'filename': str, 'checked': bool, 'already': bool}
        item_state = {}

        def _make_iid():
            return f"item_{len(item_state) + 1}"

        # Construire la hiérarchie : map rel_dir → list of files
        from collections import defaultdict
        dir_files = defaultdict(list)
        for rd, fn in nested_files:
            dir_files[rd].append(fn)
        # Aussi inclure files_flat à la racine
        for fn in files_flat:
            dir_files[''].append(fn)

        # Construire récursivement en commençant par la racine
        # On a besoin de connaître tous les sous-dossiers, ordonnés
        all_dirs = sorted(dir_files.keys())  # '' en tête

        def _insert_dir(parent_iid, rel_dir):
            """Insère un nœud dossier et tous ses .txt + sous-dossiers."""
            if rel_dir:
                dir_iid = _make_iid()
                dir_name = rel_dir.rstrip('/').split('/')[-1]
                tree.insert(parent_iid, 'end', iid=dir_iid, text=f"📁 {dir_name}",
                             values=('☐', ''), open=True)
                item_state[dir_iid] = {
                    'kind': 'dir', 'rel_dir': rel_dir, 'checked': False,
                }
            else:
                dir_iid = ''  # racine virtuelle

            # Insérer les fichiers de ce dossier
            for fn in dir_files.get(rel_dir, []):
                fn_iid = _make_iid()
                abs_path = os.path.join(folder, rel_dir, fn) if rel_dir else os.path.join(folder, fn)
                is_already = os.path.normpath(abs_path) in already_paths
                mark = '─' if is_already else '☐'
                status = t('add_folder.already_in_list') if is_already else ''
                tags = ('disabled',) if is_already else ()
                tree.insert(dir_iid, 'end', iid=fn_iid, text=f"📄 {fn}",
                             values=(mark, status), tags=tags)
                item_state[fn_iid] = {
                    'kind': 'file', 'rel_dir': rel_dir, 'filename': fn,
                    'abs_path': abs_path, 'checked': False, 'already': is_already,
                }

        # On insère d'abord les fichiers à la racine (rel_dir='')
        # Puis on construit récursivement les sous-arbres pour chaque sous-dir
        # Pour gérer les niveaux multiples (ex: CR-G3-05/22042026/), on doit
        # construire la hiérarchie correctement.
        # Approche simple : on collecte tous les rel_dir uniques, on les trie,
        # et on les insère dans l'ordre — chaque dossier est inséré sous son
        # parent immédiat.
        dir_iid_map = {'': ''}  # rel_dir → iid (racine = '')

        # 1) Fichiers à la racine
        for fn in dir_files.get('', []):
            fn_iid = _make_iid()
            abs_path = os.path.join(folder, fn)
            is_already = os.path.normpath(abs_path) in already_paths
            mark = '─' if is_already else '☐'
            status = t('add_folder.already_in_list') if is_already else ''
            tags = ('disabled',) if is_already else ()
            tree.insert('', 'end', iid=fn_iid, text=f"📄 {fn}",
                         values=(mark, status), tags=tags)
            item_state[fn_iid] = {
                'kind': 'file', 'rel_dir': '', 'filename': fn,
                'abs_path': abs_path, 'checked': False, 'already': is_already,
            }

        # 2) Tous les sous-dossiers, triés pour insérer parents avant enfants
        sub_dirs = sorted(d for d in dir_files.keys() if d)
        for rd in sub_dirs:
            # Trouver le parent
            parts = rd.split('/')
            if len(parts) == 1:
                parent_iid = ''
            else:
                parent_rd = '/'.join(parts[:-1])
                parent_iid = dir_iid_map.get(parent_rd, '')

            dir_iid = _make_iid()
            dir_name = parts[-1]
            tree.insert(parent_iid, 'end', iid=dir_iid, text=f"📁 {dir_name}",
                         values=('☐', ''), open=True)
            item_state[dir_iid] = {
                'kind': 'dir', 'rel_dir': rd, 'checked': False,
            }
            dir_iid_map[rd] = dir_iid

            # Insérer les fichiers de ce dossier
            for fn in dir_files.get(rd, []):
                fn_iid = _make_iid()
                abs_path = os.path.join(folder, rd, fn)
                is_already = os.path.normpath(abs_path) in already_paths
                mark = '─' if is_already else '☐'
                status = t('add_folder.already_in_list') if is_already else ''
                tags = ('disabled',) if is_already else ()
                tree.insert(dir_iid, 'end', iid=fn_iid, text=f"📄 {fn}",
                             values=(mark, status), tags=tags)
                item_state[fn_iid] = {
                    'kind': 'file', 'rel_dir': rd, 'filename': fn,
                    'abs_path': abs_path, 'checked': False, 'already': is_already,
                }

        tree.tag_configure('disabled', foreground='gray')

        def _set_checked(iid, value):
            """Coche/décoche un item et propage aux enfants si dossier.
            Ignore les fichiers déjà ajoutés (grisés)."""
            state = item_state.get(iid)
            if not state:
                return
            if state['kind'] == 'file':
                if state['already']:
                    return
                state['checked'] = value
                cur = list(tree.item(iid, 'values'))
                cur[0] = '☑' if value else '☐'
                tree.item(iid, values=cur)
            else:
                # Dossier : propager aux enfants
                state['checked'] = value
                cur = list(tree.item(iid, 'values'))
                cur[0] = '☑' if value else '☐'
                tree.item(iid, values=cur)
                for child in tree.get_children(iid):
                    _set_checked(child, value)

        def _on_click(event):
            region = tree.identify('region', event.x, event.y)
            if region not in ('cell', 'tree'):
                return
            iid = tree.identify_row(event.y)
            if not iid:
                return
            state = item_state.get(iid)
            if not state:
                return
            new_val = not state['checked']
            _set_checked(iid, new_val)

        tree.bind('<Button-1>', _on_click)

        # Boutons select all / deselect all
        sel_btns = _Frame(frm)
        sel_btns.pack(fill=tk.X, pady=(6, 0))

        def _select_all():
            for iid in tree.get_children():
                _set_checked(iid, True)

        def _deselect_all():
            for iid in tree.get_children():
                _set_checked(iid, False)

        _Button(sel_btns, text=t('panel.btn_select_all'),
                command=_select_all).pack(side=tk.LEFT, padx=2)
        _Button(sel_btns, text=t('panel.btn_deselect'),
                command=_deselect_all).pack(side=tk.LEFT, padx=2)

        # Boutons OK/Cancel
        btn_frm = _Frame(win)
        btn_frm.pack(fill=tk.X, padx=14, pady=(0, 12))

        result = {'selected': []}

        def _ok():
            sel = []
            for iid, state in item_state.items():
                if state['kind'] == 'file' and state['checked'] and not state['already']:
                    sel.append((state['rel_dir'], state['filename'], state['abs_path']))
            if not sel:
                messagebox.showinfo(t('msg.info_title'),
                                     t('add_folder.none_selected'), parent=win)
                return
            result['selected'] = sel
            win.destroy()

        _AccentButton(btn_frm, text=f"{ICONS['add']} {t('add_folder.add_selected')}",
                       accent='primary', command=_ok, width=15).pack(side=tk.RIGHT, padx=4)
        _Button(btn_frm, text=t('common.cancel'),
                command=win.destroy, width=9).pack(side=tk.RIGHT, padx=4)

        win.bind('<Escape>', lambda e: win.destroy())

        self.wait_window(win)

        if not result['selected']:
            return
        self._push_undo(t('action.add_folder'))
        for rel_dir, filename, abs_path in result['selected']:
            # sample_folder = dossier qui contient effectivement le .txt
            sf = os.path.dirname(abs_path)
            # display_name = chemin relatif (sans .txt) pour que l'utilisateur
            # distingue les spectres venant de sous-dossiers différents
            if rel_dir:
                rel_full = f"{rel_dir}/{os.path.splitext(filename)[0]}"
            else:
                rel_full = clean_label(filename)
            self.spectra_meta.append({
                'sample_folder': sf,
                'filename': filename,
                'display_name': rel_full,
                'visible': True,
                'color': None,
                'linestyle': None,
                'laser': self.sample_laser_var.get(),
            })
        self._refresh_spectra_tree()
        self._schedule_update()
        n = len(result['selected'])
        self.status_var.set(f"➕ {n} spectre(s) ajouté(s) à la liste")

    def _refresh_spectra_list(self, append_mode=False):
        """Scan le sample folder courant et remplit self.spectra_meta.

        Args:
            append_mode : si True, ajoute les nouveaux fichiers à la liste existante
                          au lieu de tout remplacer. Utilisé par le bouton
                          "Ajouter ce dossier" pour cumuler plusieurs dossiers.
        """
        folder = self._current_sample_path()
        if not folder or not os.path.isdir(folder):
            if not append_mode:
                # Si on est en mode normal, vider
                for item in self.spectra_tree.get_children():
                    self.spectra_tree.delete(item)
                self.spectrum_files = []
                self.spectra_meta = []
            self._schedule_update()
            return
        files = sorted(f for f in os.listdir(folder) if f.lower().endswith('.txt'))

        if append_mode:
            # Mode cumul : on garde les spectres existants et on ajoute les nouveaux
            # qui ne sont pas déjà présents (même folder + même filename)
            existing_keys = {(s.get('sample_folder'), s['filename'])
                             for s in self.spectra_meta}
            for f in files:
                key = (folder, f)
                if key not in existing_keys:
                    self.spectra_meta.append({
                        'sample_folder': folder,
                        'filename': f,
                        'display_name': clean_label(f),
                        'visible': False,
                        'color': None,
                        'linestyle': None,
                        'laser': self.sample_laser_var.get(),
                    })
        else:
            # Mode "remplacer le dossier courant" :
            # - On garde les spectres venant d'AUTRES dossiers (multi-dossiers cumulé)
            # - On vide les anciens spectres du dossier courant pour les recharger
            # - Si un spectre du dossier était coché, on conserve son état (visible,
            #   color, etc.) en l'indexant par filename.
            # Sauvegarde de l'état des spectres déjà présents pour ce dossier
            existing_in_folder = {
                s['filename']: s for s in self.spectra_meta
                if s.get('sample_folder') and
                   os.path.normpath(s['sample_folder']) == os.path.normpath(folder)
            }
            # Garde les spectres des autres dossiers
            self.spectra_meta = [
                s for s in self.spectra_meta
                if not s.get('sample_folder') or
                   os.path.normpath(s['sample_folder']) != os.path.normpath(folder)
            ]
            # Re-scan disque pour ce dossier, en réutilisant l'état précédent si possible
            for f in files:
                if f in existing_in_folder:
                    # Reprendre l'état (visibilité, couleurs) du spectre existant
                    self.spectra_meta.append(existing_in_folder[f])
                else:
                    self.spectra_meta.append({
                        'sample_folder': folder,
                        'filename': f,
                        'display_name': clean_label(f),
                        'visible': False,
                        'color': None,
                        'linestyle': None,
                        'laser': self.sample_laser_var.get(),
                    })
        self._refresh_spectra_tree()
        self._schedule_update()

    def _linestyle_glyph(self, ls_key):
        """Retourne un petit pictogramme texte pour représenter un linestyle."""
        glyphs = {
            'solid':      '───',
            'dashed':     '╌╌╌',
            'dotted':     '···',
            'dashdot':    '─·─',
            'longdash':   '━━',
            'densedot':   '····',
            'dashdotdot': '─··',
        }
        return glyphs.get(ls_key, '───')

    def _refresh_spectra_tree(self):
        """Reconstruit le Treeview des spectres depuis spectra_meta.
        Préfixe le nom de fichier par [dossier] quand le spectre vient
        d'un dossier différent du sample courant (multi-dossiers).
        Pour les sous-dossiers profonds (mode arborescent), affiche le
        chemin relatif complet, ex. [CR-G3-05/22042026]."""
        for item in self.spectra_tree.get_children():
            self.spectra_tree.delete(item)
        # Dossier sample courant pour comparaison
        current_folder = self._current_sample_path()
        for i, s in enumerate(self.spectra_meta):
            check = '☑' if s['visible'] else '☐'
            color_cell = '●' if s.get('color') else '○'
            ls_key = s.get('linestyle') or self.sample_linestyle_var.get()
            ls_cell = self._linestyle_glyph(ls_key)
            tag = f'color_spec_{i}'
            # Préfixer le nom de fichier par [chemin/relatif] si le spectre vient
            # d'un autre dossier que le sample actif. On utilise le chemin
            # RELATIF complet depuis le sample courant pour montrer toute la
            # hiérarchie (ex. CR-G3-05/22042026 plutôt que juste 22042026).
            file_label = s['filename']
            spec_folder = s.get('sample_folder')
            if spec_folder and current_folder and \
               os.path.normpath(spec_folder) != os.path.normpath(current_folder):
                try:
                    rel = os.path.relpath(spec_folder, current_folder).replace('\\', '/')
                    # Si rel commence par '..' (spec_folder hors du sample courant)
                    # on retombe sur juste le basename pour rester lisible
                    if rel.startswith('..'):
                        rel = os.path.basename(os.path.normpath(spec_folder))
                except ValueError:
                    rel = os.path.basename(os.path.normpath(spec_folder))
                file_label = f"[{rel}] {s['filename']}"
            laser_cell = s.get('laser', self.sample_laser_var.get())
            self.spectra_tree.insert('', 'end', iid=str(i), values=(
                check, color_cell, ls_cell, file_label, s['display_name'], laser_cell),
                tags=(tag,))
            if s.get('color'):
                self.spectra_tree.tag_configure(tag, foreground=s['color'])
            else:
                self.spectra_tree.tag_configure(tag, foreground='gray')
        self.spectrum_files = [s['filename'] for s in self.spectra_meta if s['visible']]

    def _current_sample_path(self):
        base = self.base_folder_var.get()
        sub  = self.sample_folder_var.get()
        if base and sub:
            return os.path.join(base, sub)
        return ''

    def _current_lib_path(self):
        """Retourne le dossier RRUFF effectif (avec sous-dossier database si défini)."""
        lib = self.lib_folder_var.get()
        sub = self.database_folder_var.get()
        if lib and sub:
            candidate = os.path.join(lib, sub)
            if os.path.isdir(candidate):
                return candidate
        return lib

    def _refresh_database_folders(self):
        """Liste les sous-dossiers de DATABASE_RRUFF et peuple le combobox."""
        lib = self.lib_folder_var.get()
        if not os.path.isdir(lib) or not hasattr(self, 'database_combo'):
            return
        subs = sorted(d for d in os.listdir(lib)
                      if os.path.isdir(os.path.join(lib, d)))
        # "(racine)" = scanner directement lib_folder sans sous-dossier
        values = [t('match.lbl.db_root')] + subs
        _set_combo_values(self.database_combo, values)
        # Si rien n'est défini et qu'on a des sous-dossiers, ne rien forcer
        # (laisser l'utilisateur choisir explicitement)
        current = self.database_folder_var.get()
        if current and current not in subs:
            # Valeur précédente invalide → remettre racine
            self.database_folder_var.set('')

    # ============================================================
    # CALLBACKS — Spectres
    # ============================================================
    def _on_spectrum_click(self, event):
        """Clic : ✓ = visibilité, 🎨 = couleur, ╌ = linestyle, laser = menu."""
        region = self.spectra_tree.identify('region', event.x, event.y)
        if region != 'cell':
            return
        col = self.spectra_tree.identify_column(event.x)
        iid = self.spectra_tree.identify_row(event.y)
        if not iid:
            return
        idx = int(iid)
        if col == '#1':      # ✓ visibilité
            self._push_undo(t('action.toggle_visibility'))
            self.spectra_meta[idx]['visible'] = not self.spectra_meta[idx]['visible']
            self._refresh_spectra_tree()
            self._schedule_update()
        elif col == '#2':    # 🎨 couleur
            self._pick_spectrum_color(idx)
        elif col == '#3':    # ╌ linestyle
            self._pick_spectrum_linestyle(idx)
        # Note : la colonne 'laser' n'a plus d'action au clic — le laser
        # se modifie via le bouton "Modifier" de la Section 2 qui ouvre un
        # dialog avec alias + laser.

    def _pick_spectrum_laser(self, idx):
        """Menu déroulant pour choisir le laser d'un spectre individuel.
        Permet d'avoir des lasers différents par spectre dans un même projet
        (utile pour les analyses multi-laser ou multi-instruments)."""
        if not (0 <= idx < len(self.spectra_meta)):
            return
        menu = tk.Menu(self, tearoff=0)
        current = self.spectra_meta[idx].get('laser', '')
        # Lasers disponibles : ceux du combobox global
        available = ['532 nm', '633 nm', '785 nm', '830 nm', '1064 nm']
        # Ajoute le laser custom du spectre s'il n'est pas dans la liste standard
        if current and current not in available:
            available.insert(0, current)
        for laser in available:
            prefix = '  ● ' if laser == current else '      '
            menu.add_command(label=f"{prefix}{laser}",
                             command=lambda lz=laser: self._set_spectrum_laser(idx, lz))
        menu.add_separator()
        menu.add_command(label="✏ " + t('action.custom_laser'),
                         command=lambda: self._set_custom_laser(idx))
        x, y = self.winfo_pointerxy()
        try:
            menu.tk_popup(x, y)
        finally:
            menu.grab_release()

    def _set_spectrum_laser(self, idx, laser):
        """Modifie le laser d'un spectre + push undo + redraw."""
        if not (0 <= idx < len(self.spectra_meta)):
            return
        if self.spectra_meta[idx].get('laser') == laser:
            return
        self._push_undo(t('action.change_laser'))
        self.spectra_meta[idx]['laser'] = laser
        self._refresh_spectra_tree()
        self._schedule_update()

    def _set_custom_laser(self, idx):
        """Demande un laser custom via simpledialog."""
        from tkinter import simpledialog
        if not (0 <= idx < len(self.spectra_meta)):
            return
        current = self.spectra_meta[idx].get('laser', '')
        new = simpledialog.askstring(
            t('action.custom_laser'),
            t('msg.enter_custom_laser'),
            initialvalue=current, parent=self)
        if new and new.strip():
            self._set_spectrum_laser(idx, new.strip())

    def _pick_spectrum_linestyle(self, idx):
        """Menu déroulant pour choisir le linestyle d'un spectre."""
        menu = tk.Menu(self, tearoff=0)
        current = self.spectra_meta[idx].get('linestyle')
        menu.add_command(label=f"(Défaut global : {self.sample_linestyle_var.get()})",
                         command=lambda: self._set_spectrum_linestyle(idx, None))
        menu.add_separator()
        for key, label, _ in LINESTYLES:
            prefix = '  ● ' if key == current else '      '
            menu.add_command(label=f"{prefix}{label}",
                             command=lambda k=key: self._set_spectrum_linestyle(idx, k))
        x, y = self.winfo_pointerxy()
        try:
            menu.tk_popup(x, y)
        finally:
            menu.grab_release()

    def _set_spectrum_linestyle(self, idx, ls_key):
        self.spectra_meta[idx]['linestyle'] = ls_key
        self._refresh_spectra_tree()
        self._schedule_update()

    def _pick_spectrum_color(self, idx):
        """Ouvre un color picker pour le spectre à l'index donné."""
        from tkinter import colorchooser
        current = self.spectra_meta[idx].get('color') or '#1f77b4'
        result = colorchooser.askcolor(
            color=current,
            title=f"Couleur pour : {self.spectra_meta[idx]['filename']}")
        if result and result[1]:
            self._push_undo(t('action.change_color'))
            self.spectra_meta[idx]['color'] = result[1]
            self._refresh_spectra_tree()
            self._schedule_update()

    def _reset_spectrum_color(self, idx):
        """Remet la couleur en auto (None)."""
        self._push_undo(t('action.change_color'))
        self.spectra_meta[idx]['color'] = None
        self._refresh_spectra_tree()
        self._schedule_update()

    def _on_spectrum_rightclick(self, event):
        """Menu contextuel clic droit sur un spectre."""
        iid = self.spectra_tree.identify_row(event.y)
        if not iid:
            return
        idx = int(iid)
        # Sélectionner la ligne visuellement
        self.spectra_tree.selection_set(iid)

        menu = tk.Menu(self, tearoff=0)
        menu.add_command(label="🎨 Changer couleur…",
                         command=lambda: self._pick_spectrum_color(idx))
        menu.add_command(label="↺ Réinitialiser couleur",
                         command=lambda: self._reset_spectrum_color(idx))
        menu.add_separator()
        menu.add_command(label="╌ Changer style ligne…",
                         command=lambda: self._pick_spectrum_linestyle(idx))
        menu.add_command(label="↺ Réinitialiser style ligne",
                         command=lambda: self._set_spectrum_linestyle(idx, None))
        menu.add_separator()
        menu.add_command(label="✎ Renommer…",
                         command=self._rename_spectrum_dialog)
        menu.add_command(label="👁 Basculer visibilité",
                         command=lambda: self._toggle_single_spectrum_visibility(idx))
        try:
            menu.tk_popup(event.x_root, event.y_root)
        finally:
            menu.grab_release()

    def _toggle_single_spectrum_visibility(self, idx):
        self.spectra_meta[idx]['visible'] = not self.spectra_meta[idx]['visible']
        self._refresh_spectra_tree()
        self._schedule_update()

    def _on_spectrum_dblclick(self, event):
        """Double-clic : renommer l'alias."""
        region = self.spectra_tree.identify('region', event.x, event.y)
        if region == 'cell':
            self._rename_spectrum_dialog()

    def _rename_spectrum_dialog(self):
        """Dialog de modification d'un spectre : alias (display_name) + laser.
        (Anciennement "Rename" — renommé en "Modify" pour refléter qu'on peut
        maintenant modifier plusieurs propriétés à la fois.)"""
        sel = self.spectra_tree.selection()
        if not sel:
            messagebox.showinfo(t('msg.info_title'), t('msg.no_spectrum_selected'))
            return
        idx = int(sel[0])
        s = self.spectra_meta[idx]

        win = _Toplevel(self)
        win.title(t('dlg.modify.title'))
        win.geometry("480x300")
        win.transient(self)
        win.grab_set()
        win.resizable(False, False)
        try:
            win.lift(); win.focus_force()
        except Exception:
            pass

        frm = _Frame(win)
        frm.pack(fill=tk.BOTH, expand=True, padx=18, pady=16)

        _Label(frm, text=t('dlg.rename.file', name=s['filename']),
               font=('TkDefaultFont', 9),
               foreground='gray').pack(anchor='w')

        # === Alias ===
        _Label(frm, text=t('dlg.rename.alias'),
               font=('TkDefaultFont', 10, 'bold')).pack(anchor='w', pady=(12, 2))
        alias_var = tk.StringVar(value=s['display_name'])
        ent = _Entry(frm, textvariable=alias_var)
        ent.pack(fill=tk.X, pady=2, ipady=2)
        try:
            ent.focus_set()
            if HAS_CTK and hasattr(ent, '_entry'):
                ent._entry.select_range(0, tk.END)
            else:
                ent.select_range(0, tk.END)
        except Exception:
            pass

        # === Laser ===
        _Label(frm, text=t('dlg.modify.laser'),
               font=('TkDefaultFont', 10, 'bold')).pack(anchor='w', pady=(12, 2))
        laser_var = tk.StringVar(value=s.get('laser', self.sample_laser_var.get()))
        laser_combo = _Combobox(frm, textvariable=laser_var,
                                 values=('532 nm', '633 nm', '785 nm', '830 nm', '1064 nm'),
                                 state='normal')
        laser_combo.pack(fill=tk.X, pady=2)
        _Label(frm, text=t('dlg.modify.laser_hint'),
               font=('TkDefaultFont', 8), foreground='gray').pack(anchor='w', pady=(2, 0))

        btn_frm = _Frame(win)
        btn_frm.pack(fill=tk.X, padx=18, pady=(0, 14))

        def _ok():
            self._push_undo(t('action.rename_spectrum'))
            new_alias = alias_var.get().strip() or clean_label(s['filename'])
            new_laser = laser_var.get().strip() or self.sample_laser_var.get()
            self.spectra_meta[idx]['display_name'] = new_alias
            self.spectra_meta[idx]['laser'] = new_laser
            self._refresh_spectra_tree()
            self._schedule_update()
            win.destroy()

        def _reset():
            alias_var.set(clean_label(s['filename']))
            laser_var.set(self.sample_laser_var.get())

        _Button(btn_frm, text=f"{ICONS['reset']} {t('common.reset')}",
                command=_reset, width=9).pack(side=tk.LEFT)
        _AccentButton(btn_frm, text=f"{ICONS['check']} {t('common.apply')}",
                       accent='primary', command=_ok, width=11).pack(side=tk.RIGHT, padx=4)
        _Button(btn_frm, text=t('common.cancel'), command=win.destroy,
                width=9).pack(side=tk.RIGHT, padx=4)
        win.bind('<Return>', lambda e: _ok())
        win.bind('<Escape>', lambda e: win.destroy())

    def _select_all_spectra(self):
        self._push_undo(t('action.toggle_visibility'))
        for s in self.spectra_meta:
            s['visible'] = True
        self._refresh_spectra_tree()
        self._schedule_update()

    def _deselect_all_spectra(self):
        self._push_undo(t('action.toggle_visibility'))
        for s in self.spectra_meta:
            s['visible'] = False
        self._refresh_spectra_tree()
        self._schedule_update()

    def _compare_spectra_dialog(self):
        """Dialog de comparaison de 2 spectres avec différence/ratio.
        Support samples + refs de TOUS les dossiers avec preview matplotlib live.
        Les chemins sont résolus au moment de l'ouverture du dialog pour
        permettre de comparer des spectres de samples différents."""
        lib_folder = self._current_lib_path()

        # Construire la liste des éléments disponibles avec chemin ABSOLU :
        # - Tous les samples dans le sample actif (charge aussi les autres dossiers)
        # - Tous les autres dossiers samples du base_folder
        # - Toutes les refs actuelles
        items = []  # liste de tuples (label, full_path)

        # 1) Samples : scan de TOUS les sous-dossiers de base_folder
        base = self.base_folder_var.get()
        if base and os.path.isdir(base):
            for sample_name in sorted(os.listdir(base)):
                sample_path = os.path.join(base, sample_name)
                if not os.path.isdir(sample_path):
                    continue
                try:
                    files = sorted(f for f in os.listdir(sample_path)
                                    if f.lower().endswith('.txt'))
                except (PermissionError, OSError):
                    continue
                for f in files:
                    label = f"Sample: {sample_name} / {clean_label(f)}"
                    full_path = os.path.join(sample_path, f)
                    items.append((label, full_path))

        # 2) Refs : utiliser les refs chargées dans le projet
        for r in self.refs:
            label = f"Ref: {r['mineral']} ({r.get('display_name') or clean_label(r['filename'])})"
            full_path = os.path.join(lib_folder, r['filename'])
            items.append((label, full_path))

        if len(items) < 2:
            messagebox.showinfo(t('msg.info_title'), t('compare.error_select'))
            return

        win = _Toplevel(self)
        win.title(t('compare.title'))
        win.geometry("1100x700")
        win.transient(self)
        win.minsize(900, 550)
        try:
            win.lift(); win.focus_force()
        except Exception:
            pass

        top_frm = _Frame(win)
        top_frm.pack(fill=tk.X, padx=12, pady=(10, 4))
        _Label(top_frm, text=t('compare.hint'),
               font=('TkDefaultFont', 9), foreground='gray').pack(anchor='w')

        sel_frm = _Frame(win)
        sel_frm.pack(fill=tk.X, padx=12, pady=(4, 8))

        # Liste déroulante spectre A
        _Label(sel_frm, text=t('compare.spectrum_a'),
               width=12).grid(row=0, column=0, sticky='w', pady=2)
        labels = [it[0] for it in items]
        var_a = tk.StringVar(value=labels[0])
        cb_a = _Combobox(sel_frm, textvariable=var_a, values=labels,
                          state='readonly', width=55)
        cb_a.grid(row=0, column=1, sticky='ew', padx=6, pady=2)

        # Liste déroulante spectre B
        _Label(sel_frm, text=t('compare.spectrum_b'),
               width=12).grid(row=1, column=0, sticky='w', pady=2)
        var_b = tk.StringVar(value=labels[1] if len(labels) > 1 else labels[0])
        cb_b = _Combobox(sel_frm, textvariable=var_b, values=labels,
                          state='readonly', width=55)
        cb_b.grid(row=1, column=1, sticky='ew', padx=6, pady=2)
        sel_frm.columnconfigure(1, weight=1)

        # Options : mode de calcul + checkbox affichage
        opt_frm = _Frame(win)
        opt_frm.pack(fill=tk.X, padx=12, pady=(0, 8))
        _Label(opt_frm, text=t('compare.diff_mode')).pack(side=tk.LEFT)
        diff_mode_var = tk.StringVar(value='sub')
        if HAS_CTK:
            ctk.CTkRadioButton(opt_frm, text=t('compare.diff_sub'),
                                variable=diff_mode_var, value='sub').pack(side=tk.LEFT, padx=8)
            ctk.CTkRadioButton(opt_frm, text=t('compare.diff_div'),
                                variable=diff_mode_var, value='div').pack(side=tk.LEFT, padx=8)
        else:
            ttk.Radiobutton(opt_frm, text=t('compare.diff_sub'),
                             variable=diff_mode_var, value='sub').pack(side=tk.LEFT, padx=8)
            ttk.Radiobutton(opt_frm, text=t('compare.diff_div'),
                             variable=diff_mode_var, value='div').pack(side=tk.LEFT, padx=8)

        show_orig_var = tk.BooleanVar(value=True)
        show_diff_var = tk.BooleanVar(value=True)
        opt_frm2 = _Frame(win)
        opt_frm2.pack(fill=tk.X, padx=12, pady=(0, 4))
        _Checkbutton(opt_frm2, text=t('compare.show_orig'),
                     variable=show_orig_var).pack(side=tk.LEFT, padx=6)
        _Checkbutton(opt_frm2, text=t('compare.show_diff'),
                     variable=show_diff_var).pack(side=tk.LEFT, padx=6)

        # Zone du graphique
        fig = Figure(figsize=(9, 5), dpi=90)
        canvas = FigureCanvasTkAgg(fig, master=win)
        canvas.get_tk_widget().pack(fill=tk.BOTH, expand=True, padx=12, pady=(4, 4))

        def _load_data(item):
            """Charge x, y depuis un tuple (label, full_path)."""
            label, full_path = item
            return load_spectrum(full_path)

        def _find_item(label_text):
            for it in items:
                if it[0] == label_text:
                    return it
            return None

        def _update_compare():
            item_a = _find_item(var_a.get())
            item_b = _find_item(var_b.get())
            fig.clear()
            if item_a is None or item_b is None:
                ax = fig.add_subplot(111)
                ax.text(0.5, 0.5, t('compare.error_select'),
                        ha='center', va='center', transform=ax.transAxes,
                        fontsize=10, color='black')
                ax.axis('off')
                canvas.draw_idle()
                return
            if item_a == item_b:
                ax = fig.add_subplot(111)
                ax.text(0.5, 0.5, t('compare.error_same'),
                        ha='center', va='center', transform=ax.transAxes,
                        fontsize=10, color='red')
                ax.axis('off')
                canvas.draw_idle()
                return
            try:
                xa, ya = _load_data(item_a)
                xb, yb = _load_data(item_b)
            except Exception as e:
                ax = fig.add_subplot(111)
                ax.text(0.5, 0.5, t('compare.no_data', err=e),
                        ha='center', va='center', transform=ax.transAxes,
                        fontsize=9, color='red')
                ax.axis('off')
                canvas.draw_idle()
                return

            # Résampler B sur la grille de A (plage commune)
            xmin_c = max(xa.min(), xb.min())
            xmax_c = min(xa.max(), xb.max())
            x_common = xa[(xa >= xmin_c) & (xa <= xmax_c)]
            if len(x_common) < 3:
                ax = fig.add_subplot(111)
                ax.text(0.5, 0.5, "Plages spectrales incompatibles",
                        ha='center', va='center', transform=ax.transAxes,
                        fontsize=10, color='red')
                ax.axis('off')
                canvas.draw_idle()
                return
            ya_common = np.interp(x_common, xa, ya)
            yb_common = np.interp(x_common, xb, yb)

            # Normaliser sur 0-1 dans la plage commune
            def _norm(arr):
                lo, hi = arr.min(), arr.max()
                return (arr - lo) / (hi - lo) if hi > lo else arr * 0
            ya_n = _norm(ya_common)
            yb_n = _norm(yb_common)

            # Calculer la différence/ratio
            mode = diff_mode_var.get()
            if mode == 'sub':
                diff = ya_n - yb_n
                diff_label = "A − B"
            else:
                # Éviter division par zéro : clipper b à 1e-3
                safe_b = np.where(np.abs(yb_n) > 1e-3, yb_n, 1e-3)
                diff = ya_n / safe_b
                diff_label = "A / B"

            # Construire le layout selon les options cochées
            show_o = show_orig_var.get()
            show_d = show_diff_var.get()
            if show_o and show_d:
                ax1 = fig.add_subplot(211)
                ax2 = fig.add_subplot(212, sharex=ax1)
                _orig_ax, _diff_ax = ax1, ax2
            elif show_o:
                _orig_ax = fig.add_subplot(111)
                _diff_ax = None
            elif show_d:
                _orig_ax = None
                _diff_ax = fig.add_subplot(111)
            else:
                # Rien à afficher
                ax = fig.add_subplot(111)
                ax.text(0.5, 0.5, "Coche au moins une option d'affichage",
                        ha='center', va='center', transform=ax.transAxes,
                        color='gray', fontsize=10)
                ax.axis('off')
                canvas.draw_idle()
                return

            if _orig_ax is not None:
                # Labels courts et lisibles : on garde juste le nom du fichier
                # (dernière partie après le dernier '/' ou ':')
                def _short_label(full_label):
                    # "Sample: CR-G3-03 / 0001 10042026" → "CR-G3-03 / 0001 10042026"
                    # "Ref: abellaite (Abellaite R250095...)" → "abellaite (Abellaite R250095...)"
                    if ':' in full_label:
                        short = full_label.split(':', 1)[1].strip()
                    else:
                        short = full_label
                    if len(short) > 45:
                        short = short[:42] + '…'
                    return short

                _orig_ax.plot(x_common, ya_n, color='#1976d2', linewidth=1.3,
                              label=f"A: {_short_label(item_a[0])}", zorder=2)
                _orig_ax.plot(x_common, yb_n, color='#d32f2f', linewidth=1.3,
                              linestyle='--',
                              label=f"B: {_short_label(item_b[0])}", zorder=2)
                _orig_ax.set_ylabel(t('match.lbl.normalized_intensity'))
                # Légende avec cadre blanc solide pour être visible en mode sombre
                leg = _orig_ax.legend(loc='upper right', fontsize=9,
                                       frameon=True, framealpha=0.9,
                                       facecolor='white', edgecolor='gray')
                # S'assurer que le texte de la légende est noir (pas inverse thème)
                for text in leg.get_texts():
                    text.set_color('black')
                _orig_ax.grid(alpha=0.3)
                if _diff_ax is None:
                    _orig_ax.set_xlabel(r'Raman shift (cm$^{-1}$)')

            if _diff_ax is not None:
                color_diff = '#2e7d32' if mode == 'sub' else '#6a1b9a'
                _diff_ax.plot(x_common, diff, color=color_diff, linewidth=1.3,
                              label=diff_label, zorder=2)
                if mode == 'sub':
                    _diff_ax.axhline(0, color='gray', linewidth=0.5, alpha=0.6)
                else:
                    _diff_ax.axhline(1, color='gray', linewidth=0.5, alpha=0.6)
                _diff_ax.set_ylabel(diff_label)
                _diff_ax.set_xlabel(r'Raman shift (cm$^{-1}$)')
                leg2 = _diff_ax.legend(loc='upper right', fontsize=9,
                                        frameon=True, framealpha=0.9,
                                        facecolor='white', edgecolor='gray')
                for text in leg2.get_texts():
                    text.set_color('black')
                _diff_ax.grid(alpha=0.3)

            fig.tight_layout()
            canvas.draw_idle()

        # Rafraîchir quand les options changent
        var_a.trace_add('write', lambda *a: _update_compare())
        var_b.trace_add('write', lambda *a: _update_compare())
        diff_mode_var.trace_add('write', lambda *a: _update_compare())
        show_orig_var.trace_add('write', lambda *a: _update_compare())
        show_diff_var.trace_add('write', lambda *a: _update_compare())

        _update_compare()

        # Boutons du bas
        btn_frm = _Frame(win)
        btn_frm.pack(fill=tk.X, padx=12, pady=(4, 12))

        def _export():
            path = filedialog.asksaveasfilename(
                title=t('compare.export'),
                defaultextension=".png",
                filetypes=[("PNG", "*.png"), ("PDF", "*.pdf"), ("SVG", "*.svg")],
                initialdir=self.save_dir_var.get() or os.path.expanduser('~'),
                initialfile="Comparaison_spectres",
                parent=win,
            )
            if not path:
                return
            try:
                fig.savefig(path, dpi=300, bbox_inches='tight')
                messagebox.showinfo(t('msg.save_ok'),
                    f"{os.path.basename(path)}", parent=win)
            except Exception as e:
                messagebox.showerror(t('msg.error_title'), str(e), parent=win)

        _Button(btn_frm, text=f"{ICONS['export']}  {t('compare.export')}",
                command=_export).pack(side=tk.LEFT)
        _Button(btn_frm, text=t('common.close'), command=win.destroy,
                width=9).pack(side=tk.RIGHT)
        win.bind('<Escape>', lambda e: win.destroy())

    def _toggle_spectra_visibility(self):
        """Bascule la visibilité des spectres sélectionnés."""
        sel = self.spectra_tree.selection()
        self._push_undo(t('action.toggle_visibility'))
        if not sel:
            # Sans sélection, bascule tout
            for s in self.spectra_meta:
                s['visible'] = not s['visible']
        else:
            for iid in sel:
                idx = int(iid)
                self.spectra_meta[idx]['visible'] = not self.spectra_meta[idx]['visible']
        self._refresh_spectra_tree()
        self._schedule_update()

    def _remove_spectrum_from_list(self):
        """Retire le(s) spectre(s) sélectionné(s) de la liste, sans toucher au
        disque. Utile pour nettoyer la liste après avoir cumulé plusieurs
        dossiers via le bouton ➕."""
        sel = self.spectra_tree.selection()
        if not sel:
            messagebox.showinfo(t('msg.info_title'),
                                 t('msg.no_spectrum_selected'))
            return
        # Récupérer les indices à retirer
        indices_to_remove = sorted({int(iid) for iid in sel}, reverse=True)
        n = len(indices_to_remove)
        # Demander confirmation pour éviter les retraits accidentels
        if not messagebox.askyesno(t('msg.warning_title'),
                                    t('msg.confirm_remove_from_list', n=n)):
            return
        self._push_undo(t('action.remove_from_list'))
        # Retirer en partant de la fin pour que les indices restent valides
        for idx in indices_to_remove:
            if 0 <= idx < len(self.spectra_meta):
                del self.spectra_meta[idx]
        self._refresh_spectra_tree()
        self._schedule_update()
        self.status_var.set(f"− {n} spectre(s) retiré(s) de la liste")

    # ============================================================
    # CALLBACKS — Références (avec laser individuel)
    # ============================================================
    def _scan_rruff_folder(self, force=False):
        folder = self._current_lib_path()
        if not force and self._rruff_cache is not None and self._rruff_cache_key == folder:
            return self._rruff_cache

        minerals = {}
        # Détermine si on est en mode "racine" (= lib_folder direct, sans sous-dossier
        # database). Dans ce cas on scanne RÉCURSIVEMENT pour inclure les .txt
        # éventuellement rangés dans des sous-dossiers.
        is_root_mode = (folder == self.lib_folder_var.get())

        def _process_file(filename):
            m = re.split(r'[_-]*R\d+', filename, maxsplit=1, flags=re.IGNORECASE)
            if len(m) > 1:
                mineral = m[0].rstrip('_-').lower()
            else:
                mineral = re.sub(r'[a-zA-Z]*\d.*', '', filename).rstrip('_-').lower()
            if mineral:
                minerals.setdefault(mineral, []).append(filename)

        if os.path.isdir(folder):
            if is_root_mode:
                # Mode racine : parcours récursif de TOUS les sous-dossiers
                for root_dir, _dirs, file_list in os.walk(folder):
                    for f in sorted(file_list):
                        if not f.lower().endswith('.txt'):
                            continue
                        # On stocke le chemin relatif au folder racine pour pouvoir
                        # le retrouver ensuite (ex: "Subset/Abellaite__R250095.txt")
                        rel = os.path.relpath(os.path.join(root_dir, f), folder)
                        # Mais le pattern de mineral utilise juste le nom de fichier
                        m = re.split(r'[_-]*R\d+', f, maxsplit=1, flags=re.IGNORECASE)
                        if len(m) > 1:
                            mineral = m[0].rstrip('_-').lower()
                        else:
                            mineral = re.sub(r'[a-zA-Z]*\d.*', '', f).rstrip('_-').lower()
                        if mineral:
                            # Stocker le chemin relatif pour que load_spectrum trouve le fichier
                            minerals.setdefault(mineral, []).append(rel)
            else:
                # Mode sous-dossier : scan plat (non récursif) du sous-dossier choisi
                for f in sorted(os.listdir(folder)):
                    if not f.lower().endswith('.txt'):
                        continue
                    _process_file(f)

        self._rruff_cache = minerals
        self._rruff_cache_key = folder
        return minerals

    def _update_mineral_suggestions(self):
        """Liste les minéraux disponibles dans le DOSSIER RRUFF (pas la DB).
        Si une info DB existe pour un minéral (formule, groupe), elle est ajoutée."""
        self.suggest_listbox.delete(0, tk.END)
        rruff = self._scan_rruff_folder()

        if not rruff:
            self.suggest_listbox.insert(
                tk.END, "  ⚠ Aucun .txt trouvé dans le dossier RRUFF")
            return

        query = self.search_var.get().strip().lower()

        # Construire la liste de tuples (score, mineral, n_files, formula, group)
        results = []
        for mineral in rruff:
            n_files = len(rruff[mineral])
            db_info = RAMAN_DB.get(mineral, {})
            formula = db_info.get('formula', '')
            group   = db_info.get('group', '')
            # Versions normalisées pour la recherche : permet à l'utilisateur
            # de taper "TiO2" et de matcher "TiO$_2$" (ou "TiO₂")
            formula_uni  = latex_to_unicode(formula).lower() if formula else ''
            formula_lc   = formula.lower() if formula else ''

            if not query:
                score = 1   # tout est inclus, ordre alphabétique
            elif query == mineral:
                score = 100
            elif mineral.startswith(query):
                score = 90
            elif query in mineral:
                score = 70
            elif formula and (query in formula_lc or query in formula_uni):
                score = 60
            elif group and query in group.lower():
                score = 50
            else:
                continue   # pas de match

            results.append((score, mineral, n_files, formula, group))

        # Tri : par score décroissant, puis alphabétique
        results.sort(key=lambda r: (-r[0], r[1]))

        if not results:
            self.suggest_listbox.insert(tk.END,
                f"  (Aucun résultat pour « {query} » dans {len(rruff)} minéraux RRUFF)")
            return

        # Affichage : <mineral>  <n>x  <formula_unicode>  [group_unicode]
        # La formule et le groupe sont convertis de LaTeX → Unicode pour être
        # lisibles directement dans la Listbox Tk (qui ne sait pas rendre du
        # mathtext). Si le groupe contient des indices/symboles grecs (ex. d'un
        # ajout futur dans raman_db), ils s'afficheront proprement.
        for _, mineral, n, formula, group in results[:60]:
            n_str = f"{n}×" if n > 1 else "  "
            formula_uni = latex_to_unicode(formula) if formula else ''
            group_uni   = latex_to_unicode(group) if group else ''
            extras = []
            if formula_uni: extras.append(formula_uni)
            if group_uni:   extras.append(f"[{group_uni}]")
            extras_str = "   ".join(extras)
            self.suggest_listbox.insert(
                tk.END, f"{mineral:<25s} {n_str:<3s} {extras_str}")

    def _show_full_mineral_list(self):
        rruff = self._scan_rruff_folder(force=True)
        if not rruff:
            messagebox.showinfo(t('msg.info_title'),
                t('msg.no_txt_found', path=self._current_lib_path()))
            return
        n_min = len(rruff)
        n_files = sum(len(v) for v in rruff.values())
        win = _Toplevel(self)
        win.title(t('dlg.mineral.title', n_min=n_min, n_files=n_files))
        win.geometry("780x580")
        win.transient(self)
        try:
            win.lift(); win.focus_force()
        except Exception:
            pass

        # --- Champ de recherche en haut ---
        search_frm = _Frame(win)
        search_frm.pack(fill=tk.X, padx=12, pady=10)
        _Label(search_frm, text=f"{ICONS['search']} {t('dlg.mineral.search')}").pack(side=tk.LEFT)
        list_search_var = tk.StringVar()
        search_ent = _Entry(search_frm, textvariable=list_search_var, width=30)
        search_ent.pack(side=tk.LEFT, padx=8, fill=tk.X, expand=True)
        try:
            search_ent.focus_set()
        except Exception:
            pass
        count_var = tk.StringVar()
        _Label(search_frm, textvariable=count_var,
               foreground='gray').pack(side=tk.LEFT, padx=8)

        # --- Liste (Listbox tkinter, pas d'équivalent CTk) ---
        lb_frame = _Frame(win)
        lb_frame.pack(fill=tk.BOTH, expand=True, padx=12, pady=(0, 6))
        lb = tk.Listbox(lb_frame, font=('Consolas', 10),
                        relief='flat', borderwidth=1,
                        highlightthickness=0)
        sb = ttk.Scrollbar(lb_frame, orient='vertical', command=lb.yview)
        lb.configure(yscrollcommand=sb.set)
        lb.pack(side=tk.LEFT, fill=tk.BOTH, expand=True)
        sb.pack(side=tk.RIGHT, fill=tk.Y)

        # Appliquer la couleur du thème à la Listbox (comme pour la listbox de suggestions)
        if HAS_CTK:
            try:
                mode = ctk.get_appearance_mode().lower()
                if mode == 'dark':
                    lb.configure(bg='#2b2b2b', fg='#e0e0e0',
                                 selectbackground='#4a90d9',
                                 selectforeground='white')
                else:
                    lb.configure(bg='#ffffff', fg='#000000',
                                 selectbackground='#0078d7',
                                 selectforeground='white')
            except Exception:
                pass

        # Pré-calculer la liste des entrées une fois.
        # On stocke la formule LaTeX brute ET la version Unicode pour pouvoir
        # rechercher sur les deux et afficher la version Unicode lisible.
        # Idem pour le groupe.
        entries = []  # (mineral, formula_l, formula_uni_l, group_l, group_uni_l, line_text)
        for mineral in sorted(rruff.keys()):
            n_files = len(rruff[mineral])
            db_info = RAMAN_DB.get(mineral, {})
            formula = db_info.get('formula', '')
            group   = db_info.get('group', '')
            formula_uni = latex_to_unicode(formula) if formula else ''
            group_uni   = latex_to_unicode(group) if group else ''
            extras = []
            if formula_uni: extras.append(formula_uni)
            if group_uni:   extras.append(f"[{group_uni}]")
            in_db = ' ✓DB' if mineral in RAMAN_DB else '    '
            line = f"{mineral:<25s} {n_files:>2d}×  {' '.join(extras):<35s}{in_db}"
            entries.append((mineral, formula.lower(), formula_uni.lower(),
                            group.lower(), group_uni.lower(), line))

        def _refresh_filter():
            query = list_search_var.get().strip().lower()
            lb.delete(0, tk.END)
            shown = 0
            for mineral, formula_l, formula_uni_l, group_l, group_uni_l, line in entries:
                if (not query
                        or query in mineral
                        or query in formula_l
                        or query in formula_uni_l
                        or query in group_l
                        or query in group_uni_l):
                    lb.insert(tk.END, line)
                    shown += 1
            count_var.set(f"{shown}/{len(entries)}")

        list_search_var.trace_add('write', lambda *a: _refresh_filter())
        _refresh_filter()

        def _pick():
            sel = lb.curselection()
            if sel:
                mineral_name = lb.get(sel[0]).split()[0]
                self.search_var.set(mineral_name)
                self._update_mineral_suggestions()
                win.destroy()

        btn_row = _Frame(win)
        btn_row.pack(side=tk.BOTTOM, fill=tk.X, padx=12, pady=10)
        _AccentButton(btn_row, text=f"{ICONS['check']} {t('common.select')}",
                       accent='primary', command=_pick).pack(side=tk.RIGHT, padx=4)
        _Button(btn_row, text=t('common.close'), command=win.destroy,
                width=9).pack(side=tk.RIGHT, padx=4)
        lb.bind('<Double-Button-1>', lambda e: _pick())
        win.bind('<Return>', lambda e: _pick())
        win.bind('<Escape>', lambda e: win.destroy())

    def _show_groups(self):
        groups = list_groups()
        if not groups:
            messagebox.showinfo(t('msg.info_title'), t('msg.no_groups'))
            return
        win = _Toplevel(self)
        win.title(t('dlg.groups.title'))
        win.geometry("640x560")
        win.transient(self)
        try:
            win.lift(); win.focus_force()
        except Exception:
            pass

        _Label(win, text=t('dlg.groups.header'),
               font=('TkDefaultFont', 12, 'bold')).pack(
            anchor='w', padx=14, pady=(12, 4))

        txt_frame = _Frame(win)
        txt_frame.pack(fill=tk.BOTH, expand=True, padx=14, pady=(0, 6))
        txt = tk.Text(txt_frame, wrap='none',
                      relief='flat', borderwidth=1,
                      highlightthickness=0,
                      font=('Consolas', 10))
        sb = ttk.Scrollbar(txt_frame, orient='vertical', command=txt.yview)
        txt.configure(yscrollcommand=sb.set)
        txt.pack(side=tk.LEFT, fill=tk.BOTH, expand=True)
        sb.pack(side=tk.RIGHT, fill=tk.Y)

        # Thème
        if HAS_CTK:
            try:
                mode = ctk.get_appearance_mode().lower()
                if mode == 'dark':
                    txt.configure(bg='#2b2b2b', fg='#e0e0e0',
                                  insertbackground='#e0e0e0')
                else:
                    txt.configure(bg='#ffffff', fg='#000000')
            except Exception:
                pass

        for group, mins in sorted(groups.items()):
            txt.insert(tk.END, f"═══ {group.upper()} ═══\n", 'hdr')
            for m in sorted(mins):
                formula = RAMAN_DB[m].get('formula', '')
                txt.insert(tk.END, f"  {m:<22s} {formula}\n")
            txt.insert(tk.END, "\n")
        txt.tag_configure('hdr', font=('TkDefaultFont', 10, 'bold'))
        txt.configure(state='disabled')

        _Button(win, text=t('common.close'), command=win.destroy,
                width=9).pack(pady=(0, 12))
        win.bind('<Escape>', lambda e: win.destroy())

    def _refresh_refs_list(self):
        for item in self.refs_tree.get_children():
            self.refs_tree.delete(item)
        for i, r in enumerate(self.refs):
            check = '☑' if r.get('visible', True) else '☐'
            alias = r.get('display_name', '') or clean_label(r['filename'])
            color_cell = '●' if r.get('color') else '○'
            ls_key = r.get('linestyle') or self.ref_linestyle_var.get()
            ls_cell = self._linestyle_glyph(ls_key)
            tag = f'color_ref_{i}'
            self.refs_tree.insert('', 'end', iid=str(i), values=(
                check, color_cell, ls_cell, r['mineral'], r['filename'], r['laser'], alias),
                tags=(tag,))
            if r.get('color'):
                self.refs_tree.tag_configure(tag, foreground=r['color'])
            else:
                self.refs_tree.tag_configure(tag, foreground='gray')

    def _on_ref_click(self, event):
        """Clic : ✓ = visibilité, 🎨 = couleur, ╌ = linestyle."""
        region = self.refs_tree.identify('region', event.x, event.y)
        if region != 'cell':
            return
        col = self.refs_tree.identify_column(event.x)
        iid = self.refs_tree.identify_row(event.y)
        if not iid:
            return
        idx = int(iid)
        if col == '#1':      # visibilité
            self._push_undo(t('action.toggle_visibility'))
            self.refs[idx]['visible'] = not self.refs[idx].get('visible', True)
            self._refresh_refs_list()
            self._schedule_update()
        elif col == '#2':    # couleur
            self._pick_ref_color(idx)
        elif col == '#3':    # linestyle
            self._pick_ref_linestyle(idx)

    def _pick_ref_linestyle(self, idx):
        menu = tk.Menu(self, tearoff=0)
        current = self.refs[idx].get('linestyle')
        menu.add_command(label=f"(Défaut global : {self.ref_linestyle_var.get()})",
                         command=lambda: self._set_ref_linestyle(idx, None))
        menu.add_separator()
        for key, label, _ in LINESTYLES:
            prefix = '  ● ' if key == current else '      '
            menu.add_command(label=f"{prefix}{label}",
                             command=lambda k=key: self._set_ref_linestyle(idx, k))
        x, y = self.winfo_pointerxy()
        try:
            menu.tk_popup(x, y)
        finally:
            menu.grab_release()

    def _set_ref_linestyle(self, idx, ls_key):
        self.refs[idx]['linestyle'] = ls_key
        self._refresh_refs_list()
        self._schedule_update()

    def _pick_ref_color(self, idx):
        from tkinter import colorchooser
        current = self.refs[idx].get('color') or '#1f77b4'
        result = colorchooser.askcolor(
            color=current,
            title=f"Couleur pour : {self.refs[idx]['mineral']}")
        if result and result[1]:
            self._push_undo(t('action.change_color'))
            self.refs[idx]['color'] = result[1]
            self._refresh_refs_list()
            self._schedule_update()

    def _reset_ref_color(self, idx):
        self._push_undo(t('action.change_color'))
        self.refs[idx]['color'] = None
        self._refresh_refs_list()
        self._schedule_update()

    def _on_ref_rightclick(self, event):
        """Menu contextuel clic droit sur une ref."""
        iid = self.refs_tree.identify_row(event.y)
        if not iid:
            return
        idx = int(iid)
        self.refs_tree.selection_set(iid)

        menu = tk.Menu(self, tearoff=0)
        menu.add_command(label="🎨 Changer couleur…",
                         command=lambda: self._pick_ref_color(idx))
        menu.add_command(label="↺ Réinitialiser couleur",
                         command=lambda: self._reset_ref_color(idx))
        menu.add_separator()
        menu.add_command(label="╌ Changer style ligne…",
                         command=lambda: self._pick_ref_linestyle(idx))
        menu.add_command(label="↺ Réinitialiser style ligne",
                         command=lambda: self._set_ref_linestyle(idx, None))
        menu.add_separator()
        menu.add_command(label="✎ Modifier (laser + alias)…",
                         command=self._edit_reference_dialog)
        menu.add_command(label="👁 Basculer visibilité",
                         command=lambda: self._toggle_single_ref_visibility(idx))
        menu.add_separator()
        menu.add_command(label="🗑 Retirer",
                         command=lambda: self._remove_single_ref(idx))
        try:
            menu.tk_popup(event.x_root, event.y_root)
        finally:
            menu.grab_release()

    def _toggle_single_ref_visibility(self, idx):
        self.refs[idx]['visible'] = not self.refs[idx].get('visible', True)
        self._refresh_refs_list()
        self._schedule_update()

    def _remove_single_ref(self, idx):
        del self.refs[idx]
        self._refresh_refs_list()
        self._schedule_update()

    def _add_reference(self):
        sel = self.suggest_listbox.curselection()
        if not sel:
            messagebox.showwarning(t('msg.warning_title'), t('msg.no_mineral_selected'))
            return
        mineral = self.suggest_listbox.get(sel[0]).split()[0].lower()
        lib = self._current_lib_path()
        if not os.path.isdir(lib):
            messagebox.showerror(t('msg.error_title'), t('msg.rruff_not_found', path=lib))
            return
        all_refs = sorted(f for f in os.listdir(lib) if f.lower().endswith('.txt'))
        matches = [f for f in all_refs if mineral in f.lower()]
        if not matches:
            messagebox.showwarning(t('msg.warning_title'), t('msg.no_ref_for_mineral', name=mineral))
            return
        if len(matches) == 1:
            chosen = matches
        else:
            chosen = self._multi_select_dialog_with_preview(
                t('dlg.multisel.files_for', name=mineral), matches, lib)
            if not chosen:
                return
        self._push_undo(t('action.add_ref'))
        default_laser = self.default_ref_laser_var.get()
        n_detected = 0
        for f in chosen:
            # Auto-détection du laser depuis le nom de fichier RRUFF
            detected_laser = detect_laser_from_filename(f)
            laser = detected_laser if detected_laser else default_laser
            if detected_laser:
                n_detected += 1
            self.refs.append({
                'mineral': mineral, 'filename': f, 'laser': laser,
                'display_name': clean_label(f),
                'visible': True,
                'color': None,
                'linestyle': None,
            })
        self._refresh_refs_list()
        # Message de statut précisant la détection
        if n_detected == len(chosen):
            msg = f"✓ Ajout : {mineral} ({len(chosen)} ref(s), laser auto-détecté)"
        elif n_detected > 0:
            msg = f"✓ Ajout : {mineral} ({len(chosen)} ref(s), {n_detected} laser auto + {len(chosen)-n_detected} @ {default_laser})"
        else:
            msg = f"✓ Ajout : {mineral} ({len(chosen)} ref(s) @ {default_laser})"
        self.status_var.set(msg)
        self._schedule_update()

    def _remove_reference(self):
        sel = self.refs_tree.selection()
        if not sel:
            return
        self._push_undo(t('action.remove_ref'))
        idxs = sorted([int(s) for s in sel], reverse=True)
        for i in idxs:
            del self.refs[i]
        self._refresh_refs_list()
        self._schedule_update()

    def _edit_reference_dialog(self):
        """Dialog pour modifier le laser et l'alias d'une référence."""
        sel = self.refs_tree.selection()
        if not sel:
            messagebox.showinfo(t('msg.info_title'), t('msg.no_ref_selected'))
            return
        idx = int(sel[0])
        ref = self.refs[idx]

        win = _Toplevel(self)
        win.title(t('dlg.editref.title', n=idx + 1))
        win.geometry("620x270")
        win.transient(self)
        win.grab_set()
        win.resizable(False, False)
        try:
            win.lift(); win.focus_force()
        except Exception:
            pass

        frm = _Frame(win)
        frm.pack(fill=tk.BOTH, expand=True, padx=18, pady=16)

        _Label(frm, text=t('dlg.editref.mineral', name=ref['mineral']),
               font=('TkDefaultFont', 11, 'bold')).grid(
            row=0, column=0, columnspan=2, sticky='w', pady=(0, 4))
        _Label(frm, text=t('dlg.editref.file', name=ref['filename']),
               font=('TkDefaultFont', 9),
               foreground='gray').grid(
            row=1, column=0, columnspan=2, sticky='w', pady=(0, 8))

        _Label(frm, text=t('dlg.editref.laser')).grid(row=2, column=0, sticky='w', pady=8)
        laser_var = tk.StringVar(value=ref['laser'])
        laser_cb = _Combobox(frm, textvariable=laser_var, width=15,
                              values=('325 nm', '405 nm', '457 nm', '488 nm', '514 nm',
                                      '532 nm', '633 nm', '647 nm', '785 nm', '830 nm', '1064 nm'))
        laser_cb.grid(row=2, column=1, sticky='w', pady=8, padx=10)

        _Label(frm, text=t('dlg.editref.alias')).grid(row=3, column=0, sticky='w', pady=8)
        alias_var = tk.StringVar(value=ref.get('display_name', '') or clean_label(ref['filename']))
        ent_alias = _Entry(frm, textvariable=alias_var, width=35)
        ent_alias.grid(row=3, column=1, sticky='ew', pady=8, padx=10)
        try:
            ent_alias.focus_set()
        except Exception:
            pass
        frm.columnconfigure(1, weight=1)

        btn_frm = _Frame(win)
        btn_frm.pack(fill=tk.X, padx=18, pady=(0, 14))

        def _ok():
            self._push_undo(t('action.edit_ref'))
            self.refs[idx]['laser'] = laser_var.get().strip()
            self.refs[idx]['display_name'] = alias_var.get().strip() or clean_label(ref['filename'])
            self._refresh_refs_list()
            self._schedule_update()
            win.destroy()

        def _reset_alias():
            alias_var.set(clean_label(ref['filename']))

        _Button(btn_frm, text=f"{ICONS['reset']} {t('dlg.editref.reset')}",
                command=_reset_alias).pack(side=tk.LEFT)
        _AccentButton(btn_frm, text=f"{ICONS['check']} {t('common.apply')}",
                       accent='primary', command=_ok,
                       width=11).pack(side=tk.RIGHT, padx=4)
        _Button(btn_frm, text=t('common.cancel'),
                command=win.destroy, width=9).pack(side=tk.RIGHT, padx=4)
        win.bind('<Return>', lambda e: _ok())
        win.bind('<Escape>', lambda e: win.destroy())

    def _multi_select_dialog_with_preview(self, title, items, lib_folder):
        """Dialog de sélection multi avec prévisualisation graphique."""
        win = _Toplevel(self)
        win.title(title)
        win.geometry("1000x560")
        win.transient(self)
        win.grab_set()
        win.minsize(720, 420)
        try:
            win.lift(); win.focus_force()
        except Exception:
            pass

        _Label(win, text=t('dlg.multisel.title', title=title),
               font=('TkDefaultFont', 9)).pack(pady=(10, 4), padx=12, anchor='w')

        # --- Paned : liste à gauche, preview à droite ---
        paned = tk.PanedWindow(win, orient=tk.HORIZONTAL, sashrelief='raised',
                                sashwidth=4, bg='#d9d9d9')
        paned.pack(fill=tk.BOTH, expand=True, padx=12, pady=4)

        # --- Panneau gauche : listbox ---
        left = _Frame(paned)
        paned.add(left, minsize=280, width=370, stretch='never')

        lb_frame = _Frame(left)
        lb_frame.pack(fill=tk.BOTH, expand=True, padx=4, pady=4)
        lb = tk.Listbox(lb_frame, selectmode=tk.EXTENDED, font=('Consolas', 9),
                        exportselection=False,
                        relief='flat', borderwidth=1,
                        highlightthickness=0)
        lb_sb = ttk.Scrollbar(lb_frame, orient='vertical', command=lb.yview)
        lb.configure(yscrollcommand=lb_sb.set)
        lb.pack(side=tk.LEFT, fill=tk.BOTH, expand=True)
        lb_sb.pack(side=tk.RIGHT, fill=tk.Y)
        # Thème pour la Listbox
        if HAS_CTK:
            try:
                mode = ctk.get_appearance_mode().lower()
                if mode == 'dark':
                    lb.configure(bg='#2b2b2b', fg='#e0e0e0',
                                 selectbackground="#00CBFD",
                                 selectforeground='white')
                else:
                    lb.configure(bg='#ffffff', fg='#000000',
                                 selectbackground="#00CBFD",
                                 selectforeground='white')
            except Exception:
                pass
        for it in items:
            lb.insert(tk.END, it)

        # --- Panneau droit : preview matplotlib ---
        right = _Frame(paned)
        paned.add(right, minsize=400, stretch='always')

        # Ligne 1 : checkbox overlay samples
        overlay_frame = _Frame(right)
        overlay_frame.pack(fill=tk.X, padx=4, pady=(4, 0))
        show_sample_var = tk.BooleanVar(value=True)
        _Checkbutton(overlay_frame,
                     text=t('dlg.multisel.overlay'),
                     variable=show_sample_var, text_color = 'black').pack(side=tk.LEFT)

        # Ligne 2 : X min / X max / Y min / Y max + Auto
        lim_frame = _Frame(right)
        lim_frame.pack(fill=tk.X, padx=4, pady=(4, 4))
        _Label(lim_frame, text="X :", text_color = 'black').pack(side=tk.LEFT)
        xmin_var_p = tk.StringVar()
        xmax_var_p = tk.StringVar()
        ymin_var_p = tk.StringVar()
        ymax_var_p = tk.StringVar()
        _Entry(lim_frame, textvariable=xmin_var_p, width=7).pack(side=tk.LEFT, padx=2)
        _Label(lim_frame, text="–", text_color = 'black').pack(side=tk.LEFT)
        _Entry(lim_frame, textvariable=xmax_var_p, width=7).pack(side=tk.LEFT, padx=2)
        _Label(lim_frame, text="   Y :", text_color = 'black').pack(side=tk.LEFT)
        _Entry(lim_frame, textvariable=ymin_var_p, width=6).pack(side=tk.LEFT, padx=2)
        _Label(lim_frame, text="–", text_color = 'black').pack(side=tk.LEFT)
        _Entry(lim_frame, textvariable=ymax_var_p, width=6).pack(side=tk.LEFT, padx=2)

        def _auto_lims():
            xmin_var_p.set(''); xmax_var_p.set('')
            ymin_var_p.set(''); ymax_var_p.set('')
            _update_preview()

        _Button(lim_frame, text=t('dlg.multisel.auto'), width=5,
                command=_auto_lims, text_color = 'black').pack(side=tk.LEFT, padx=8)
        _Label(lim_frame, text=t('dlg.multisel.auto_hint'),
               text_color='black', font=('TkDefaultFont', 8)).pack(side=tk.LEFT)

        preview_fig = Figure(figsize=(5, 3.5), dpi=90)
        preview_ax = preview_fig.add_subplot(111)
        preview_ax.text(0.5, 0.5, t('dlg.multisel.preview_hint'),
                         ha='center', va='center', transform=preview_ax.transAxes,
                         fontsize=10, color='black')
        preview_ax.axis('off')
        preview_canvas = FigureCanvasTkAgg(preview_fig, master=right)
        preview_canvas.get_tk_widget().pack(fill=tk.BOTH, expand=True, padx=4, pady=4)

        # Pré-charger les samples visibles une seule fois
        sample_folder = self._current_sample_path()
        cached_samples = []
        if sample_folder and os.path.isdir(sample_folder):
            for s in self.spectra_meta:
                if not s.get('visible'):
                    continue
                try:
                    src_folder = s.get('sample_folder') or sample_folder
                    x, y = load_spectrum(os.path.join(src_folder, s['filename']))
                    cached_samples.append({
                        'label': s.get('display_name') or clean_label(s['filename']),
                        'x': x, 'y': y,
                    })
                except Exception:
                    continue

        def _parse_f(s):
            """Retourne float ou None si invalide/vide."""
            s = (s or '').strip().replace(',', '.')
            if not s:
                return None
            try:
                return float(s)
            except ValueError:
                return None

        # Débouncer _update_preview : éviter les redraws matplotlib à chaque touche
        preview_job = [None]  # liste pour pouvoir modifier dans la closure
        def _schedule_preview():
            if preview_job[0] is not None:
                try: win.after_cancel(preview_job[0])
                except Exception: pass
            preview_job[0] = win.after(250, _update_preview)

        def _update_preview():
            preview_job[0] = None
            preview_fig.clear()
            ax = preview_fig.add_subplot(111)
            sel_idxs = lb.curselection()
            include_samples = show_sample_var.get() and cached_samples

            if not sel_idxs and not include_samples:
                ax.text(0.5, 0.5, t('dlg.multisel.preview_hint'),
                        ha='center', va='center', transform=ax.transAxes,
                        fontsize=10, color='black')
                ax.axis('off')
                preview_canvas.draw_idle()
                return

            # Charger les refs sélectionnées
            ref_specs = []
            for i in sel_idxs:
                fname = items[i]
                path = os.path.join(lib_folder, fname)
                try:
                    x, y = load_spectrum(path)
                    ref_specs.append((fname, x, y))
                except Exception:
                    continue

            # Plage x auto (bornes des données)
            all_x_mins = []
            all_x_maxs = []
            if ref_specs:
                all_x_mins.extend(x.min() for _, x, _ in ref_specs)
                all_x_maxs.extend(x.max() for _, x, _ in ref_specs)
            if include_samples:
                all_x_mins.extend(s['x'].min() for s in cached_samples)
                all_x_maxs.extend(s['x'].max() for s in cached_samples)

            if not all_x_mins:
                ax.text(0.5, 0.5, "⚠ Rien à afficher",
                        ha='center', va='center', transform=ax.transAxes,
                        fontsize=10, color='red')
                ax.axis('off')
                preview_canvas.draw_idle()
                return

            # Lire les bornes user (peuvent être None)
            xmin_u = _parse_f(xmin_var_p.get())
            xmax_u = _parse_f(xmax_var_p.get())
            ymin_u = _parse_f(ymin_var_p.get())
            ymax_u = _parse_f(ymax_var_p.get())

            norm_xmin = xmin_u if xmin_u is not None else min(all_x_mins)
            norm_xmax = xmax_u if xmax_u is not None else max(all_x_maxs)

            # 1) Tracer les refs
            if ref_specs:
                colors = plt.cm.tab10(np.linspace(0, 1, max(len(ref_specs), 1)))
                for (fname, x, y), color in zip(ref_specs, colors):
                    y_n = normalize_in_window(x, y, norm_xmin, norm_xmax)
                    ax.plot(x, y_n, color=color, linewidth=1.0, linestyle='--',
                            alpha=0.85,
                            label=f"Ref: {clean_label(fname)[:30]}", zorder=2)

            # 2) Tracer les samples par-dessus
            if include_samples:
                for s in cached_samples:
                    y_n = normalize_in_window(s['x'], s['y'], norm_xmin, norm_xmax)
                    ax.plot(s['x'], y_n, color='black', linewidth=1.8,
                            alpha=0.9,
                            label=f"Sample: {s['label'][:30]}", zorder=3)

            if xmin_u is not None or xmax_u is not None:
                ax.set_xlim(left=xmin_u, right=xmax_u)
            if ymin_u is not None or ymax_u is not None:
                ax.set_ylim(bottom=ymin_u, top=ymax_u)

            ax.set_xlabel(r'Raman shift (cm$^{-1}$)', fontsize=9)
            ax.set_ylabel(t('match.lbl.normalized_intensity'), fontsize=9)
            ax.tick_params(labelsize=8)
            ax.legend(loc='best', fontsize=7, frameon=True)
            preview_fig.tight_layout()
            preview_canvas.draw_idle()

        # Redessiner quand on change la checkbox ou les bornes (débouncé)
        show_sample_var.trace_add('write', lambda *a: _schedule_preview())
        for v in (xmin_var_p, xmax_var_p, ymin_var_p, ymax_var_p):
            v.trace_add('write', lambda *a: _schedule_preview())

        _update_preview()
        lb.bind('<<ListboxSelect>>', lambda e: _schedule_preview())

        # --- Boutons du bas ---
        sel_row = _Frame(win)
        sel_row.pack(fill=tk.X, padx=12, pady=(4, 2))
        _Button(sel_row, text=f"{ICONS['check']} {t('dlg.multisel.select_all')}",
                command=lambda: (lb.selection_set(0, tk.END), _update_preview())).pack(side=tk.LEFT)
        _Button(sel_row, text=f"{ICONS['cancel']} {t('dlg.multisel.deselect')}",
                command=lambda: (lb.selection_clear(0, tk.END), _update_preview())).pack(side=tk.LEFT, padx=8)

        result = []
        def _ok():
            for i in lb.curselection():
                result.append(lb.get(i))
            win.destroy()

        btn_row = _Frame(win)
        btn_row.pack(fill=tk.X, padx=12, pady=(4, 12))
        _AccentButton(btn_row, text=f"{ICONS['check']} {t('common.ok')}",
                       accent='primary', command=_ok, width=9).pack(side=tk.RIGHT, padx=4)
        _Button(btn_row, text=t('common.cancel'), command=win.destroy,
                width=9).pack(side=tk.RIGHT, padx=4)
        win.bind('<Return>', lambda e: _ok())
        win.bind('<Escape>', lambda e: win.destroy())

        win.wait_window()
        return result

    def _multi_select_dialog(self, title, items):
        """Version simple sans preview (gardée pour compat)."""
        win = tk.Toplevel(self)
        win.title(title)
        win.geometry("500x380")
        win.transient(self)
        win.grab_set()
        ttk.Label(win, text=title + " (Ctrl/Shift)").pack(pady=4)

        lb = tk.Listbox(win, selectmode=tk.EXTENDED)
        for it in items:
            lb.insert(tk.END, it)
        lb.pack(fill=tk.BOTH, expand=True, padx=8, pady=4)

        sel_row = ttk.Frame(win)
        sel_row.pack(fill=tk.X, padx=8, pady=(0, 4))
        ttk.Button(sel_row, text=t('btn.select_all'),
                   command=lambda: lb.selection_set(0, tk.END)).pack(side=tk.LEFT)
        ttk.Button(sel_row, text=t('btn.deselect_all'),
                   command=lambda: lb.selection_clear(0, tk.END)).pack(side=tk.LEFT, padx=6)

        result = []
        def _ok():
            for i in lb.curselection():
                result.append(lb.get(i))
            win.destroy()

        btn_row = ttk.Frame(win)
        btn_row.pack(fill=tk.X, padx=8, pady=6)
        ttk.Button(btn_row, text="✓ OK", command=_ok).pack(side=tk.RIGHT, padx=4)
        ttk.Button(btn_row, text=t('match.btn.cancel'), command=win.destroy).pack(side=tk.RIGHT, padx=4)
        win.bind('<Return>', lambda e: _ok())
        win.bind('<Escape>', lambda e: win.destroy())

        win.wait_window()
        return result

    # ============================================================
    # CALLBACKS — Pics
    # ============================================================
    def _new_peak_dict(self, pos, label='', mineral=''):
        """Crée un nouveau pic avec tous les champs par défaut."""
        return {
            'pos': float(pos),
            'label': label,
            'mineral': mineral,
            'dy_pos': 0.0,        # décalage y du numéro
            'dy_lbl': 0.0,        # décalage y du label
            'dx': 0.0,            # décalage x commun
            'show_marker': None,  # None = utiliser défaut global ; True/False = override
            'dy_marker': 0.0,     # décalage y du marqueur ▼
        }

    def _auto_peaks_dialog(self):
        if not self.refs:
            messagebox.showinfo(t('msg.info_title'), t('msg.no_refs_yet'))
            return
        win = _Toplevel(self)
        win.title(t('dlg.autopeak.title'))
        win.geometry("800x600")
        win.transient(self)
        try:
            win.lift(); win.focus_force()
        except Exception:
            pass

        _Label(win, text=t('dlg.autopeak.header'),
               font=('TkDefaultFont', 11, 'bold')).pack(anchor='w', padx=14, pady=(12, 6))

        # Notebook : ttk (pas d'équivalent CTk, fonctionne dans les deux)
        notebook = ttk.Notebook(win)
        notebook.pack(fill=tk.BOTH, expand=True, padx=14, pady=(0, 6))
        listboxes = []

        # Couleurs de la Listbox selon le thème
        if HAS_CTK:
            try:
                mode = ctk.get_appearance_mode().lower()
                if mode == 'dark':
                    lb_bg, lb_fg = '#2b2b2b', '#e0e0e0'
                    lb_sel_bg, lb_sel_fg = '#4a90d9', 'white'
                else:
                    lb_bg, lb_fg = '#ffffff', '#000000'
                    lb_sel_bg, lb_sel_fg = '#0078d7', 'white'
            except Exception:
                lb_bg, lb_fg = '#ffffff', '#000000'
                lb_sel_bg, lb_sel_fg = '#0078d7', 'white'
        else:
            lb_bg, lb_fg = '#ffffff', '#000000'
            lb_sel_bg, lb_sel_fg = '#0078d7', 'white'

        for mineral in list({r['mineral'] for r in self.refs}):
            if mineral not in RAMAN_DB:
                continue
            info = RAMAN_DB[mineral]
            all_pics = info.get('pics', [])
            frame = _Frame(notebook)
            # Tab title : ajout de la formule en Unicode pour identification rapide
            formula_uni = latex_to_unicode(info.get('formula', ''))
            group_uni   = latex_to_unicode(info.get('group', ''))
            tab_title = f"{mineral} ({len(all_pics)})"
            if formula_uni:
                tab_title = f"{mineral} {formula_uni} ({len(all_pics)})"
            notebook.add(frame, text=tab_title)
            # Header dans l'onglet : minéral + formule + groupe (tout en Unicode)
            header_text = f"{mineral.capitalize()}"
            if formula_uni:
                header_text += f" — {formula_uni}"
            if group_uni:
                header_text += f"   [{group_uni}]"
            _Label(frame, text=header_text,
                   font=('TkDefaultFont', 11, 'bold')).pack(anchor='w', padx=8, pady=6)

            lb_row = _Frame(frame)
            lb_row.pack(fill=tk.BOTH, expand=True, padx=8, pady=(0, 8))
            lb = tk.Listbox(lb_row, selectmode=tk.EXTENDED, font=('Consolas', 10),
                            relief='flat', borderwidth=1, highlightthickness=0,
                            bg=lb_bg, fg=lb_fg,
                            selectbackground=lb_sel_bg,
                            selectforeground=lb_sel_fg)
            sb = ttk.Scrollbar(lb_row, orient='vertical', command=lb.yview)
            lb.configure(yscrollcommand=sb.set)
            lb.pack(side=tk.LEFT, fill=tk.BOTH, expand=True)
            sb.pack(side=tk.RIGHT, fill=tk.Y)
            for pos, lbl, rel in all_pics:
                bar = '█' * int(rel * 10)
                # Convertir le label LaTeX en Unicode pour affichage Tk lisible
                # (ex. $E_g^{(1)}$ → E_g⁽¹⁾)
                lbl_show = latex_to_unicode(lbl) if lbl else '(no label)'
                lb.insert(tk.END, f" {pos:>6.0f} cm⁻¹  {bar:<10s} {rel:.2f}  {lbl_show}")
            listboxes.append((mineral, lb, all_pics))

        btn_frame = _Frame(win)
        btn_frame.pack(fill=tk.X, padx=14, pady=(4, 12))

        def _select_main():
            idx = notebook.index(notebook.select())
            mineral, lb, all_pics = listboxes[idx]
            lb.selection_clear(0, tk.END)
            for i, (_, _, rel) in enumerate(all_pics):
                if rel >= 0.5:
                    lb.selection_set(i)

        def _select_all():
            idx = notebook.index(notebook.select())
            _, lb, _ = listboxes[idx]
            lb.selection_set(0, tk.END)

        def _add_selected():
            # Vérifier qu'au moins un pic est sélectionné avant de pousser undo
            total_sel = sum(len(lb.curselection()) for _, lb, _ in listboxes)
            if total_sel == 0:
                win.destroy()
                return
            self._push_undo(t('action.auto_peaks'))
            added = 0
            for mineral, lb, all_pics in listboxes:
                for i in lb.curselection():
                    pos, lbl, _ = all_pics[i]
                    self.peaks.append(self._new_peak_dict(
                        pos=pos, label=lbl or '', mineral=mineral))
                    added += 1
            self._refresh_peaks_tree()
            self.status_var.set(f"✓ {added} pic(s) ajouté(s)")
            win.destroy()
            self._schedule_update()

        _Button(btn_frame, text=t('dlg.autopeak.main'),
                command=_select_main).pack(side=tk.LEFT, padx=2)
        _Button(btn_frame, text=t('dlg.autopeak.all'),
                command=_select_all).pack(side=tk.LEFT, padx=2)
        _AccentButton(btn_frame, text=f"{ICONS['check']} {t('dlg.autopeak.add')}",
                       accent='primary', command=_add_selected,
                       width=11).pack(side=tk.RIGHT, padx=4)
        _Button(btn_frame, text=t('common.cancel'), command=win.destroy,
                width=9).pack(side=tk.RIGHT, padx=4)
        win.bind('<Escape>', lambda e: win.destroy())

    def _add_manual_peak(self):
        try:
            pos = float(self.manual_pos_var.get().strip())
        except ValueError:
            messagebox.showerror(t('msg.error_title'), t('msg.invalid_position'))
            return
        self._push_undo(t('action.add_peak'))
        self.peaks.append(self._new_peak_dict(
            pos=pos,
            label=self.manual_lbl_var.get().strip(),
            mineral=self.manual_min_var.get().strip().lower(),
        ))
        self._refresh_peaks_tree()
        self.manual_pos_var.set('')
        self.manual_lbl_var.set('')
        self.manual_min_var.set('')
        self._schedule_update()

    def _refresh_peaks_tree(self):
        for item in self.peaks_tree.get_children():
            self.peaks_tree.delete(item)
        self.peaks.sort(key=lambda p: p['pos'])
        for i, p in enumerate(self.peaks):
            # Affichage : label converti en Unicode pour lisibilité Tk
            # (les données originales LaTeX restent dans p['label'])
            label_display = p.get('label', '') or ''
            label_display = latex_to_unicode(label_display) if label_display else '—'
            self.peaks_tree.insert('', 'end', iid=str(i), values=(
                f"{p['pos']:.1f}",
                label_display,
                p.get('mineral', '') or '—',
            ))

    def _remove_peak(self):
        sel = self.peaks_tree.selection()
        if not sel:
            return
        self._push_undo(t('action.remove_peak'))
        idxs = sorted([int(s) for s in sel], reverse=True)
        for i in idxs:
            del self.peaks[i]
        self._refresh_peaks_tree()
        self._schedule_update()

    def _clear_peaks(self):
        if self.peaks and not messagebox.askyesno(t('msg.warning_title'),
                                                   t('msg.confirm_clear_peaks')):
            return
        self._push_undo(t('action.clear_peaks'))
        self.peaks = []
        self._refresh_peaks_tree()
        self._schedule_update()

    def _export_peaks_csv(self):
        """Exporte la liste des pics en CSV (ouvrable dans Excel / LibreOffice)."""
        if not self.peaks:
            messagebox.showinfo(t('msg.info_title'), t('msg.peaks_none_to_export'))
            return
        default_dir = (self.csv_save_folder_var.get()
                       or self._current_sample_path()
                       or os.path.expanduser('~'))
        path = filedialog.asksaveasfilename(
            title="Exporter les pics en CSV",
            defaultextension=".csv",
            filetypes=[("CSV (Excel compatible)", "*.csv"), ("Tous fichiers", "*.*")],
            initialdir=default_dir,
            initialfile="pics_raman.csv",
        )
        if not path:
            return
        try:
            import csv
            # utf-8-sig ajoute un BOM pour qu'Excel ouvre correctement les accents.
            # Séparateur ';' = compatible Excel FR.
            with open(path, 'w', encoding='utf-8-sig', newline='') as f:
                w = csv.writer(f, delimiter=';')
                w.writerow([
                    'Position (cm-1)', 'Label', 'Minéral source',
                    'dy_pos', 'dy_lbl', 'dx', 'show_marker', 'dy_marker'
                ])
                for p in sorted(self.peaks, key=lambda x: x['pos']):
                    show_marker = p.get('show_marker')
                    if show_marker is None:
                        marker_str = 'default'
                    else:
                        marker_str = 'on' if show_marker else 'off'
                    w.writerow([
                        f"{p['pos']:.2f}",
                        p.get('label', ''),
                        p.get('mineral', ''),
                        f"{p.get('dy_pos', 0):.2f}",
                        f"{p.get('dy_lbl', 0):.2f}",
                        f"{p.get('dx', 0):.2f}",
                        marker_str,
                        f"{p.get('dy_marker', 0):.2f}",
                    ])
            messagebox.showinfo(t('msg.csv_export_ok'),
                f"{len(self.peaks)} pic(s) exporté(s) dans :\n\n{path}")
            self.status_var.set(f"✓ {len(self.peaks)} pics exportés en CSV")
        except Exception as e:
            messagebox.showerror(t('msg.error_title'), t('msg.csv_export_fail', err=e))

    def _edit_peak_dialog(self):
        """Dialog d'édition individuelle d'un pic — tous les contrôles."""
        sel = self.peaks_tree.selection()
        if not sel:
            messagebox.showinfo(t('msg.info_title'), t('msg.no_peak_selected'))
            return
        idx = int(sel[0])
        peak = self.peaks[idx]

        win = _Toplevel(self)
        win.title(t('dlg.editpeak.title', n=idx + 1))
        win.geometry("500x580")
        win.transient(self)
        win.grab_set()
        win.resizable(False, False)
        try:
            win.lift(); win.focus_force()
        except Exception:
            pass

        frm = _Frame(win)
        frm.pack(fill=tk.BOTH, expand=True, padx=16, pady=14)

        # === Section 1 : contenu ===
        sec1 = _LabelFrame(frm, text=t('dlg.editpeak.content'))
        sec1.pack(fill=tk.X, pady=(0, 10))
        sec1_in = _lf_inner(sec1)
        _Label(sec1_in, text=t('dlg.editpeak.position')).grid(row=0, column=0, sticky='w', padx=8, pady=4)
        pos_var = tk.StringVar(value=f"{peak['pos']:.2f}")
        pos_entry = _Entry(sec1_in, textvariable=pos_var, width=18)
        pos_entry.grid(row=0, column=1, sticky='ew', padx=8, pady=4)
        try:
            pos_entry.focus_set()
            if HAS_CTK and hasattr(pos_entry, '_entry'):
                pos_entry._entry.select_range(0, tk.END)
            else:
                pos_entry.select_range(0, tk.END)
        except Exception:
            pass
        _Label(sec1_in, text=t('dlg.editpeak.label')).grid(row=1, column=0, sticky='w', padx=8, pady=4)
        lbl_var = tk.StringVar(value=peak.get('label', ''))
        _Entry(sec1_in, textvariable=lbl_var, width=18).grid(row=1, column=1, sticky='ew', padx=8, pady=4)
        _Label(sec1_in, text=t('dlg.editpeak.source')).grid(row=2, column=0, sticky='w', padx=8, pady=4)
        min_var = tk.StringVar(value=peak.get('mineral', ''))
        _Entry(sec1_in, textvariable=min_var, width=18).grid(row=2, column=1, sticky='ew', padx=8, pady=4)
        sec1_in.columnconfigure(1, weight=1)

        # === Section 2 : décalages position/label ===
        sec2 = _LabelFrame(frm, text=t('dlg.editpeak.offsets'))
        sec2.pack(fill=tk.X, pady=(0, 8))
        sec2_in = _lf_inner(sec2)
        _Label(sec2_in, text=t('dlg.editpeak.dy_pos')).grid(row=0, column=0, sticky='w', padx=8, pady=4)
        dypos_var = tk.DoubleVar(value=peak.get('dy_pos', 0.0))
        _Spinbox(sec2_in, from_=-5.0, to=5.0, increment=0.05, format='%.2f',
                 textvariable=dypos_var, width=10).grid(row=0, column=1, sticky='w', padx=8, pady=4)
        _Label(sec2_in, text=t('dlg.editpeak.dy_lbl')).grid(row=1, column=0, sticky='w', padx=8, pady=4)
        dylbl_var = tk.DoubleVar(value=peak.get('dy_lbl', 0.0))
        _Spinbox(sec2_in, from_=-5.0, to=5.0, increment=0.05, format='%.2f',
                 textvariable=dylbl_var, width=10).grid(row=1, column=1, sticky='w', padx=8, pady=4)
        _Label(sec2_in, text=t('dlg.editpeak.dx')).grid(row=2, column=0, sticky='w', padx=8, pady=4)
        dx_var = tk.DoubleVar(value=peak.get('dx', 0.0))
        _Spinbox(sec2_in, from_=-200.0, to=200.0, increment=2.0, format='%.1f',
                 textvariable=dx_var, width=10).grid(row=2, column=1, sticky='w', padx=8, pady=4)
        sec2_in.columnconfigure(1, weight=1)

        # === Section 3 : marqueur ▼ ===
        sec3 = _LabelFrame(frm, text=t('dlg.editpeak.marker'))
        sec3.pack(fill=tk.X, pady=(0, 8))
        sec3_in = _lf_inner(sec3)
        current_marker = peak.get('show_marker', None)
        marker_state_var = tk.StringVar(value=
            'default' if current_marker is None else ('on' if current_marker else 'off'))
        marker_row = _Frame(sec3_in)
        marker_row.pack(fill=tk.X, padx=8, pady=4)
        _Label(marker_row, text=t('dlg.editpeak.show')).pack(side=tk.LEFT)
        def _rb(parent, text, value):
            if HAS_CTK:
                return ctk.CTkRadioButton(parent, text=text,
                                           variable=marker_state_var, value=value)
            return ttk.Radiobutton(parent, text=text,
                                    variable=marker_state_var, value=value)
        _rb(marker_row, t('dlg.editpeak.default'), 'default').pack(side=tk.LEFT, padx=6)
        _rb(marker_row, t('dlg.editpeak.force_on'), 'on').pack(side=tk.LEFT, padx=6)
        _rb(marker_row, t('dlg.editpeak.force_off'), 'off').pack(side=tk.LEFT, padx=6)

        marker_dy_row = _Frame(sec3_in)
        marker_dy_row.pack(fill=tk.X, padx=8, pady=4)
        _Label(marker_dy_row, text=t('dlg.editpeak.dy_marker')).pack(side=tk.LEFT)
        dymark_var = tk.DoubleVar(value=peak.get('dy_marker', 0.0))
        _Spinbox(marker_dy_row, from_=-2.0, to=2.0, increment=0.02, format='%.2f',
                 textvariable=dymark_var, width=10).pack(side=tk.LEFT, padx=8)

        # === Boutons ===
        btn_frm = _Frame(win)
        btn_frm.pack(fill=tk.X, padx=16, pady=(0, 14))

        # Sauvegarder l'état initial du pic pour pouvoir l'annuler proprement
        # à la fermeture en cas de Cancel.
        import copy
        initial_peak = copy.deepcopy(peak)

        # Live preview : à chaque modif, on met à jour le pic et redraw.
        # IMPORTANT : on garde une RÉFÉRENCE au dict du pic plutôt que son
        # index, car _refresh_peaks_tree() trie self.peaks par position.
        # Si on modifie pos de 650→200, l'index du pic change après le tri,
        # et l'ancien index pointerait vers un AUTRE pic — d'où le bug où
        # plusieurs pics se trouvaient écrasés.
        self._push_undo(t('action.edit_peak'))
        peak_ref = self.peaks[idx]  # référence stable au dict du pic

        def _live_apply(*_args):
            try:
                new_pos = float(pos_var.get().strip())
            except (ValueError, tk.TclError):
                return
            mstate = marker_state_var.get()
            try:
                # Mutation IN-PLACE du dict du pic (pas de réassignation par index).
                # Comme c'est le même dict, le tri ne casse pas notre référence.
                peak_ref.clear()
                peak_ref.update({
                    'pos': new_pos,
                    'label': lbl_var.get().strip(),
                    'mineral': min_var.get().strip().lower(),
                    'dy_pos': float(dypos_var.get()),
                    'dy_lbl': float(dylbl_var.get()),
                    'dx':     float(dx_var.get()),
                    'show_marker': None if mstate == 'default' else (mstate == 'on'),
                    'dy_marker':  float(dymark_var.get()),
                })
                self._refresh_peaks_tree()
                self._schedule_update(delay=80)
            except (ValueError, tk.TclError):
                pass

        # Branchement live sur toutes les vars
        for v in (pos_var, lbl_var, min_var, dypos_var, dylbl_var, dx_var,
                  marker_state_var, dymark_var):
            v.trace_add('write', _live_apply)

        def _ok():
            # Validation finale avant fermeture
            try:
                float(pos_var.get().strip())
            except ValueError:
                messagebox.showerror(t('msg.error_title'), t('msg.invalid_position'), parent=win)
                return
            # _live_apply a déjà tout appliqué, on ferme juste
            win.destroy()

        def _cancel():
            # Restaurer l'état initial du pic via mutation in-place (même
            # raison que _live_apply : peak_ref pointe toujours vers le bon
            # dict dans self.peaks même après les sorts intermédiaires).
            peak_ref.clear()
            peak_ref.update(initial_peak)
            # Retirer le push_undo qu'on avait fait, puisqu'on annule
            if self._undo_stack:
                self._undo_stack.pop()
            self._refresh_peaks_tree()
            self._schedule_update(delay=50)
            win.destroy()

        def _reset_offsets():
            dypos_var.set(0.0); dylbl_var.set(0.0); dx_var.set(0.0)
            dymark_var.set(0.0); marker_state_var.set('default')

        _Button(btn_frm, text=f"{ICONS['reset']} {t('dlg.editpeak.reset')}",
                command=_reset_offsets).pack(side=tk.LEFT)
        _AccentButton(btn_frm, text=f"{ICONS['check']} {t('common.apply')}",
                       accent='primary', command=_ok, width=11).pack(side=tk.RIGHT, padx=4)
        _Button(btn_frm, text=t('common.cancel'), command=_cancel,
                width=9).pack(side=tk.RIGHT, padx=4)
        win.bind('<Return>', lambda e: _ok())
        win.bind('<Escape>', lambda e: _cancel())
        # Si l'utilisateur ferme par la croix, traiter comme Cancel
        win.protocol('WM_DELETE_WINDOW', _cancel)

    # ============================================================
    # NOM AUTO de sauvegarde + RESET
    # ============================================================
    def _auto_save_name(self):
        """Génère un nom de fichier auto à partir des spectres visibles + refs.
        Format : Fig_Raman_<sample(s)>_<specs>_vs_<refs>
        Le nom du sample est dérivé des dossiers RÉELS des spectres visibles
        (pas du combobox active sample qui peut être différent en multi-dossiers).
        """
        # Récupérer les noms courts des spectres visibles (cochés)
        visible_specs = [s for s in self.spectra_meta if s.get('visible', False)]

        # Sample = dossiers réels des spectres visibles, dédupliqués dans l'ordre.
        # Si aucun spectre visible : fallback sur l'active sample du combobox.
        sample_folders_seen = []
        for s in visible_specs:
            sf = s.get('sample_folder')
            if sf:
                bn = os.path.basename(os.path.normpath(sf))
                if bn and bn not in sample_folders_seen:
                    sample_folders_seen.append(bn)
        if sample_folders_seen:
            # Concaténer les noms de dossiers (max 3 pour rester court)
            if len(sample_folders_seen) <= 3:
                sample = "-".join(sample_folders_seen)
            else:
                sample = "-".join(sample_folders_seen[:3]) + f"_p{len(sample_folders_seen)}"
        else:
            sample = self.sample_folder_var.get() or 'sample'

        if visible_specs:
            # Utiliser display_name (alias) sinon nom de fichier sans extension
            names = []
            for s in visible_specs:
                name = s.get('display_name') or os.path.splitext(s['filename'])[0]
                # Garder seulement la dernière partie (ex: "_10042026" → "10042026")
                short = name.split('_')[-1] if '_' in name else name
                names.append(short)
            spec_short = safe_filename('_'.join(names))[:40] or 'spec'
        else:
            spec_short = 'spec'
        ref_short = safe_filename('_'.join(
            sorted({r['mineral'] for r in self.refs}))) or 'noref'
        self.save_name_var.set(f"Fig_Raman_{safe_filename(sample)}_{spec_short}_vs_{ref_short}")

    def _apply_publication_preset(self):
        """Configure la Section 7 pour export publication-ready :
        - DPI : 600
        - Formats : PDF + SVG cochés, PNG décoché
        - Dimensions : 8 × 5 pouces (ratio classique single-column publication)
        - Watermark : activé
        Applique aussi une marge X auto de 50 cm⁻¹ pour un rendu propre.
        """
        self.dpi_var.set(600)
        self.fmt_png_var.set(False)
        self.fmt_pdf_var.set(True)
        self.fmt_svg_var.set(True)
        self.fig_width_var.set(8.0)
        self.fig_height_var.set(5.0)
        self.watermark_var.set(True)
        # Désactiver le fit auto de la largeur (on veut 8 pouces exact)
        if hasattr(self, 'fit_width_var'):
            self.fit_width_var.set(False)
        self.status_var.set("📖 Preset Publication appliqué : 600 DPI, PDF+SVG, 8×5″")
        self._schedule_update(delay=50)

    def _user_profile_dialog(self, force=False):
        """Affiche un dialog pour saisir/éditer le profil utilisateur.
        Retourne le dict profile si validé, None si annulé.

        Args:
            force : si True, force l'affichage même si le profil est déjà complet
                    (utilisé pour l'édition manuelle depuis un menu).
                    Sinon, n'affiche que si le profil est incomplet.
        """
        existing = _load_user_profile()
        if not force and _profile_is_complete(existing):
            return existing

        win = _Toplevel(self)
        win.title(t('profile.title'))
        win.geometry("480x340")
        win.transient(self)
        win.grab_set()
        win.resizable(False, False)
        try:
            win.lift(); win.focus_force()
        except Exception:
            pass

        frm = _Frame(win)
        frm.pack(fill=tk.BOTH, expand=True, padx=18, pady=14)

        _Label(frm, text=t('profile.intro'),
               font=('TkDefaultFont', 9), foreground='gray',
               wraplength=420, justify='left').pack(anchor='w', pady=(0, 12))

        # Variables liées
        title_var = tk.StringVar(value=existing.get('title', ''))
        fn_var    = tk.StringVar(value=existing.get('firstname', ''))
        ln_var    = tk.StringVar(value=existing.get('lastname', ''))
        email_var = tk.StringVar(value=existing.get('email', ''))

        # Grille de saisie
        grid = _Frame(frm)
        grid.pack(fill=tk.X)

        _Label(grid, text=t('profile.title_field') + " :").grid(
            row=0, column=0, sticky='w', padx=4, pady=4)
        _Entry(grid, textvariable=title_var, width=18).grid(
            row=0, column=1, sticky='w', padx=4, pady=4)
        _Label(grid, text=t('profile.title_hint'),
               font=('TkDefaultFont', 8), foreground='gray').grid(
            row=0, column=2, sticky='w', padx=4)

        _Label(grid, text=t('profile.firstname') + " * :").grid(
            row=1, column=0, sticky='w', padx=4, pady=4)
        ent_fn = _Entry(grid, textvariable=fn_var)
        ent_fn.grid(row=1, column=1, columnspan=2, sticky='ew', padx=4, pady=4)

        _Label(grid, text=t('profile.lastname') + " * :").grid(
            row=2, column=0, sticky='w', padx=4, pady=4)
        _Entry(grid, textvariable=ln_var).grid(
            row=2, column=1, columnspan=2, sticky='ew', padx=4, pady=4)

        _Label(grid, text=t('profile.email') + " * :").grid(
            row=3, column=0, sticky='w', padx=4, pady=4)
        _Entry(grid, textvariable=email_var).grid(
            row=3, column=1, columnspan=2, sticky='ew', padx=4, pady=4)

        grid.columnconfigure(1, weight=1)

        _Label(frm, text=t('profile.required_hint'),
               font=('TkDefaultFont', 8), foreground='gray').pack(anchor='w', pady=(8, 0))

        # Boutons
        btn_frm = _Frame(win)
        btn_frm.pack(fill=tk.X, padx=18, pady=(0, 14))

        result = {'profile': None}

        def _ok():
            fn = fn_var.get().strip()
            ln = ln_var.get().strip()
            email = email_var.get().strip()
            # Validation : prénom, nom, email obligatoires
            if not fn or not ln or not email:
                messagebox.showerror(t('msg.error_title'),
                                     t('profile.error_required'), parent=win)
                return
            # Validation simple email (présence de @)
            if '@' not in email or '.' not in email.split('@')[-1]:
                messagebox.showerror(t('msg.error_title'),
                                     t('profile.error_email'), parent=win)
                return
            profile = {
                'title':     title_var.get().strip(),
                'firstname': fn,
                'lastname':  ln,
                'email':     email,
            }
            _save_user_profile(profile)
            result['profile'] = profile
            win.destroy()

        _AccentButton(btn_frm, text=f"{ICONS['check']} {t('common.apply')}",
                       accent='primary', command=_ok, width=11).pack(side=tk.RIGHT, padx=4)
        _Button(btn_frm, text=t('common.cancel'), command=win.destroy,
                width=9).pack(side=tk.RIGHT, padx=4)
        win.bind('<Return>', lambda e: _ok())
        win.bind('<Escape>', lambda e: win.destroy())

        try:
            ent_fn.focus_set()
        except Exception:
            pass
        # Bloquer jusqu'à la fermeture
        self.wait_window(win)
        return result['profile']

    def _export_pdf_report(self):
        """Exporte un rapport PDF multi-pages au format A4 portrait professionnel.

        Structure :
          1. Page de garde élégante (titre, auteur, date, métadonnées encadrées)
          2. Page graphique principal (haute résolution + caption)
          3. Page(s) tableau des pics annotés (mise en page tabulaire propre)
          4. Page tableau des références utilisées
        Sauvegarde dans SAUVEGARDE/Rapports/.
        """
        n_vis_spec = sum(1 for s in self.spectra_meta if s.get('visible', False))
        n_vis_refs = sum(1 for r in self.refs if r.get('visible', True))
        if n_vis_spec == 0 and n_vis_refs == 0:
            messagebox.showwarning(t('msg.warning_title'), t('msg.save_nothing'))
            return

        # Vérifier/saisir le profil utilisateur AVANT toute écriture du PDF.
        # Si l'utilisateur annule la saisie, on annule l'export.
        user_profile = self._user_profile_dialog(force=False)
        if user_profile is None or not _profile_is_complete(user_profile):
            self.status_var.set("✗ Export PDF annulé : profil utilisateur requis.")
            return

        # Utiliser la StringVar dédiée aux rapports
        save_dir = self.rapport_save_folder_var.get().strip()
        if not save_dir:
            # Fallback : SAUVEGARDE/Rapports/
            save_root = self.save_root_var.get().strip()
            if not save_root:
                messagebox.showwarning(t('msg.warning_title'), t('msg.save_choose_folder'))
                return
            save_dir = os.path.join(save_root, "Rapports")
        os.makedirs(save_dir, exist_ok=True)
        name = safe_filename(self.save_name_var.get().strip() or "Rapport_Raman")
        pdf_path = os.path.join(save_dir, f"{name}_rapport.pdf")

        try:
            from matplotlib.backends.backend_pdf import PdfPages
        except ImportError:
            messagebox.showerror(t('msg.error_title'),
                "matplotlib.backends.backend_pdf non disponible.")
            return

        import datetime
        now = datetime.datetime.now()
        today_long = now.strftime('%d %B %Y')  # ex: "24 avril 2026"
        today_short = now.strftime('%Y-%m-%d %H:%M')

        # Le "sample" affiché sur la page de garde et dans le caption doit
        # correspondre aux dossiers d'origine des spectres VISIBLES, pas à
        # l'active sample (qui peut être différent en multi-dossiers).
        # On utilise le chemin RELATIF depuis le sample courant (ex.
        # CR-G3-05/22042026) pour montrer l'arborescence complète, plutôt
        # que juste le basename du dossier le plus profond.
        current_sf_for_report = self._current_sample_path()
        visible_specs_for_meta = [s for s in self.spectra_meta if s.get('visible', False)]
        sample_folders_seen = []
        for s in visible_specs_for_meta:
            sf = s.get('sample_folder')
            if not sf:
                continue
            # Calculer chemin relatif depuis le sample courant si possible
            if current_sf_for_report:
                try:
                    rel = os.path.relpath(sf, current_sf_for_report).replace('\\', '/')
                    if rel.startswith('..') or rel == '.':
                        # Hors du sample courant ou égal — fallback basename
                        label = os.path.basename(os.path.normpath(sf))
                    else:
                        label = rel
                except ValueError:
                    label = os.path.basename(os.path.normpath(sf))
            else:
                label = os.path.basename(os.path.normpath(sf))
            if label and label not in sample_folders_seen:
                sample_folders_seen.append(label)
        if sample_folders_seen:
            if len(sample_folders_seen) == 1:
                sample = sample_folders_seen[0]
            elif len(sample_folders_seen) <= 3:
                sample = ", ".join(sample_folders_seen)
            else:
                sample = ", ".join(sample_folders_seen[:3]) + f" (+{len(sample_folders_seen) - 3})"
        else:
            # Aucun spectre visible : fallback sur l'active sample (page de garde)
            sample = self.sample_folder_var.get() or '—'

        title = self.title_var.get().strip() or "Analyse spectrale Raman"

        # Format A4 portrait : 8.27 × 11.69 pouces (210 × 297 mm)
        A4_W, A4_H = 8.27, 11.69
        # Marges (en fraction de figure)
        MARGIN_L = 0.10
        MARGIN_R = 0.90
        MARGIN_T = 0.93
        MARGIN_B = 0.07

        try:
            with PdfPages(pdf_path) as pdf:

                # ============================================================
                # PAGE 1 — PAGE DE GARDE
                # ============================================================
                fig1 = Figure(figsize=(A4_W, A4_H))
                fig1.patch.set_facecolor('white')

                # Bandeau coloré en haut
                from matplotlib.patches import Rectangle, FancyBboxPatch
                fig1.patches.append(Rectangle((0, 0.88), 1, 0.12,
                                               facecolor='#1a5fb4',
                                               transform=fig1.transFigure,
                                               zorder=0))
                # Logo / nom application en blanc dans le bandeau
                fig1.text(0.5, 0.945, APP_NAME,
                          ha='center', va='center',
                          fontsize=22, weight='bold', color='white')
                fig1.text(0.5, 0.905, f"v{APP_VERSION}",
                          ha='center', va='center',
                          fontsize=9, color='white', alpha=0.85)

                # Titre principal du rapport
                fig1.text(0.5, 0.78, "RAPPORT D'ANALYSE",
                          ha='center', va='center',
                          fontsize=11, color='gray', weight='bold',
                          family='sans-serif')
                # Filet décoratif sous le sous-titre
                fig1.add_artist(plt.Line2D([0.30, 0.70], [0.755, 0.755],
                                            color='#1a5fb4', linewidth=1.5,
                                            transform=fig1.transFigure))
                # Titre du projet (donné par l'utilisateur ou défaut)
                fig1.text(0.5, 0.715, title,
                          ha='center', va='center',
                          fontsize=18, weight='bold', wrap=True)

                # Bloc métadonnées dans un cadre arrondi
                meta_box = FancyBboxPatch(
                    (0.12, 0.32), 0.76, 0.32,
                    boxstyle="round,pad=0.02,rounding_size=0.015",
                    facecolor='#f5f5f7', edgecolor='#d0d0d4',
                    linewidth=0.8, transform=fig1.transFigure, zorder=0)
                fig1.patches.append(meta_box)

                # Titre du bloc
                fig1.text(0.5, 0.61, "Informations de l'analyse",
                          ha='center', va='top',
                          fontsize=11, weight='bold', color='#1a5fb4')

                # Métadonnées en 2 colonnes (label : valeur)
                meta_pairs = [
                    ("Échantillon actif",   sample),
                    ("Laser échantillon",   self.sample_laser_var.get()),
                    ("Base de données",     self.database_folder_var.get() or t('match.lbl.db_root')),
                    ("Spectres affichés",   str(n_vis_spec)),
                    ("Références",          str(n_vis_refs)),
                    ("Pics annotés",        str(len(self.peaks))),
                ]
                y_start = 0.575
                for i, (label, value) in enumerate(meta_pairs):
                    y = y_start - i * 0.035
                    fig1.text(0.18, y, label + " :",
                              ha='left', va='center', fontsize=10, color='#555')
                    fig1.text(0.50, y, value,
                              ha='left', va='center', fontsize=10,
                              weight='bold', color='black')

                # Pied de page : auteur du rapport (profil utilisateur) +
                # crédit développeur + crédit IA
                fig1.text(0.5, 0.20, today_long,
                          ha='center', va='center',
                          fontsize=11, color='#555')
                fig1.add_artist(plt.Line2D([0.35, 0.65], [0.165, 0.165],
                                            color='#d0d0d4', linewidth=0.8,
                                            transform=fig1.transFigure))
                # Auteur du rapport (depuis le profil utilisateur)
                fig1.text(0.5, 0.135, _format_profile(user_profile),
                          ha='center', va='center',
                          fontsize=10, color='#222', weight='bold')
                fig1.text(0.5, 0.105, t('pdf.report_author'),
                          ha='center', va='center',
                          fontsize=8, color='gray', style='italic')
                # Crédit développeur de l'application + IA
                fig1.text(0.5, 0.07, t('app.author'),
                          ha='center', va='center',
                          fontsize=7.5, color='gray')
                fig1.text(0.5, 0.045, t('app.ai_credit'),
                          ha='center', va='center',
                          fontsize=7.5, color='gray', style='italic')

                # Bandeau bas
                fig1.patches.append(Rectangle((0, 0.0), 1, 0.025,
                                               facecolor='#1a5fb4',
                                               transform=fig1.transFigure,
                                               zorder=0))

                pdf.savefig(fig1)

                # ============================================================
                # PAGE 2 — GRAPHIQUE PRINCIPAL (rendu VECTORIEL pur)
                # ============================================================
                # Approche : on crée une figure A4, on appelle _draw_figure
                # dessus pour qu'elle dessine son contenu (qui prend toute la
                # figure par défaut), puis on REPOSITIONNE l'axe principal
                # dans la moitié haute pour libérer la place pour en-tête et
                # caption. Résultat : tout le plot reste vectoriel (qualité
                # parfaite, taille fichier réduite).
                fig2 = Figure(figsize=(A4_W, A4_H))
                fig2.patch.set_facecolor('white')

                sample_folder = self._current_sample_path()
                # Sauver et forcer temporairement les contraintes de taille à
                # A4 pour que _draw_figure ne fasse pas de set_size_inches
                # contre-productif.
                _saved_w = self.fig_width_var.get()
                _saved_h = self.fig_height_var.get()
                try:
                    self.fig_width_var.set(A4_W)
                    self.fig_height_var.set(A4_H)
                    self._draw_figure(fig2, sample_folder)
                finally:
                    self.fig_width_var.set(_saved_w)
                    self.fig_height_var.set(_saved_h)

                # Repositionner l'axe principal pour libérer espace en-tête + caption.
                # _draw_figure a fait fig.add_subplot(111) qui prend toute la zone.
                # On remet l'axe dans une position contrôlée [left, bottom, w, h].
                if fig2.axes:
                    main_ax = fig2.axes[0]
                    # x=0.10, y=0.30 (au-dessus du caption), largeur=0.80, hauteur=0.58
                    main_ax.set_position([MARGIN_L, 0.30,
                                           MARGIN_R - MARGIN_L, 0.58])

                # En-tête : titre + date à droite (par-dessus, après _draw_figure)
                fig2.text(MARGIN_L, 0.96, "Figure 1 — Spectres Raman",
                          ha='left', va='center',
                          fontsize=11, weight='bold', color='#1a5fb4')
                fig2.text(MARGIN_R, 0.96, today_short,
                          ha='right', va='center',
                          fontsize=8, color='gray')
                fig2.add_artist(plt.Line2D([MARGIN_L, MARGIN_R], [0.945, 0.945],
                                            color='#1a5fb4', linewidth=0.6,
                                            transform=fig2.transFigure))

                # ===== Caption sous le graphique =====
                visible_spectra = [s for s in self.spectra_meta
                                    if s.get('visible', False)]

                def _format_spec_with_folder(s):
                    """Retourne 'CR-G3-05 — 0027 13042026' = dossier_source — nom_fichier."""
                    spec_name = s.get('display_name') or clean_label(s['filename'])
                    sf = s.get('sample_folder')
                    if sf:
                        folder_name = os.path.basename(os.path.normpath(sf))
                        return f"{folder_name} — {spec_name}"
                    return spec_name

                if visible_spectra:
                    if len(visible_spectra) == 1:
                        s = visible_spectra[0]
                        sample_caption = _format_spec_with_folder(s)
                        laser_caption = s.get('laser', self.sample_laser_var.get())
                    else:
                        items = [_format_spec_with_folder(s) for s in visible_spectra[:3]]
                        more = f" (+{len(visible_spectra) - 3})" if len(visible_spectra) > 3 else ""
                        sample_caption = " · ".join(items) + more
                        lasers = {s.get('laser', self.sample_laser_var.get())
                                  for s in visible_spectra}
                        laser_caption = lasers.pop() if len(lasers) == 1 else "multiple"
                else:
                    sample_caption = sample
                    laser_caption = self.sample_laser_var.get()

                fig2.text(MARGIN_L, 0.25,
                          f"Échantillon : {sample_caption}",
                          ha='left', va='top',
                          fontsize=9, style='italic', color='#444', wrap=True)
                fig2.text(MARGIN_L, 0.225,
                          f"Laser : {laser_caption}  •  "
                          f"{n_vis_spec} spectre(s), {n_vis_refs} référence(s), {len(self.peaks)} pic(s)",
                          ha='left', va='top',
                          fontsize=9, style='italic', color='#444')

                # Pied de page
                fig2.text(0.5, 0.025, f"Page 2 — {APP_NAME} v{APP_VERSION}",
                          ha='center', va='center',
                          fontsize=8, color='gray')

                pdf.savefig(fig2)

                # ============================================================
                # PAGE 3+ — TABLEAU DES PICS (si présents)
                # ============================================================
                if self.peaks:
                    PEAKS_PER_PAGE = 32
                    peaks_sorted = sorted(self.peaks, key=lambda p: p['pos'])
                    total_pages = (len(peaks_sorted) - 1) // PEAKS_PER_PAGE + 1

                    for page_idx in range(0, len(peaks_sorted), PEAKS_PER_PAGE):
                        fig_p = Figure(figsize=(A4_W, A4_H))
                        fig_p.patch.set_facecolor('white')
                        page_num = page_idx // PEAKS_PER_PAGE + 1

                        # En-tête page
                        suffix = f" ({page_num}/{total_pages})" if total_pages > 1 else ""
                        fig_p.text(MARGIN_L, 0.96, f"Pics annotés{suffix}",
                                   ha='left', va='center',
                                   fontsize=11, weight='bold', color='#1a5fb4')
                        fig_p.text(MARGIN_R, 0.96,
                                   f"{len(peaks_sorted)} pic(s) au total",
                                   ha='right', va='center',
                                   fontsize=8, color='gray')
                        fig_p.add_artist(plt.Line2D([MARGIN_L, MARGIN_R], [0.945, 0.945],
                                                     color='#1a5fb4', linewidth=0.6,
                                                     transform=fig_p.transFigure))

                        # Header du tableau (avec fond coloré)
                        y_header = 0.91
                        fig_p.patches.append(Rectangle(
                            (MARGIN_L, y_header - 0.015), MARGIN_R - MARGIN_L, 0.025,
                            facecolor='#1a5fb4', transform=fig_p.transFigure,
                            zorder=0))
                        fig_p.text(0.13, y_header, "Position (cm⁻¹)",
                                   ha='left', va='center',
                                   fontsize=9.5, weight='bold', color='white')
                        fig_p.text(0.34, y_header, "Label",
                                   ha='left', va='center',
                                   fontsize=9.5, weight='bold', color='white')
                        fig_p.text(0.62, y_header, "Minéral source",
                                   ha='left', va='center',
                                   fontsize=9.5, weight='bold', color='white')

                        # Lignes du tableau (alternance gris clair / blanc)
                        row_height = 0.025
                        page_peaks = peaks_sorted[page_idx:page_idx + PEAKS_PER_PAGE]
                        for i, p in enumerate(page_peaks):
                            y_p = 0.88 - i * row_height
                            # Fond alterné
                            if i % 2 == 0:
                                fig_p.patches.append(Rectangle(
                                    (MARGIN_L, y_p - 0.011),
                                    MARGIN_R - MARGIN_L, row_height,
                                    facecolor='#f8f8fa', transform=fig_p.transFigure,
                                    zorder=0))
                            fig_p.text(0.13, y_p, f"{p['pos']:.1f}",
                                       ha='left', va='center',
                                       fontsize=9, family='monospace')
                            fig_p.text(0.34, y_p,
                                       (p.get('label', '') or '—')[:42],
                                       ha='left', va='center', fontsize=9)
                            fig_p.text(0.62, y_p,
                                       (p.get('mineral', '') or '—')[:30],
                                       ha='left', va='center', fontsize=9,
                                       style='italic', color='#444')

                        # Pied de page
                        fig_p.text(0.5, 0.025,
                                   f"Page {page_num + 2} — {APP_NAME} v{APP_VERSION}",
                                   ha='center', va='center',
                                   fontsize=8, color='gray')

                        pdf.savefig(fig_p)

                # ============================================================
                # DERNIÈRE PAGE — TABLEAU DES RÉFÉRENCES (si présentes)
                # ============================================================
                if self.refs:
                    fig_r = Figure(figsize=(A4_W, A4_H))
                    fig_r.patch.set_facecolor('white')

                    fig_r.text(MARGIN_L, 0.96, "Références utilisées",
                               ha='left', va='center',
                               fontsize=11, weight='bold', color='#1a5fb4')
                    fig_r.text(MARGIN_R, 0.96, f"{len(self.refs)} référence(s)",
                               ha='right', va='center',
                               fontsize=8, color='gray')
                    fig_r.add_artist(plt.Line2D([MARGIN_L, MARGIN_R], [0.945, 0.945],
                                                  color='#1a5fb4', linewidth=0.6,
                                                  transform=fig_r.transFigure))

                    # Header (cyan/bleu)
                    y_header = 0.91
                    fig_r.patches.append(Rectangle(
                        (MARGIN_L, y_header - 0.015), MARGIN_R - MARGIN_L, 0.025,
                        facecolor='#1a5fb4', transform=fig_r.transFigure,
                        zorder=0))
                    fig_r.text(0.115, y_header, "#",
                               ha='left', va='center',
                               fontsize=9.5, weight='bold', color='white')
                    fig_r.text(0.16, y_header, "Minéral",
                               ha='left', va='center',
                               fontsize=9.5, weight='bold', color='white')
                    fig_r.text(0.36, y_header, "Fichier source",
                               ha='left', va='center',
                               fontsize=9.5, weight='bold', color='white')
                    fig_r.text(0.82, y_header, "Laser",
                               ha='left', va='center',
                               fontsize=9.5, weight='bold', color='white')

                    row_height = 0.025
                    for i, r in enumerate(self.refs):
                        y_r = 0.88 - i * row_height
                        if y_r < 0.05:
                            break
                        if i % 2 == 0:
                            fig_r.patches.append(Rectangle(
                                (MARGIN_L, y_r - 0.011),
                                MARGIN_R - MARGIN_L, row_height,
                                facecolor='#f8f8fa', transform=fig_r.transFigure,
                                zorder=0))
                        fig_r.text(0.115, y_r, str(i + 1),
                                   ha='left', va='center', fontsize=9)
                        fig_r.text(0.16, y_r, r['mineral'][:22],
                                   ha='left', va='center',
                                   fontsize=9, weight='bold')
                        fig_r.text(0.36, y_r, r['filename'][:55],
                                   ha='left', va='center',
                                   fontsize=8, family='monospace', color='#444')
                        fig_r.text(0.82, y_r, r['laser'],
                                   ha='left', va='center',
                                   fontsize=9, style='italic', color='#1a5fb4')

                    fig_r.text(0.5, 0.025, f"{APP_NAME} v{APP_VERSION}",
                               ha='center', va='center',
                               fontsize=8, color='gray')

                    pdf.savefig(fig_r)

                # ============ MÉTADONNÉES PDF ============
                d = pdf.infodict()
                d['Title'] = title
                d['Author'] = _format_profile(user_profile)
                d['Creator'] = f"{APP_NAME} v{APP_VERSION}"
                d['Subject'] = "Rapport d'analyse Raman"
                d['CreationDate'] = now

        except Exception as e:
            messagebox.showerror(t('msg.error_title'),
                                  f"Erreur d'export PDF :\n{e}")
            return

        self.status_var.set(f"✓ Rapport PDF généré : {os.path.basename(pdf_path)}")
        messagebox.showinfo(t('msg.save_ok'),
                             f"Rapport PDF :\n\n{pdf_path}")

    def _draw_figure_into_ax(self, ax, sample_folder, fig):
        """Helper pour dessiner le contenu du plot principal dans un axe donné.
        Utilisé par _export_pdf_report pour insérer le graphique dans une page A4
        avec marges contrôlées (sans tight_layout qui prendrait toute la page).
        """
        # On crée une figure temporaire qu'on dessine, puis on copie l'axe
        tmp_fig = Figure(figsize=(8, 5.5), dpi=120)
        self._draw_figure(tmp_fig, sample_folder)
        # Récupérer l'axe principal de la figure temporaire et copier ses contenus
        tmp_axes = tmp_fig.axes
        if not tmp_axes:
            return
        tmp_ax = tmp_axes[0]
        # Copier les courbes
        for line in tmp_ax.get_lines():
            ax.plot(line.get_xdata(), line.get_ydata(),
                    color=line.get_color(),
                    linestyle=line.get_linestyle(),
                    linewidth=line.get_linewidth(),
                    alpha=line.get_alpha() if line.get_alpha() else 1.0,
                    label=line.get_label(), zorder=line.get_zorder())
        # Copier les axes
        ax.set_xlim(tmp_ax.get_xlim())
        ax.set_ylim(tmp_ax.get_ylim())
        ax.set_xlabel(tmp_ax.get_xlabel())
        ax.set_ylabel(tmp_ax.get_ylabel())
        # Légende
        if tmp_ax.get_legend() is not None:
            ax.legend(loc='upper right', fontsize=7,
                       frameon=True, framealpha=0.95)
        # Grille discrète
        ax.grid(alpha=0.25, linewidth=0.4)

    def _reset_all(self):
        # Si l'utilisateur a des modifs non sauvegardées, lui proposer de sauver
        if not self._prompt_save_if_dirty(title=t('msg.reset_title')):
            return
        if not messagebox.askyesno(t('msg.reset_title'), t('msg.reset_body')):
            return
        self._push_undo(t('action.reset_all'))

        # Données
        self.spectrum_files = []
        # Remettre tous les spectres à invisible
        for s in self.spectra_meta:
            s['visible'] = False
            s['display_name'] = clean_label(s['filename'])
        self._refresh_spectra_tree()
        self.refs = []
        self._refresh_refs_list()
        self.peaks = []
        self._refresh_peaks_tree()
        # Effacer aussi les annotations libres
        self.annotations = []

        # Options remises à leur défaut
        self.title_var.set('')
        self.x_margin_var.set(DEFAULTS['x_margin'])
        self.sample_laser_var.set(DEFAULTS['sample_laser'])
        self.default_ref_laser_var.set(DEFAULTS['ref_laser'])
        self.xmin_var.set(''); self.xmax_var.set('')
        self.ymin_var.set(''); self.ymax_var.set('')
        self.fig_width_var.set(DEFAULTS['fig_width'])
        self.fig_height_var.set(DEFAULTS['fig_height'])
        self.fit_width_var.set(True)
        self.label_mode_var.set(DEFAULTS['label_mode'])
        self.color_by_mineral_var.set(True)
        self.show_peak_marker_var.set(True)
        self.auto_stagger_var.set(True)
        self.sample_palette_var.set(DEFAULTS['sample_palette'])
        self.ref_palette_var.set(DEFAULTS['ref_palette'])
        # Reset offset horizontal samples
        self.sample_x_offset_var.set(0.0)

        # Sauvegarde (on garde le dossier choisi par l'utilisateur)
        self.save_name_var.set(DEFAULTS['save_name'])
        self.dpi_var.set(DEFAULTS['dpi'])

        # Oublier le chemin du projet précédent : sinon Ctrl+S écraserait
        # l'ancien fichier alors qu'on est sur un projet tout neuf.
        self._current_project_path = None
        self._mark_dirty(False)

        self.status_var.set("↺  Tout réinitialisé.")
        self._schedule_update()

    # ============================================================
    # LIVE UPDATE
    # ============================================================
    def _setup_auto_updates(self):
        # Note : fig_width_var et fig_height_var ont un traitement spécial :
        # - fig_width_var est modifiée en direct par le mode fit_width_var quand
        #   l'utilisateur redimensionne. Ça déclencherait 60 redraws/sec.
        # - Un redimensionnement manuel DOIT re-render le plot (fix bug : sinon
        #   rien ne se passait quand fit_width était désactivé).
        for var in (self.title_var, self.x_margin_var,
                    self.sample_laser_var,
                    self.xmin_var, self.xmax_var, self.ymin_var, self.ymax_var,
                    self.label_mode_var, self.color_by_mineral_var,
                    self.show_peak_marker_var, self.auto_stagger_var,
                    self.sample_palette_var, self.ref_palette_var,
                    self.sample_linestyle_var, self.ref_linestyle_var):
            var.trace_add('write', lambda *a: self._schedule_update())

        # Traces spéciales pour les dimensions :
        # On ne déclenche update que si le changement vient d'une saisie manuelle
        # (et pas d'un resize automatique via fit_width)
        def _on_dim_change(*_args):
            # Si fit_width est activé, le changement vient du resize auto,
            # donc on ignore (sinon boucle infinie de redraws).
            if self.fit_width_var.get():
                return
            # Sinon, re-render avec les nouvelles dimensions
            self._schedule_update(delay=100)
        self.fig_width_var.trace_add('write', _on_dim_change)
        self.fig_height_var.trace_add('write', _on_dim_change)
        # Quand on coche/décoche fit_width, toujours re-render
        self.fit_width_var.trace_add('write',
            lambda *a: self._schedule_update(delay=50))

        # Quand l'utilisateur modifie xmin/xmax manuellement, désactiver l'état
        # "enfoncé" du bouton Zoom (si celui-ci est actif)
        def _on_xlim_change(*_args):
            if getattr(self, '_zoom_active', False):
                # Vérifier si les bornes correspondent encore à un pic zoomé
                try:
                    cur_xmin = float(self.xmin_var.get()) if self.xmin_var.get() else None
                    cur_xmax = float(self.xmax_var.get()) if self.xmax_var.get() else None
                except ValueError:
                    cur_xmin = cur_xmax = None
                sel = self.peaks_tree.selection() if hasattr(self, 'peaks_tree') else []
                if not sel or cur_xmin is None or cur_xmax is None:
                    self._set_zoom_button_active(False)
                    return
                try:
                    positions = [self.peaks[int(s)]['pos'] for s in sel]
                    new_xmin = min(positions) - 50
                    new_xmax = max(positions) + 50
                    if abs(cur_xmin - new_xmin) >= 1 or abs(cur_xmax - new_xmax) >= 1:
                        self._set_zoom_button_active(False)
                except Exception:
                    self._set_zoom_button_active(False)
        self.xmin_var.trace_add('write', _on_xlim_change)
        self.xmax_var.trace_add('write', _on_xlim_change)

    def _setup_keyboard_shortcuts(self):
        """Raccourcis clavier.

        IMPORTANT — Cas Toplevel (fenêtre fille de Match Search) :
        On ne peut PAS utiliser bind_all() car ça enregistrerait les
        raccourcis sur la racine Tk partagée, ce qui écraserait les
        raccourcis de Match Search (par ex. Ctrl+S de Match Search se
        retrouverait à appeler save_project() de Plot Builder qui ouvre
        un dialogue .rpm dans le mauvais dossier).

        Solution : si on est en Toplevel, on utilise bind() (instance)
        qui ne s'applique qu'à cette fenêtre. Sinon (fenêtre principale),
        bind_all() reste OK car c'est la seule fenêtre.
        """
        is_toplevel = getattr(self, '_is_toplevel_window', False)
        bind_method = self.bind if is_toplevel else self.bind_all

        bind_method('<Control-s>', lambda e: self.save_project())
        bind_method('<Control-S>', lambda e: self.save_project_as())
        bind_method('<Control-o>', lambda e: self.load_project())
        bind_method('<Control-O>', lambda e: self.load_project())
        bind_method('<Control-e>', lambda e: self.save_figure())
        bind_method('<Control-E>', lambda e: self.save_figure())
        bind_method('<F5>', lambda e: self.update_plot())
        # Ctrl+R = tout réinitialiser (moins dangereux que juste R)
        bind_method('<Control-r>', lambda e: self._reset_all())
        bind_method('<Control-R>', lambda e: self._reset_all())
        # Ctrl+Q = quitter (avec prompt si dirty)
        bind_method('<Control-q>', lambda e: self._on_close_request())
        bind_method('<Control-Q>', lambda e: self._on_close_request())
        # Undo / Redo
        bind_method('<Control-z>', lambda e: self.undo())
        bind_method('<Control-Z>', lambda e: self.undo())
        bind_method('<Control-y>', lambda e: self.redo())
        bind_method('<Control-Y>', lambda e: self.redo())

        # Afficher le tutoriel au tout premier lancement (pas au suivant)
        self._maybe_show_first_launch_tutorial()

        # Activer le drag & drop si tkinterdnd2 est disponible
        self._setup_drag_and_drop()

    # ============================================================
    # CLIC SUR LE GRAPHIQUE (ajout de pic)
    # ============================================================
    def _on_plot_click(self, event):
        """Handler unifié du plot :
        - Clic gauche en mode annotation : créer annotation
        - Clic gauche sur annotation : commencer drag
        - Clic droit : menu contextuel (pics ou annotations selon ce qui est cliqué)
        """
        if event.inaxes is None or event.xdata is None:
            return
        # Si la toolbar est en mode zoom ou pan, ne rien faire
        if self.toolbar.mode:
            return

        x_clicked = float(event.xdata)
        y_clicked = float(event.ydata) if event.ydata is not None else 0.0

        # --- Clic gauche en mode annotation : créer une nouvelle ---
        if event.button == 1 and self._annotation_mode:
            self._create_annotation_at(x_clicked, y_clicked)
            self._annotation_mode = False
            self.status_var.set(t('status.ready'))
            try:
                self.canvas.get_tk_widget().configure(cursor='')
            except Exception:
                pass
            return

        # --- Clic gauche : chercher si on clique sur une annotation ---
        if event.button == 1:
            # Vérifier si on a cliqué sur une annotation existante
            for i, ann in enumerate(self.annotations):
                artist = ann.get('_artist')
                if artist is None:
                    continue
                contains, _ = artist.contains(event)
                if contains:
                    # Double-clic gauche sur annotation = ouvre l'édition
                    if getattr(event, 'dblclick', False):
                        self._edit_annotation_dialog(i)
                        return
                    # Sinon : démarrer le drag — pousser l'état AVANT modification
                    self._push_undo(t('action.move_annotation'))
                    self._drag_annotation_idx = i
                    self._drag_start_xy = (x_clicked, y_clicked)
                    self._drag_orig_xy = (ann['x'], ann['y'])
                    try:
                        self.canvas.get_tk_widget().configure(cursor='fleur')
                    except Exception:
                        pass
                    return
            return

        # --- Clic droit : menu contextuel ---
        if event.button != 3:
            return

        # Vérifier si on clique sur une annotation
        for i, ann in enumerate(self.annotations):
            artist = ann.get('_artist')
            if artist is None:
                continue
            contains, _ = artist.contains(event)
            if contains:
                # Menu contextuel annotation
                x_screen, y_screen = self.winfo_pointerxy()
                menu = tk.Menu(self, tearoff=0)
                menu.add_command(
                    label=f"{ICONS['edit']} {t('ctx.edit_annotation')}",
                    command=lambda idx=i: self._edit_annotation_dialog(idx))
                menu.add_command(
                    label=f"{ICONS['trash']} {t('ctx.remove_annotation')}",
                    command=lambda idx=i: self._remove_annotation(idx))
                try:
                    menu.tk_popup(x_screen, y_screen)
                finally:
                    menu.grab_release()
                return

        # Sinon, menu contextuel pic (ancien comportement)
        nearest_idx = None
        nearest_dist = float('inf')
        for i, p in enumerate(self.peaks):
            d = abs(p['pos'] - x_clicked)
            if d < nearest_dist:
                nearest_dist = d
                nearest_idx = i

        x_screen, y_screen = self.winfo_pointerxy()
        menu = tk.Menu(self, tearoff=0)
        menu.add_command(
            label=t('ctx.add_peak', pos=x_clicked),
            command=lambda: self._quick_add_peak(x_clicked))
        if nearest_idx is not None and nearest_dist < 50:
            p_near = self.peaks[nearest_idx]
            label_info = p_near.get('label') or p_near.get('mineral') or '?'
            menu.add_separator()
            menu.add_command(
                label=t('ctx.edit_nearest', pos=p_near['pos'], label=label_info[:20]),
                command=lambda: self._edit_peak_by_index(nearest_idx))
            menu.add_command(
                label=t('ctx.remove_peak', pos=p_near['pos']),
                command=lambda: self._remove_peak_by_index(nearest_idx))
        # Ajouter "Annoter ici" en bas
        menu.add_separator()
        menu.add_command(
            label=f"🖊️  {t('ctx.add_annotation_here', pos=x_clicked)}",
            command=lambda: self._create_annotation_at(x_clicked, y_clicked))
        try:
            menu.tk_popup(x_screen, y_screen)
        finally:
            menu.grab_release()

    def _on_plot_motion(self, event):
        """Déplacement souris : si une annotation est en cours de drag, la suivre."""
        if self._drag_annotation_idx is None:
            return
        if event.inaxes is None or event.xdata is None or event.ydata is None:
            return
        idx = self._drag_annotation_idx
        if idx >= len(self.annotations):
            self._drag_annotation_idx = None
            return
        # Calculer le delta et appliquer à la position originale
        dx = float(event.xdata) - self._drag_start_xy[0]
        dy = float(event.ydata) - self._drag_start_xy[1]
        new_x = self._drag_orig_xy[0] + dx
        new_y = self._drag_orig_xy[1] + dy
        self.annotations[idx]['x'] = new_x
        self.annotations[idx]['y'] = new_y
        # Déplacer directement l'artist matplotlib sans re-dessiner toute la figure
        artist = self.annotations[idx].get('_artist')
        if artist is not None:
            try:
                artist.set_position((new_x, new_y))
                self.canvas.draw_idle()
            except Exception:
                pass

    def _on_plot_release(self, event):
        """Fin du drag : on relâche et on marque dirty."""
        if self._drag_annotation_idx is None:
            return
        self._drag_annotation_idx = None
        self._drag_start_xy = None
        self._drag_orig_xy = None
        try:
            self.canvas.get_tk_widget().configure(cursor='')
        except Exception:
            pass
        self._mark_dirty(True)

    def _quick_add_peak(self, pos):
        """Ajoute un pic à la position donnée, avec dialog pour label/mineral."""
        self._push_undo(t('action.add_peak'))
        self.peaks.append(self._new_peak_dict(pos=pos))
        self._refresh_peaks_tree()
        self._schedule_update()
        # Ouvrir le dialog d'édition du pic tout juste ajouté
        new_idx = len(self.peaks) - 1
        # Sélectionner + éditer
        try:
            self.peaks_tree.selection_set(str(new_idx))
            self._edit_peak_dialog()
        except Exception:
            pass

    # ============================================================
    # ANNOTATIONS LIBRES SUR LE GRAPHIQUE
    # ============================================================
    def _start_annotation_mode(self):
        """Active le mode annotation : le prochain clic gauche créera une annotation."""
        self._annotation_mode = True
        self.status_var.set("🖊️  " + t('annotation.click_to_place'))
        try:
            self.canvas.get_tk_widget().configure(cursor='crosshair')
        except Exception:
            pass

    def _create_annotation_at(self, x, y):
        """Ouvre un dialog pour saisir le texte, puis crée l'annotation à (x, y).
        Supporte maintenant le choix couleur du texte, du fond de boîte et du
        contour de boîte."""
        win = _Toplevel(self)
        win.title(t('annotation.dialog_title'))
        win.geometry("500x450")
        win.transient(self)
        win.grab_set()
        win.resizable(False, False)
        try:
            win.lift(); win.focus_force()
        except Exception:
            pass

        frm = _Frame(win)
        frm.pack(fill=tk.BOTH, expand=True, padx=16, pady=14)

        _Label(frm, text=t('annotation.position_info', x=x, y=y),
               font=('TkDefaultFont', 9),
               foreground='gray').pack(anchor='w')

        _Label(frm, text=t('annotation.text_label'),
               font=('TkDefaultFont', 10, 'bold')).pack(anchor='w', pady=(10, 2))
        text_var = tk.StringVar()
        ent = _Entry(frm, textvariable=text_var)
        ent.pack(fill=tk.X, pady=2, ipady=3)
        try:
            ent.focus_set()
        except Exception:
            pass

        # Options : taille, boîte, couleurs
        opt_frame = _LabelFrame(frm, text=" " + t('annotation.options') + " ")
        opt_frame.pack(fill=tk.X, pady=(12, 4))
        opt_in = _lf_inner(opt_frame)

        # Ligne 1 : taille + case boîte
        _Label(opt_in, text=t('annotation.fontsize')).grid(row=0, column=0, sticky='w', padx=6, pady=4)
        fontsize_var = tk.IntVar(value=10)
        _Spinbox(opt_in, from_=6, to=24, increment=1,
                 textvariable=fontsize_var, width=8).grid(row=0, column=1, sticky='w', padx=6, pady=4)

        box_var = tk.BooleanVar(value=True)
        _Checkbutton(opt_in, text=t('annotation.with_box'),
                     variable=box_var).grid(row=0, column=2, sticky='w', padx=12, columnspan=2)

        # Ligne 2 : couleur texte + aperçu cliquable
        _Label(opt_in, text=t('annotation.text_color')).grid(row=1, column=0, sticky='w', padx=6, pady=4)
        text_color_var = tk.StringVar(value='#000000')
        text_color_swatch = tk.Frame(opt_in, bg=text_color_var.get(),
                                       width=30, height=22,
                                       relief='solid', borderwidth=1)
        text_color_swatch.grid(row=1, column=1, sticky='w', padx=6, pady=4)
        text_color_swatch.grid_propagate(False)

        def _pick_text_color():
            from tkinter import colorchooser
            result = colorchooser.askcolor(color=text_color_var.get(),
                                            title=t('annotation.text_color'),
                                            parent=win)
            if result and result[1]:
                text_color_var.set(result[1])
                text_color_swatch.configure(bg=result[1])

        _Button(opt_in, text=t('common.choose'),
                command=_pick_text_color).grid(row=1, column=2, sticky='w', padx=6, pady=4)

        # Ligne 3 : couleur fond boîte
        _Label(opt_in, text=t('annotation.box_fill')).grid(row=2, column=0, sticky='w', padx=6, pady=4)
        box_fill_var = tk.StringVar(value='#ffffff')
        box_fill_swatch = tk.Frame(opt_in, bg=box_fill_var.get(),
                                     width=30, height=22,
                                     relief='solid', borderwidth=1)
