    # ============================================================
    # DRAG & DROP
    # ============================================================
    def _setup_drag_and_drop(self):
        """Active le DnD natif si tkinterdnd2 est installé."""
        if not HAS_DND:
            return
        try:
            self.drop_target_register(DND_FILES)
            self.dnd_bind('<<Drop>>', self._on_drop_files)
        except Exception as e:
            print(f"⚠ DnD Match Search init failed : {e}")

    def _on_drop_files(self, event):
        """Handler du drop : .rms ouvre projet, .txt ouvre onglet."""
        raw = event.data
        if not raw:
            return
        # Parser les chemins (gestion des accolades pour espaces)
        files = []
        i = 0
        while i < len(raw):
            ch = raw[i]
            if ch == '{':
                end = raw.find('}', i)
                if end > i:
                    files.append(raw[i+1:end]); i = end + 1
                else:
                    i += 1
            elif ch.strip():
                end = raw.find(' ', i)
                if end < 0:
                    files.append(raw[i:]); break
                files.append(raw[i:end]); i = end
            else:
                i += 1

        if not files:
            return

        rms_files = [f for f in files if f.lower().endswith('.rms')]
        txt_files = [f for f in files if f.lower().endswith('.txt')]

        # Priorité au .rms (charge un projet)
        if rms_files:
            if len(rms_files) > 1:
                messagebox.showinfo(t('msg.title.info'),
                    t('match.dlg.multi_rms_dropped', n=len(rms_files)),
                    parent=self)
            if not self._prompt_save_if_dirty(t('match.action.open_project')):
                return
            self._load_project_path(rms_files[0])
            return

        if txt_files:
            n_opened = 0
            for f in txt_files:
                if not os.path.isfile(f):
                    continue
                # Vérifier si onglet déjà ouvert pour ce fichier
                existing = None
                for ts in self.tabs.values():
                    if os.path.normpath(ts.spectrum_path) == os.path.normpath(f):
                        existing = ts; break
                if existing:
                    self.notebook.select(existing.frame)
                    continue
                # Charger et ouvrir
                try:
                    data = np.loadtxt(f)
                    if data.ndim == 1 or data.shape[1] < 2:
                        continue
                    x, y = data[:, 0], data[:, 1]
                    y = np.asarray(y, dtype=float)
                    ymin, ymax = float(y.min()), float(y.max())
                    if ymax - ymin > 1e-10:
                        y = (y - ymin) / (ymax - ymin)
                except Exception:
                    continue
                ts = _TabState(spectrum_path=f, x=x, y=y, parent_app=self)
                existing_names = {t.spectrum_name for t in self.tabs.values()}
                tab_label = ts.spectrum_name
                if tab_label in existing_names:
                    parent = os.path.basename(os.path.dirname(f))
                    tab_label = f"{parent}/{ts.spectrum_name}"
                self._build_tab_ui(ts, tab_label)
                ts.add_curve(label='Brut', history='[Brut]', kind='raw',
                              x=x, y=y, color='black', linestyle='-')
                self._refresh_curves_tree(ts)
                self._refresh_plot(ts)
                if n_opened == 0:
                    self.notebook.select(ts.frame)
                n_opened += 1
            if n_opened > 0:
                self._mark_dirty(True)
                self.status_var.set(t('match.status.tabs_dnd', n=n_opened))

    # ============================================================
    # TUTORIEL + ABOUT (réutilise les helpers de cfg)
    # ============================================================
    def _maybe_show_first_launch_tutorial(self):
        """Affiche le tutoriel au tout premier lancement Match Search."""
        try:
            cfg = os.path.join(os.path.expanduser('~'), '.raman_plot_builder.cfg')
            if os.path.isfile(cfg):
                with open(cfg, 'r', encoding='utf-8') as f:
                    data = json.load(f)
                if data.get('match_tutorial_shown'):
                    return
        except Exception:
            pass
        self.after(800, self._show_first_launch_tutorial)

    def _show_first_launch_tutorial(self):
        """Dialog de bienvenue Match Search avec un tour guidé en 5 étapes."""
        win = _Toplevel(self)
        win.title(t('match.dlg.welcome_title'))
        win.geometry("700x580")
        win.transient(self)
        win.grab_set()
        win.resizable(False, False)
        try:
            win.lift(); win.focus_force()
        except Exception:
            pass

        header = _Frame(win); header.pack(fill=tk.X, padx=20, pady=(20, 8))
        _Label(header, text=t('match.tuto.title'),
               font=('TkDefaultFont', 14, 'bold')).pack(anchor='center')
        _Label(header, text=t('match.tuto.module_v', version=APP_VERSION),
               font=('TkDefaultFont', 9), foreground='gray').pack(
                   anchor='center', pady=(0, 4))

        body = _Frame(win); body.pack(fill=tk.BOTH, expand=True, padx=20, pady=4)

        steps = [
            ("1.", t('match.tuto.step1_title'), t('match.tuto.step1_desc')),
            ("2.", t('match.tuto.step2_title'), t('match.tuto.step2_desc')),
            ("3.", t('match.tuto.step3_title'), t('match.tuto.step3_desc')),
            ("4.", t('match.tuto.step4_title'), t('match.tuto.step4_desc')),
            ("5.", t('match.tuto.step5_title'), t('match.tuto.step5_desc')),
        ]
        for num, title, desc in steps:
            row = _Frame(body); row.pack(fill=tk.X, pady=4)
            _Label(row, text=num, font=('TkDefaultFont', 14, 'bold'),
                   foreground='#1a5fb4', width=3).pack(side=tk.LEFT, anchor='n')
            txt_col = _Frame(row); txt_col.pack(side=tk.LEFT, fill=tk.X, expand=True)
            _Label(txt_col, text=title,
                   font=('TkDefaultFont', 10, 'bold')).pack(anchor='w')
            _Label(txt_col, text=desc, justify='left',
                   font=('TkDefaultFont', 9), foreground='#444',
                   wraplength=580).pack(anchor='w', pady=(1, 0))

        # Footer : checkbox + bouton
        footer = _Frame(win); footer.pack(fill=tk.X, padx=20, pady=(8, 16))
        cfg_path = os.path.join(os.path.expanduser('~'), '.raman_plot_builder.cfg')
        already_hidden = False
        try:
            if os.path.isfile(cfg_path):
                with open(cfg_path, 'r', encoding='utf-8') as f:
                    _data_init = json.load(f)
                already_hidden = bool(_data_init.get('match_tutorial_shown', False))
        except Exception:
            pass
        dont_show = tk.BooleanVar(value=already_hidden)
        _Checkbutton(footer, text=t('tuto.dont_show'),
                     variable=dont_show).pack(side=tk.LEFT)

        def _close():
            try:
                data = {}
                if os.path.isfile(cfg_path):
                    try:
                        with open(cfg_path, 'r', encoding='utf-8') as f:
                            data = json.load(f)
                    except Exception:
                        data = {}
                data['match_tutorial_shown'] = bool(dont_show.get())
                with open(cfg_path, 'w', encoding='utf-8') as f:
                    json.dump(data, f)
            except Exception:
                pass
            win.destroy()

        _AccentButton(footer, text=t('match.tuto.btn_start'), accent='primary',
                       command=_close, width=14).pack(side=tk.RIGHT)
        win.bind('<Escape>', lambda e: _close())
        win.bind('<Return>', lambda e: _close())
        win.protocol('WM_DELETE_WINDOW', _close)

